                ));
            }
        };
        let hash = contents.trim();
        if hash.len() != 32 || !hash.bytes().all(|byte| byte.is_ascii_hexdigit()) {
            return PinConfiguration::Invalid(format!(
                "PIN 配置 {} 无效；请重新运行 `aow pin`",
                path.display()
            ));
        }
        PinConfiguration::Configured(hash.to_ascii_lowercase())
    }
}

