        )
        .route("/m", get(aow_root))
        .route("/m/", get(aow_root))
        .route("/fs", get(fs_root_redirect))
        .route("/fs/", get(fs_root))
        .route("/fs/{*path}", get(fs_path))
        .route("/help", get(help_page))
        .merge(terminal::routes())
        .merge(aow::routes())
        .merge(pull_requests::routes())
        .merge(notifications::routes())
        .merge(im_api::routes())
