                .any(|entry| entry["name"] == "sample %20.txt")
        );

        let read = app
            .clone()
            .oneshot(
                Request::get(format!("/api/fs/text{encoded}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(read.status(), StatusCode::OK);
