                    }
                    assert!(
                        tokio::time::Instant::now() < deadline,
                        "expected {expected:?}: {body}"
                    );
                    tokio::time::sleep(Duration::from_millis(50)).await;
                }
                let all = manager.agents(None).await.unwrap();
                assert_eq!(all.agents.get(&tabs[1].panes[0].id), Some(&None));
                if expected.is_some() {
