            && let Err(error) = std::fs::remove_dir_all(&self.directory)
            && error.kind() != std::io::ErrorKind::NotFound
        {
            tracing::debug!(
                %error,
                directory = %self.directory.display(),
                "failed to remove temporary clipboard image directory"
            );
        }
    }
