        return PathBuf::from(runtime_dir)
            .join("aow-terminald")
            .join("terminald.sock");
    }
    let uid = unsafe { libc::geteuid() };
    PathBuf::from(format!("/tmp/aow-terminald-{uid}/terminald.sock"))
}

