    assert.equal(state.settings.notes_base, '/notes');
    assert.deepEqual(state.settings.execution_path, ['/usr/local/bin', '/usr/bin', '/bin']);
    assert.deepEqual(state.writes, [], 'display preferences must never save file contents');
  });

