    JSON.stringify({ version: 1, notes_base: join(temporary, "notes") }),
  );
  start("aow-terminald", ["--socket", socket]);
  for (let count = 0; count < 100; count++) {
    if (
      await stat(socket).then(
        () => true,
        () => false,
      )
    )
