    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  const server = start("aow-server", [
    "--host",
    "127.0.0.1",
    "--port",
    "0",
    "--state-dir",
    stateDir,
    "--terminald-socket",
    socket,
