+            .trim();
+        (!id.is_empty()
+            && id.len() <= 256
+            && !id.starts_with('-')
+            && id
+                .bytes()
+                .all(|ch| ch.is_ascii_alphanumeric() || b"_-".contains(&ch)))
+        .then(|| id.to_owned())
