+const SUMMARY_PREFIXES: [&str; 2] = [
+    "[CONTEXT COMPACTION — REFERENCE ONLY]",
+    "[CONTEXT SUMMARY]:",
+];
+const PRIOR: &str = "[PRIOR CONTEXT — for reference only; not a new message]";
+const SUMMARY: &str = "[END OF PRIOR CONTEXT — COMPACTION SUMMARY BELOW]";
