                    add_assistant_message(
                        draft,
                        SnapshotMessage {
                            text,
                            timestamp: timestamp.clone(),
                        },
                        Some(if terminal {
                            "final_answer"
                        } else {
                            "commentary"
                        }),
                        1,
                    );
                }
