            &home.join("sessions/named.jsonl"),
            &cwd,
            "first prompt",
            1_725_100_000_000,
            false,
            "first prompt",
            Some("cli"),
            None,
            None,
            None,
        );
        write(
            &home.join("session_index.jsonl"),
            "{\"id\":\"named\",\"thread_name\":\"old name\"}\n{\"id\":\"named\",\"thread_name\":\"renamed session\"}\n{partial",
        );
