        task_revision: task.revision,
        task_name: task.input.name.clone(),
        agent: task.input.agent,
        source,
        variables: (source == RunSource::Manual).then(Default::default),
        status: RunStatus::Preparing,
        started_at: Utc::now(),
        finished_at: None,
        workspace_path: None,
        branch: None,
        session_id: None,
        agent_pid: None,
        agent_command: None,
        exit_code: None,
        message: None,
        preparation_ms: None,
        session_acquired_ms: None,
