        assert_eq!(
            detail.configuration.prompt,
            "检查 🧪 {{分支}} / {{分支}} / {{保持原文}}"
        );
        assert!(store.take_manual_request(&task.id, id).unwrap().is_none());
    }
    assert_eq!(
        store.get_task(&task.id).unwrap().input.prompt,
        task.input.prompt
    );
}

