            activePath={sidebarDocument?.explorerSource === 'project' ? sidebarDocument.path : undefined}
            lockedRoot titleCase renameDirectories onRootChange={() => undefined} onOpenFile={(entry) => void openExplorerFile(entry, 'project')}
