  })), [openPullRequests]);
  const ownedCenterTabs = useMemo(() => groupWorkspaceTabs([
    ...(browserTab ? [{ id: 'system-files', kind: 'browser' as const, label: '系统文件浏览器', targetId: 'system-files' }] : []),
