        );

        provider(&app, "1/0").await;
        assert_eq!(request(&app, "GET", &endpoint, Value::Null).await.1, avatar);
        provider(&app, "{'avatar_url':None}").await;
        assert!(request(&app, "GET", &endpoint, Value::Null).await.1["avatar_url"].is_null());
        assert!(manager.project(id).await.unwrap().avatar_url.is_none());

        manager.lock().unwrap().projects[0].builtin = true;
        provider(
            &app,
            "{'avatar_url':'https://avatars.example.com/should-not-load.png'}",
        )
        .await;
        assert!(request(&app, "GET", &endpoint, Value::Null).await.1["avatar_url"].is_null());
        assert_eq!(
            request(&app, "GET", "/api/aow/projects/missing/avatar", Value::Null)
                .await
                .0,
            StatusCode::NOT_FOUND
        );
    }
}

use super::*;
use crate::operations::{Handle, Spec};
use aow_operation_log::{Level, Outcome};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(super) enum RemovalStatus {
    Queued,
    Running,
    Succeeded,
    Failed,
    Interrupted,
}

impl RemovalStatus {
    fn active(self) -> bool {
        matches!(self, Self::Queued | Self::Running)
    }
}

#[derive(Debug, Clone, Deserialize)]
pub(super) struct RemovalRequest {
    pub path: String,
    #[serde(default)]
    pub force: bool,
}

#[derive(Debug, Deserialize)]
pub(super) struct BatchRequest {
    items: Vec<RemovalRequest>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub(super) struct RemovalItem {
    path: String,
    force: bool,
    status: RemovalStatus,
    error: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub(super) struct RemovalJob {
    id: String,
    project_id: String,
    created_at: String,
    items: Vec<RemovalItem>,
    #[serde(skip)]
    finished_at: Option<std::time::Instant>,
}

pub(super) struct RemovalJobs {
    jobs: Mutex<Vec<RemovalJob>>,
    project_locks: Mutex<HashMap<String, Arc<tokio::sync::Mutex<()>>>>,
    permits: tokio::sync::Semaphore,
}

impl RemovalJobs {
    pub fn in_memory() -> Self {
        Self {
            jobs: Mutex::new(Vec::new()),
            project_locks: Mutex::new(HashMap::new()),
            permits: tokio::sync::Semaphore::new(2),
        }
    }

    fn lock(&self) -> Result<MutexGuard<'_, Vec<RemovalJob>>, AowError> {
        let mut jobs = self.jobs.lock().map_err(|_| AowError::Poisoned)?;
        // A short grace period lets clients consume final results. History lives
        // only in the shared operation log and never restores execution state.
        jobs.retain(|job| {
            job.finished_at
                .is_none_or(|at| at.elapsed() < std::time::Duration::from_secs(300))
        });
        Ok(jobs)
    }

    pub fn project_busy(&self, id: &str) -> Result<bool, AowError> {
        Ok(self
            .lock()?
            .iter()
            .any(|job| job.project_id == id && job.items.iter().any(|item| item.status.active())))
    }

    pub fn project_lock(&self, id: &str) -> Result<Arc<tokio::sync::Mutex<()>>, AowError> {
        Ok(self
            .project_locks
            .lock()
            .map_err(|_| AowError::Poisoned)?
            .entry(id.to_owned())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone())
    }

    fn update(
        &self,
        id: &str,
        path: &str,
        status: RemovalStatus,
        error: Option<String>,
    ) -> Result<(), AowError> {
        let mut jobs = self.lock()?;
        let job = jobs
            .iter_mut()
            .find(|job| job.id == id)
            .ok_or_else(|| AowError::Invalid("清理任务不存在".into()))?;
        let item = job
            .items
            .iter_mut()
            .find(|item| item.path == path)
            .ok_or_else(|| AowError::Invalid("清理项目不存在".into()))?;
        item.status = status;
        item.error = error;
        if job.items.iter().all(|item| !item.status.active()) {
            job.finished_at = Some(std::time::Instant::now());
        }
        Ok(())
    }
}

pub(super) async fn list_jobs(
    State(state): State<AppState>,
) -> Result<Json<Vec<RemovalJob>>, Response> {
    state
        .aow
        .inner
        .removals
        .lock()
        .map(|jobs| Json(jobs.clone()))
        .map_err(aow_response)
}

pub(super) async fn submit_batch(
    State(state): State<AppState>,
    AxumPath(id): AxumPath<String>,
    Json(request): Json<BatchRequest>,
) -> Result<(StatusCode, Json<RemovalJob>), Response> {
    submit(state, id, request.items)
        .map(|job| (StatusCode::ACCEPTED, Json(job)))
        .map_err(aow_response)
}

pub(super) fn submit(
    state: AppState,
    project_id: String,
    requests: Vec<RemovalRequest>,
) -> Result<RemovalJob, AowError> {
    if requests.is_empty() || requests.len() > 200 {
        return Err(AowError::Invalid("每次请选择 1～200 个 Worktree".into()));
    }
    let mut paths = HashSet::new();
    for request in &requests {
        let path = Path::new(&request.path);
        if !path.is_absolute()
            || request.path.len() > 4096
            || request.path.contains('\0')
            || path.components().any(|part| {
                matches!(
                    part,
                    std::path::Component::ParentDir | std::path::Component::CurDir
                )
            })
            || !paths.insert(request.path.clone())
        {
            return Err(AowError::Invalid("Worktree 路径无效或重复".into()));
        }
    }
    let job = RemovalJob {
        id: Uuid::new_v4().to_string(),
        project_id,
        created_at: chrono::Utc::now().to_rfc3339(),
        finished_at: None,
        items: requests
            .into_iter()
            .map(|item| RemovalItem {
                path: item.path,
                force: item.force,
                status: RemovalStatus::Queued,
                error: None,
            })
            .collect(),
    };
    let project_lock;
    {
        // Same lock order as removing a Project. No Git scan or terminal daemon call
        // belongs in this request: all potentially slow work runs in the worker.
        let registry = state.aow.lock()?;
        if !registry
            .projects
            .iter()
            .any(|project| project.id == job.project_id)
        {
            return Err(AowError::ProjectNotFound(job.project_id.clone()));
        }
        let removals = &state.aow.inner.removals;
        let mut jobs = removals.lock()?;
        if jobs
            .iter()
            .flat_map(|job| &job.items)
            .any(|item| paths.contains(&item.path) && item.status.active())
        {
            return Err(AowError::RemovalConflict(
                "所选 Worktree 已在清理队列中".into(),
            ));
        }
        project_lock = removals.project_lock(&job.project_id)?;
        let mut next = jobs.clone();
        // Bound completed history while retaining every active task.
        let finished = next
            .iter()
            .filter(|job| job.items.iter().all(|item| !item.status.active()))
            .count();
        let mut discard = finished.saturating_sub(99);
        next.retain(|job| {
            if discard > 0 && job.items.iter().all(|item| !item.status.active()) {
                discard -= 1;
                false
            } else {
                true
            }
        });
        next.push(job.clone());
        *jobs = next;
        for item in &job.items {
            if let Err(error) = state.terminals.set_workspace_removing(&item.path, true) {
                tracing::error!(%error, path = %item.path, "failed to reserve workspace for removal");
            }
        }
    }
    let operation = state.operations.begin(Spec {
        id: job.id.clone(),
        kind: "worktree.remove",
        source: "web",
        title: "删除 Worktree".into(),
        project_id: Some(job.project_id.clone()),
        resource: None,
        total: Some(job.items.len()),
    });
    let worker_job = job.clone();
    // Own the task independently of the HTTP request and catch worker panics so
    // no item is left permanently running and terminal creation is unblocked.
    tokio::spawn(async move {
        let worker_state = state.clone();
        let inner_job = worker_job.clone();
        let worker_operation = operation.clone();
        let worker = tokio::spawn(async move {
            let _project = project_lock.lock().await;
            let _permit = worker_state
                .aow
                .inner
                .removals
                .permits
                .acquire()
                .await
                .expect("removal semaphore closed");
            run_job(&worker_state, &inner_job, &worker_operation).await;
        });
        if let Err(error) = worker.await {
            for item in &worker_job.items {
                let active = state
                    .aow
                    .inner
                    .removals
                    .lock()
                    .map(|jobs| {
                        jobs.iter()
                            .find(|job| job.id == worker_job.id)
                            .is_some_and(|job| {
                                job.items.iter().any(|current| {
                                    current.path == item.path && current.status.active()
                                })
                            })
                    })
                    .unwrap_or(false);
                if active {
                    let _ = state.terminals.set_workspace_removing(&item.path, false);
                    let _ = state.aow.inner.removals.update(
                        &worker_job.id,
                        &item.path,
                        RemovalStatus::Interrupted,
                        Some(format!("清理任务中断：{error}")),
                    );
                }
            }
            operation.finish(
                Outcome::Interrupted,
                "清理任务中断，部分结果未确认，请检查 Worktree 状态",
            );
        } else if let Ok(jobs) = state.aow.inner.removals.lock()
            && let Some(job) = jobs.iter().find(|job| job.id == worker_job.id)
        {
            let succeeded = job
                .items
                .iter()
                .filter(|item| item.status == RemovalStatus::Succeeded)
                .count();
            let failed = job.items.len() - succeeded;
            let outcome = if failed == 0 {
                Outcome::Succeeded
            } else if succeeded == 0 {
                Outcome::Failed
            } else {
                Outcome::PartialSuccess
            };
            operation.finish(
                outcome,
                format!("Worktree 清理完成：成功 {succeeded}，失败 {failed}"),
            );
        }
    });
    Ok(job)
}

async fn run_job(state: &AppState, job: &RemovalJob, operation: &Handle) {
    for (index, item) in job.items.iter().enumerate() {
        operation.progress(format!("正在检查 {}", item.path), Some(index));
        let outcome = async {
            state
                .aow
                .inner
                .removals
                .update(&job.id, &item.path, RemovalStatus::Running, None)?;
            // Inspect before touching resources; main/locked/dirty worktrees retain
            // the existing deletion protections. Recheck dirtiness at removal time.
            let inspection = state
                .aow
                .inspect_worktree_removal(&job.project_id, &item.path)
                .await?;
            if inspection.change_count > 0 && !item.force {
                return Err(AowError::DirtyWorktree(inspection.change_count));
            }
            state
                .terminals
                .set_workspace_removing(&item.path, true)
                .map_err(|error| AowError::Invalid(error.to_string()))?;
            operation.progress(format!("清理 Terminal / Agent：{}", item.path), Some(index));
            state
                .terminals
                .delete_workspace(&item.path)
                .await
                .map_err(|error| AowError::Invalid(error.to_string()))?;
            operation.progress(format!("删除 Worktree 目录：{}", item.path), Some(index));
            state
                .aow
                .remove_worktree_files(&job.project_id, &item.path, item.force)
                .await?;
            Ok::<_, AowError>(())
        }
        .await;
        let (status, error) = match outcome {
            Ok(()) => (RemovalStatus::Succeeded, None),
            Err(error) => (RemovalStatus::Failed, Some(error.to_string())),
        };
        operation.event(
            if error.is_some() {
                Level::Error
            } else {
                Level::Info
            },
            match &error {
                Some(error) => format!("删除失败 {}：{error}", item.path),
                None => format!("已删除 {}", item.path),
            },
            Some(index + 1),
        );
        let _ = state.terminals.set_workspace_removing(&item.path, false);
        if let Err(error) = state
            .aow
            .inner
            .removals
            .update(&job.id, &item.path, status, error)
        {
            tracing::error!(%error, job = %job.id, path = %item.path, "failed to update worktree removal outcome");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::{
        body::{Body, to_bytes},
        http::Request,
    };
    use tower::ServiceExt;

    async fn fixture() -> (tempfile::TempDir, AppState, Project, Vec<String>) {
        let directory = tempfile::tempdir().unwrap();
        let repository = directory.path().join("repo");
        std::fs::create_dir(&repository).unwrap();
        git_output(&repository, &["init", "-q", "-b", "main"])
            .await
            .unwrap();
        git_output(
            &repository,
            &[
                "-c",
                "user.name=Test",
                "-c",
                "user.email=test@example.com",
                "commit",
                "-q",
                "--allow-empty",
                "-m",
                "initial",
            ],
        )
        .await
        .unwrap();
        let mut state = AppState::new(PathBuf::new());
        state.aow = AowManager::persistent(&directory.path().join("state")).unwrap();
        let project = state
            .aow
            .register_project(RegisterProjectRequest {
                path: repository.to_string_lossy().into_owned(),
                name: None,
                notes_path: Some(
                    directory
                        .path()
                        .join("notes")
                        .to_string_lossy()
                        .into_owned(),
                ),
            })
            .await
            .unwrap();
        let mut paths = Vec::new();
        for branch in ["dirty", "clean", "locked"] {
            let path = directory.path().join(branch).to_string_lossy().into_owned();
            state
                .aow
                .create_worktree(
                    &project.id,
                    CreateWorktreeRequest {
                        branch: branch.into(),
                        base_ref: "main".into(),
                        path: path.clone(),
                        pull_first: false,
                    },
                )
                .await
                .unwrap();
            paths.push(path);
        }
        std::fs::write(Path::new(&paths[0]).join("uncommitted.txt"), "keep me").unwrap();
        git_output(&repository, &["worktree", "lock", &paths[2]])
            .await
            .unwrap();
        (directory, state, project, paths)
    }

    async fn wait_finished(state: &AppState, id: &str) -> RemovalJob {
        tokio::time::timeout(std::time::Duration::from_secs(15), async {
            loop {
                let job = state
                    .aow
                    .inner
                    .removals
                    .lock()
                    .unwrap()
                    .iter()
                    .find(|job| job.id == id)
                    .unwrap()
                    .clone();
                if job.items.iter().all(|item| !item.status.active()) {
                    return job;
                }
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap()
    }

    #[tokio::test]
    async fn request_returns_accepted_while_worker_waits_and_rejects_duplicate_deletion() {
        let (_directory, state, project, paths) = fixture().await;
        let manager = state.aow.clone();
        let permit = manager
            .inner
            .removals
            .permits
            .acquire_many(2)
            .await
            .unwrap();
        let router = crate::build_router(state.clone());
        let request = || {
            Request::builder()
                .method("POST")
                .uri(format!(
                    "/api/aow/projects/{}/worktrees/removals",
                    project.id
                ))
                .header("content-type", "application/json")
                .body(Body::from(
                    serde_json::json!({"items": [{"path": paths[1]}]}).to_string(),
                ))
                .unwrap()
        };
        let response = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            router.clone().oneshot(request()),
        )
        .await
        .unwrap()
        .unwrap();
        assert_eq!(response.status(), StatusCode::ACCEPTED);
        let job: RemovalJob =
            serde_json::from_slice(&to_bytes(response.into_body(), 100_000).await.unwrap())
                .unwrap();
        assert_eq!(job.items[0].status, RemovalStatus::Queued);
        assert!(Path::new(&paths[1]).exists());
        assert_eq!(
            router.clone().oneshot(request()).await.unwrap().status(),
            StatusCode::CONFLICT
        );
        assert!(matches!(
            state.aow.remove_project(&project.id).await,
            Err(AowError::RemovalConflict(_))
        ));
        let response = router
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/api/terminals")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({"workspace_root": paths[1], "cwd": paths[1]})
                            .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert!(!response.status().is_success());
        let error = String::from_utf8(
            to_bytes(response.into_body(), 100_000)
                .await
                .unwrap()
                .to_vec(),
        )
        .unwrap();
        assert!(error.contains("Worktree 正在清理"), "{error}");
        drop(permit);
        assert_eq!(
            wait_finished(&state, &job.id).await.items[0].status,
            RemovalStatus::Succeeded
        );
        assert!(!Path::new(&paths[1]).exists());
    }

    #[tokio::test]
    async fn batch_isolates_failures_protects_main_locked_and_dirty_and_supports_explicit_retry() {
        let (directory, state, project, paths) = fixture().await;
        let outside = directory.path().join("outside");
        std::fs::create_dir(&outside).unwrap();
        let job = submit(
            state.clone(),
            project.id.clone(),
            [
                paths[0].clone(),
                paths[1].clone(),
                paths[2].clone(),
                project.registered_path.clone(),
                outside.to_string_lossy().into_owned(),
            ]
            .into_iter()
            .map(|path| RemovalRequest { path, force: false })
            .collect(),
        )
        .unwrap();
        let completed = wait_finished(&state, &job.id).await;
        assert_eq!(
            completed
                .items
                .iter()
                .map(|item| item.status)
                .collect::<Vec<_>>(),
            vec![
                RemovalStatus::Failed,
                RemovalStatus::Succeeded,
                RemovalStatus::Failed,
                RemovalStatus::Failed,
                RemovalStatus::Failed
            ]
        );
        assert!(Path::new(&paths[0]).join("uncommitted.txt").exists());
        assert!(!Path::new(&paths[1]).exists());
        assert!(Path::new(&paths[2]).exists());
        assert!(Path::new(&project.registered_path).exists());
        assert!(outside.exists());
        let retry = submit(
            state.clone(),
            project.id.clone(),
            vec![RemovalRequest {
                path: paths[0].clone(),
                force: true,
            }],
        )
        .unwrap();
        assert_eq!(
            wait_finished(&state, &retry.id).await.items[0].status,
            RemovalStatus::Succeeded
        );
        assert!(!Path::new(&paths[0]).exists());
        let branches = git_output(
            Path::new(&project.registered_path),
            &["branch", "--format=%(refname:short)"],
        )
        .await
        .unwrap();
        assert!(branches.lines().any(|branch| branch == "dirty"));
        assert!(branches.lines().any(|branch| branch == "clean"));
        let restored = AowManager::persistent(&directory.path().join("state")).unwrap();
        assert!(restored.inner.removals.lock().unwrap().is_empty());
        assert!(
            !directory
                .path()
                .join("state/worktree-removals.json")
                .exists()
        );
    }

    #[test]
    fn legacy_history_is_ignored_even_when_invalid() {
        let directory = tempfile::tempdir().unwrap();
        std::fs::write(directory.path().join("worktree-removals.json"), "not json").unwrap();
        let restored = AowManager::persistent(directory.path()).unwrap();
        assert!(restored.inner.removals.lock().unwrap().is_empty());
    }
}

use std::{
    collections::HashMap,
    path::{Path, PathBuf},
    sync::{Arc, Mutex},
};

use axum::{
    Json,
    extract::{Request, State},
    http::{
        HeaderMap, HeaderValue, StatusCode,
        header::{COOKIE, SET_COOKIE},
    },
    middleware::Next,
    response::{IntoResponse, Response},
};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::{AppState, HttpError};

pub(crate) const PIN_HASH_FILE: &str = "pin.md5";
const SESSION_COOKIE: &str = "aow_session";

#[derive(Clone)]
pub(crate) struct PinAuth {
    cookie_name: String,
    pin_hash_path: Option<PathBuf>,
    sessions: Arc<Mutex<HashMap<String, String>>>,
}

enum PinConfiguration {
    Disabled,
    NotConfigured,
    Configured(String),
    Invalid(String),
}

#[derive(Serialize)]
pub(crate) struct AuthStatus {
    pub configured: bool,
    pub authenticated: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
}

#[derive(Deserialize)]
pub(crate) struct LoginRequest {
    pub pin: String,
}

impl PinAuth {
    pub(crate) fn persistent(state_dir: &Path) -> Self {
        Self {
            cookie_name: SESSION_COOKIE.to_owned(),
            pin_hash_path: Some(state_dir.join(PIN_HASH_FILE)),
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// In-memory application states are used by embedders and the existing
    /// route test suite. The server binary always uses `persistent`.
    pub(crate) fn disabled() -> Self {
        Self {
            cookie_name: SESSION_COOKIE.to_owned(),
            pin_hash_path: None,
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub(crate) fn set_cookie_name(&mut self, name: String) {
        self.cookie_name = name;
    }

    pub(crate) fn status(&self, headers: &HeaderMap) -> AuthStatus {
        match self.configuration() {
            PinConfiguration::Configured(hash) => AuthStatus {
                configured: true,
                authenticated: self.has_session(headers, &hash),
                message: None,
            },
            PinConfiguration::Disabled => AuthStatus {
                configured: false,
                authenticated: false,
                message: None,
            },
            PinConfiguration::NotConfigured => AuthStatus {
                configured: false,
                authenticated: false,
                message: Some(format!(
                    "尚未配置 PIN。请在服务器上运行 `aow pin`，它会创建 {PIN_HASH_FILE}。"
                )),
            },
            PinConfiguration::Invalid(message) => AuthStatus {
                configured: false,
                authenticated: false,
                message: Some(message),
            },
        }
    }

    pub(crate) fn authorize(&self, headers: &HeaderMap) -> Result<(), HttpError> {
        match self.configuration() {
            PinConfiguration::Disabled => Ok(()),
            PinConfiguration::Configured(hash) if self.has_session(headers, &hash) => Ok(()),
            PinConfiguration::Configured(_) => Err(authentication_required()),
            PinConfiguration::NotConfigured => Err(pin_not_configured()),
            PinConfiguration::Invalid(message) => Err(HttpError::new(
                StatusCode::SERVICE_UNAVAILABLE,
                "pin_configuration_invalid",
                message,
                None,
            )),
        }
    }

    pub(crate) fn login(&self, pin: &str) -> Result<String, HttpError> {
        if !valid_pin(pin) {
            return Err(HttpError::new(
                StatusCode::BAD_REQUEST,
                "invalid_pin",
                "PIN 必须恰好为 6 位数字",
                None,
            ));
        }
        let expected_hash = match self.configuration() {
            PinConfiguration::Configured(hash) => hash,
            PinConfiguration::Disabled | PinConfiguration::NotConfigured => {
                return Err(pin_not_configured());
            }
            PinConfiguration::Invalid(message) => {
                return Err(HttpError::new(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "pin_configuration_invalid",
                    message,
                    None,
                ));
            }
        };
        let entered_hash = format!("{:x}", md5::compute(pin.as_bytes()));
        if !constant_time_eq(&entered_hash, &expected_hash) {
            return Err(HttpError::new(
                StatusCode::UNAUTHORIZED,
                "invalid_pin",
                "PIN 不正确",
                None,
            ));
        }

        let token = Uuid::new_v4().simple().to_string();
        self.sessions
            .lock()
            .map_err(|_| HttpError::internal("PIN 会话锁不可用"))?
            .insert(token.clone(), expected_hash);
        Ok(token)
    }

    fn has_session(&self, headers: &HeaderMap, current_hash: &str) -> bool {
        let Some(token) = session_token(headers, &self.cookie_name) else {
            return false;
        };
        let Ok(mut sessions) = self.sessions.lock() else {
            return false;
        };
        let Some(session_hash) = sessions.get(token) else {
            return false;
        };
        if constant_time_eq(session_hash, current_hash) {
            true
        } else {
            // A newly configured PIN invalidates sessions created with the old one.
            sessions.remove(token);
            false
        }
    }

    fn configuration(&self) -> PinConfiguration {
        let Some(path) = &self.pin_hash_path else {
            return PinConfiguration::Disabled;
        };
        let contents = match std::fs::read_to_string(path) {
            Ok(contents) => contents,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return PinConfiguration::NotConfigured;
            }
            Err(error) => {
                return PinConfiguration::Invalid(format!(
                    "无法读取 PIN 配置 {}：{error}",
                    path.display()
                ));
            }
        };
        let hash = contents.trim();
        if hash.len() != 32 || !hash.bytes().all(|byte| byte.is_ascii_hexdigit()) {
            return PinConfiguration::Invalid(format!(
                "PIN 配置 {} 无效；请重新运行 `aow pin`",
                path.display()
            ));
        }
        PinConfiguration::Configured(hash.to_ascii_lowercase())
    }
}

pub(crate) async fn status(State(state): State<AppState>, headers: HeaderMap) -> Json<AuthStatus> {
    Json(state.auth.status(&headers))
}

pub(crate) async fn login(
    State(state): State<AppState>,
    Json(request): Json<LoginRequest>,
) -> Result<Response, HttpError> {
    let token = state.auth.login(&request.pin)?;
    let mut response = Json(AuthStatus {
        configured: true,
        authenticated: true,
        message: None,
    })
    .into_response();
    response.headers_mut().insert(
        SET_COOKIE,
        HeaderValue::from_str(&format!(
            "{}={token}; Path={}; HttpOnly; SameSite=Strict",
            state.auth.cookie_name,
            state.base_path.url("/")
        ))
        .expect("UUID session token is a valid cookie value"),
    );
    Ok(response)
}

pub(crate) async fn require_auth(
    State(state): State<AppState>,
    request: Request,
    next: Next,
) -> Response {
    let path = request.uri().path();
    // Only the registered read-only share route bypasses PIN authentication.
    // A share token never establishes a AoW login session.
    let public_share = matches!(
        *request.method(),
        axum::http::Method::GET | axum::http::Method::HEAD
    ) && request
        .extensions()
        .get::<axum::extract::MatchedPath>()
        .is_some_and(|path| path.as_str() == crate::session_shares::PUBLIC_API_PATH);
    let protected = (path.starts_with("/api/")
        && !public_share
        && !matches!(path, "/api/health" | "/api/auth/status" | "/api/auth/login"))
        || path == "/fs"
        || path.starts_with("/fs/")
        || path == "/help";
    if protected && let Err(error) = state.auth.authorize(request.headers()) {
        return error.into_response();
    }
    next.run(request).await
}

#[cfg(test)]
pub(crate) fn cookie_header(token: &str) -> HeaderValue {
    HeaderValue::from_str(&format!("{SESSION_COOKIE}={token}"))
        .expect("UUID session token is a valid cookie value")
}

fn session_token<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {
    headers
        .get(COOKIE)
        .and_then(|value| value.to_str().ok())
        .and_then(|cookie| {
            cookie
                .split(';')
                .map(str::trim)
                .find_map(|entry| entry.strip_prefix(&format!("{name}=")))
        })
}

fn valid_pin(pin: &str) -> bool {
    pin.len() == 6 && pin.bytes().all(|byte| byte.is_ascii_digit())
}

fn constant_time_eq(left: &str, right: &str) -> bool {
    if left.len() != right.len() {
        return false;
    }
    let mut difference = 0_u8;
    for (left, right) in left.bytes().zip(right.bytes()) {
        difference |= left ^ right;
    }
    difference == 0
}

fn pin_not_configured() -> HttpError {
    HttpError::new(
        StatusCode::SERVICE_UNAVAILABLE,
        "pin_not_configured",
        "AoW 尚未配置 PIN；请在服务器上运行 `aow pin`",
        None,
    )
}

fn authentication_required() -> HttpError {
    HttpError::new(
        StatusCode::UNAUTHORIZED,
        "authentication_required",
        "需要输入 PIN 码后才能访问 AoW",
        None,
    )
}

