fn stop(locator: &AgentSessionLocator) {
    writeln!(
        OpenOptions::new()
            .append(true)
            .open(&locator.transcript_path)
            .unwrap(),
        "{{\"type\":\"event_msg\",\"payload\":{{\"type\":\"task_complete\",\"turn_id\":\"one\",\"last_agent_message\":\"本轮完整结论\"}}}}"
    )
