async fn codex_like_stops_use_the_expected_environment(with_process: bool) {
    use axum::body::HttpBody;
    use serde_json::json;
    use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
    use tower::ServiceExt;

    let directory = tempfile::tempdir().unwrap();
    let cwd = directory.path().join("project");
    std::fs::create_dir(&cwd).unwrap();
    let mut environment = SessionEnvironment::new();
    let mut transcripts = Vec::new();
    for (agent, variable) in [("traecli", "TRAECLI_HOME"), ("codex", "CODEX_HOME")] {
        let home = directory.path().join(agent);
        let sessions = home.join("sessions");
        std::fs::create_dir_all(&sessions).unwrap();
        let mut locator = fixture(&sessions, agent, 1);
        locator.agent = agent;
        locator.cwd = cwd.clone();
        stop(&locator); // Existing completion must not replay when registered.
        let db = rusqlite::Connection::open(home.join("state_5.sqlite")).unwrap();
        db.execute_batch(
            "CREATE TABLE threads (
                id TEXT PRIMARY KEY, rollout_path TEXT, cwd TEXT, title TEXT,
                created_at INTEGER, updated_at INTEGER, updated_at_ms INTEGER,
                archived INTEGER, first_user_message TEXT, thread_source TEXT,
                source TEXT, agent_nickname TEXT, agent_role TEXT
            );",
        )
        .unwrap();
        db.execute(
            "INSERT INTO threads VALUES (?1, ?2, ?3, 'Same title',
                1789726500, 1789726500, 1789726500000, 0, 'Task', 'user', 'cli', '', '')",
            rusqlite::params![agent, locator.transcript_path.to_str(), cwd.to_str()],
        )
        .unwrap();
        environment.insert(variable.into(), home);
        transcripts.push(locator);
    }

    struct ChildGuard(std::process::Child);
    impl Drop for ChildGuard {
        fn drop(&mut self) {
            let _ = self.0.kill();
            let _ = self.0.wait();
        }
    }
    let child = with_process.then(|| {
        use std::process::{Command, Stdio};
        ChildGuard(
            Command::new(std::env::current_exe().unwrap())
                .args([
                    "--ignored",
                    "--exact",
                    "terminal::sessions::tests::native_environment_fixture",
                ])
                .env("AOW_NATIVE_ENV_FIXTURE", "1")
                .envs(&environment)
                .current_dir(&cwd)
                .stdin(Stdio::piped())
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .spawn()
                .unwrap(),
        )
    });
    let process = child.as_ref().map(|child| {
        let info = aow_process::info(child.0.id() as i32).unwrap();
        TerminalAgentProcess {
            pid: info.pid,
            start_time: info.start_time,
            cwd: aow_process::cwd(info.pid)
                .unwrap()
                .to_string_lossy()
                .into_owned(),
        }
    });
    let metadata_for = |agent: &str| {
        let mut metadata = json!({
            "agents": {"pane": agent},
            "titles": {"pane": "Same title | project"}
        });
        if let Some(process) = &process {
            metadata["processes"] = json!({"pane": process});
        }
        metadata
    };
    let metadata = Arc::new(Mutex::new(metadata_for("traecli")));
    let socket = directory.path().join("terminald.sock");
    let listener = tokio::net::UnixListener::bind(&socket).unwrap();
    let (scanned, mut scans) = tokio::sync::mpsc::unbounded_channel();
    let daemon_metadata = metadata.clone();
    let daemon = tokio::spawn(async move {
        while let Ok((stream, _)) = listener.accept().await {
            let mut stream = BufReader::new(stream);
            let mut line = String::new();
            stream.read_line(&mut line).await.unwrap();
            assert!(line.starts_with("GET /v1/agents "));
            loop {
                line.clear();
                if stream.read_line(&mut line).await.unwrap() == 0 || line == "\r\n" {
                    break;
                }
            }
            let value = daemon_metadata.lock().unwrap().clone();
            let body = value.to_string();
            stream
                .get_mut()
                .write_all(format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                ).as_bytes())
                .await.unwrap();
            let _ = scanned.send(value);
        }
    });

    let manager = TerminalManager::in_memory(TerminaldClient::new(socket));
    let pane: TerminalPane = serde_json::from_value(json!({
        "id": "pane", "name": "project", "cwd": cwd,
        "shell": "/bin/sh", "kind": "terminal", "status": "running",
        "rows": 24, "cols": 80, "created_at": "now", "updated_at": "now"
    }))
    .unwrap();
    manager.lock_state().unwrap().tabs.push(TerminalTab {
        id: "tab".into(),
        name: "Terminal".into(),
        name_is_custom: None,
        workspace_root: cwd.to_string_lossy().into_owned(),
        layout: TerminalLayout::Pane {
            pane_id: "pane".into(),
        },
        panes: vec![pane],
        revision: 1,
        created_at: "now".into(),
        updated_at: "now".into(),
    });
    let mut state = AppState::new(directory.path().join("frontend"));
    state.terminals = manager.clone();
    let response = crate::build_router(state)
        .oneshot(
            axum::http::Request::get("/api/terminals/task-stops")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);
    let mut body = response.into_body();
    let mut callbacks = manager.inner.task_stops.subscribe();
    manager.start_agent_notifications_with_environment(
        // The native path must obtain the custom stores from the child, even
        // when the server has no corresponding fallback configuration.
        if with_process {
            SessionEnvironment::new()
        } else {
            environment
        },
        Duration::from_millis(50),
        crate::aow::AowManager::in_memory(),
    );

    async fn settled(
        scans: &mut tokio::sync::mpsc::UnboundedReceiver<serde_json::Value>,
        expected: &serde_json::Value,
    ) {
        // A second query proves that registration from the first has finished.
        tokio::time::timeout(Duration::from_secs(5), async {
            for _ in 0..2 {
                loop {
                    if &scans.recv().await.unwrap() == expected {
                        break;
                    }
                }
            }
        })
        .await
        .expect("notification discovery did not finish");
    }
    for locator in &transcripts {
        let expected = metadata_for(locator.agent);
        *metadata.lock().unwrap() = expected.clone();
        settled(&mut scans, &expected).await;
        assert!(
            callbacks.try_recv().is_err(),
            "replayed a historical completion"
        );
        // Rename only in the original agent store. OSC and the registered
        // title stay unchanged, so delivery must resolve the bound session ID.
        let db = rusqlite::Connection::open(
            locator
                .trusted_root
                .parent()
                .unwrap()
                .join("state_5.sqlite"),
        )
        .unwrap();
        let renamed = format!("{} renamed after registration", locator.agent);
        db.execute(
            "UPDATE threads SET title = ?1 WHERE id = ?2",
            rusqlite::params![renamed, locator.session_id],
        )
        .unwrap();
        stop(locator);
        let callback = tokio::time::timeout(Duration::from_secs(5), callbacks.recv())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(callback.agent, locator.agent);
        assert_eq!(callback.title, renamed);
        assert_eq!(callback.instance_ids, ["pane"]);
        assert_eq!(callback.sources.len(), 1);
        assert_eq!(callback.sources[0].project_name, "project");
        assert_eq!(callback.sources[0].tab_id, "tab");
        assert_eq!(callback.sources[0].tab_name, "Terminal");
        assert_eq!(callback.conclusion.as_deref(), Some("本轮完整结论"));
        let frame = tokio::time::timeout(
            Duration::from_secs(5),
            std::future::poll_fn(|cx| std::pin::Pin::new(&mut body).poll_frame(cx)),
        )
        .await
        .unwrap()
        .unwrap()
        .unwrap();
        let event = String::from_utf8(frame.into_data().unwrap().to_vec()).unwrap();
        assert!(event.contains("event: task-stopped"));
        assert!(event.contains(&format!("\"agent\":\"{}\"", locator.agent)));
        assert!(event.contains("\"project_name\":\"project\""));
        assert!(event.contains("\"tab_name\":\"Terminal\""));
        assert!(event.contains("\"conclusion\":\"本轮完整结论\""));
        assert!(event.contains(&format!("\"title\":\"{renamed}\"")));

        // A temporarily missing store must not suppress subsequent completions
        // or replace the latest known name with the original registration title.
        db.execute("DELETE FROM threads", []).unwrap();
        stop(locator);
        let callback = tokio::time::timeout(Duration::from_secs(5), callbacks.recv())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(callback.title, renamed);
        assert_eq!(callback.session_id, locator.session_id);
        let frame = tokio::time::timeout(
            Duration::from_secs(5),
            std::future::poll_fn(|cx| std::pin::Pin::new(&mut body).poll_frame(cx)),
        )
        .await
        .unwrap()
        .unwrap()
        .unwrap();
        assert!(
            String::from_utf8(frame.into_data().unwrap().to_vec())
                .unwrap()
                .contains(&format!("\"title\":\"{renamed}\""))
        );
        settled(&mut scans, &expected).await;
        assert!(
            callbacks.try_recv().is_err(),
            "replayed completion after rename"
        );
    }

    // Switching to Claude on a daemon without PID metadata unregisters the
    // previous title; it must not guess Claude's active session from that title.
    let expected =
        json!({"agents": {"pane": "claude"}, "titles": {"pane": "Same title | project"}});
    *metadata.lock().unwrap() = expected.clone();
    settled(&mut scans, &expected).await;
    for locator in &transcripts {
        stop(locator);
    }
    while scans.try_recv().is_ok() {}
    settled(&mut scans, &expected).await;
    assert!(
        callbacks.try_recv().is_err(),
        "kept the old agent's binding"
    );
    daemon.abort();
}

use super::*;
use aow_agents::Agent;
use aow_protocol::{AgentTerminalPhase, AgentTerminalState};

pub(super) async fn rebuild_terminal(
    State(state): State<AppState>,
    AxumPath(tab_id): AxumPath<String>,
) -> Result<Json<TerminalTab>, HttpError> {
    // Finish committing or rolling back even if the browser disconnects.
    tokio::spawn(async move {
        let previous = state
            .terminals
            .get(&tab_id)
            .await
            .map_err(terminal_http_error)?;
        ensure_rebuildable(&previous).map_err(terminal_http_error)?;
        let mut specs = Vec::new();
        for pane in &previous.panes {
            let mut spec = runtime_spec(pane);
            if pane.kind == TerminalPaneKind::Agent {
                let agent_id = pane.agent_id.as_deref().ok_or_else(|| {
                    terminal_http_error(TerminalError::Invalid(
                        "终端缺少 Agent 配置，无法重建".into(),
                    ))
                })?;
                if pane.agent_terminal.is_some()
                    && Agent::from_id(agent_id)
                        .and_then(Agent::interactive)
                        .is_none()
                {
                    return Err(terminal_http_error(TerminalError::Invalid(
                        "该 Agent 不支持交互式初始化".into(),
                    )));
                }
                // Credentials and PATH come from the current workspace profile;
                // keep the saved command/arguments (including explicit resume).
                spec.environment = state
                    .aow
                    .resolve_terminal_rebuild_launch(pane, &previous.workspace_root)
                    .await
                    .map_err(crate::aow::aow_http_error)?
                    .env;
            }
            specs.push(spec);
        }
        let tab = state
            .terminals
            .rebuild(&previous, &specs)
            .await
            .map_err(terminal_http_error)?;
        for pane in &tab.panes {
            if pane.agent_terminal.is_some() {
                let adapter = pane
                    .agent_id
                    .as_deref()
                    .and_then(Agent::from_id)
                    .and_then(Agent::interactive)
                    .expect("validated interactive adapter");
                let manager = state.terminals.clone();
                let pane_id = pane.id.clone();
                tokio::spawn(async move {
                    if let Err(error) = manager
                        .initialize_agent_lifecycle(
                            &pane_id,
                            adapter,
                            None,
                            Duration::from_secs(120),
                            None,
                        )
                        .await
                    {
                        tracing::warn!(%pane_id, %error, "failed to initialize rebuilt agent");
                    }
                });
            }
        }
        Ok(Json(tab))
    })
    .await
    .map_err(|error| HttpError::internal(error.to_string()))?
}

fn ensure_rebuildable(tab: &TerminalTab) -> Result<(), TerminalError> {
    if tab.panes.is_empty()
        || tab
            .panes
            .iter()
            .any(|pane| pane.status == TerminalPaneStatus::Running)
    {
        return Err(TerminalError::Conflict(
            "仅已退出或已中断的终端可以重建，请刷新列表".into(),
        ));
    }
    Ok(())
}

impl TerminalManager {
    async fn rebuild(
        &self,
        previous: &TerminalTab,
        specs: &[TerminalRuntimeSpec],
    ) -> Result<TerminalTab, TerminalError> {
        let _operation = self.inner.operation.lock().await;
        let current = self.get_snapshot(&previous.id)?;
        ensure_rebuildable(&current)?;
        if current
            .panes
            .iter()
            .map(|pane| &pane.id)
            .ne(previous.panes.iter().map(|pane| &pane.id))
        {
            return Err(TerminalError::Conflict("终端已发生变化，请刷新列表".into()));
        }
        {
            let state = self.lock_state()?;
            state.ensure_workspace_available(&current.workspace_root)?;
            for pane in &current.panes {
                state.ensure_workspace_available(&pane.cwd)?;
            }
        }
        validate_directory(&current.workspace_root).await?;
        for pane in &current.panes {
            validate_directory(&pane.cwd).await?;
            if self
                .inner
                .terminald
                .get(&pane.id)
                .await
                .map_err(map_client_error)?
                .is_some_and(|runtime| runtime.status == TerminalPaneStatus::Running)
            {
                return Err(TerminalError::Conflict("终端仍在运行，请刷新列表".into()));
            }
        }

        let now = timestamp();
        let panes: Vec<_> = current
            .panes
            .iter()
            .map(|pane| TerminalPane {
                id: Uuid::new_v4().to_string(),
                status: TerminalPaneStatus::Running,
                exit_code: None,
                agent_terminal: pane.agent_terminal.as_ref().map(|_| AgentTerminalState {
                    phase: AgentTerminalPhase::Starting,
                    error: None,
                    task_submitted: false,
                }),
                created_at: now.clone(),
                updated_at: now.clone(),
                ..pane.clone()
            })
            .collect();
        for (index, (pane, spec)) in panes.iter().zip(specs).enumerate() {
            if let Err(error) = self
                .inner
                .terminald
                .create(&pane.id, spec)
                .await
                .map_err(map_create_error)
            {
                for created in &panes[..=index] {
                    self.delete_failed_runtime_best_effort(&created.id).await;
                }
                return Err(error);
            }
        }
        // Keep the old metadata/runtime until every new pane has started. New
        // pane IDs also isolate stale WebSocket exit events and CLI leases.
        let result = (|| {
            let mut state = self.lock_state()?;
            let index = tab_index(&state, &current.id)?;
            let old = state.tabs[index].clone();
            let mut rebuilt = old.clone();
            for (before, after) in current.panes.iter().zip(&panes) {
                replace_layout_leaf(
                    &mut rebuilt.layout,
                    &before.id,
                    &TerminalLayout::Pane {
                        pane_id: after.id.clone(),
                    },
                );
            }
            rebuilt.panes = panes.clone();
            touch_tab(&mut rebuilt);
            state.tabs[index] = rebuilt.clone();
            if let Err(error) = self.persist_locked(&state) {
                state.tabs[index] = old;
                return Err(error);
            }
            Ok(rebuilt)
        })();
        if result.is_err() {
            for pane in &panes {
                self.delete_failed_runtime_best_effort(&pane.id).await;
            }
        } else {
            for pane in &current.panes {
                self.delete_failed_runtime_best_effort(&pane.id).await;
            }
        }
        result
    }
}

#[cfg(test)]
mod tests {
    use super::super::tests::{pane, start_daemon, stop_daemon, tab_with};
    use super::*;

    #[tokio::test]
    async fn rebuild_replaces_finished_panes_preserving_tab_and_layout() {
        let directory = tempfile::tempdir().unwrap();
        let socket = directory.path().join("terminald/daemon.sock");
        let (shutdown, daemon) = start_daemon(socket.clone()).await;
        let client = TerminaldClient::new(socket);
        let manager =
            TerminalManager::persistent(directory.path().join("state"), client.clone()).unwrap();
        let mut exited = pane("exited", TerminalPaneStatus::Exited);
        exited.exit_code = Some(9);
        exited.restart_on_daemon_restart = false;
        let mut interrupted = pane("interrupted", TerminalPaneStatus::Interrupted);
        interrupted.kind = TerminalPaneKind::Agent;
        interrupted.agent_id = Some("codex".into());
        interrupted.restart_on_daemon_restart = false;
        interrupted.arguments = vec![
            "-c".into(),
            "printf '%s' \"$REBUILD_FIXTURE\" > \"$REBUILD_OUTPUT\"; exec sleep 60".into(),
        ];
        let old = tab_with(
            TerminalLayout::Split {
                axis: TerminalSplitAxis::Row,
                ratio: 0.4,
                first: Box::new(TerminalLayout::Pane {
                    pane_id: exited.id.clone(),
                }),
                second: Box::new(TerminalLayout::Pane {
                    pane_id: interrupted.id.clone(),
                }),
            },
            vec![exited, interrupted],
        );
        let mut exit_spec = runtime_spec(&old.panes[0]);
        exit_spec.arguments = vec!["-c".into(), "exit 9".into()];
        client.create("exited", &exit_spec).await.unwrap();
        tokio::time::timeout(Duration::from_secs(5), async {
            while client.get("exited").await.unwrap().unwrap().status == TerminalPaneStatus::Running
            {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .unwrap();
        manager.lock_state().unwrap().tabs.push(old.clone());
        let mut specs: Vec<_> = old.panes.iter().map(runtime_spec).collect();
        specs[1]
            .environment
            .insert("REBUILD_FIXTURE".into(), "preserved".into());
        let output = directory.path().join("environment.txt");
        specs[1].environment.insert(
            "REBUILD_OUTPUT".into(),
            output.to_string_lossy().into_owned(),
        );
        let (first, second) =
            tokio::join!(manager.rebuild(&old, &specs), manager.rebuild(&old, &specs));
        let (rebuilt, duplicate) = if first.is_ok() {
            (first, second)
        } else {
            (second, first)
        };
        let rebuilt = rebuilt.unwrap();
        assert!(matches!(duplicate, Err(TerminalError::Conflict(_))));
        assert_eq!(rebuilt.id, old.id);
        assert_eq!(rebuilt.name, old.name);
        assert_eq!(rebuilt.workspace_root, old.workspace_root);
        assert_eq!(rebuilt.created_at, old.created_at);
        assert!(rebuilt.revision > old.revision);
        let mut expected_layout = old.layout.clone();
        for (index, replacement) in rebuilt.panes.iter().enumerate() {
            assert_ne!(replacement.id, old.panes[index].id);
            assert_eq!(replacement.status, TerminalPaneStatus::Running);
            assert_eq!(replacement.exit_code, None);
            // Runtime responses intentionally redact environment variables.
            let mut expected_spec = specs[index].clone();
            expected_spec.environment.clear();
            assert_eq!(
                client.get(&replacement.id).await.unwrap().unwrap().spec(),
                expected_spec
            );
            replace_layout_leaf(
                &mut expected_layout,
                &old.panes[index].id,
                &TerminalLayout::Pane {
                    pane_id: replacement.id.clone(),
                },
            );
            assert!(client.get(&old.panes[index].id).await.unwrap().is_none());
        }
        assert_eq!(rebuilt.layout, expected_layout);
        tokio::time::timeout(Duration::from_secs(3), async {
            while std::fs::read_to_string(&output).unwrap_or_default() != "preserved" {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .unwrap();
        assert_eq!(manager.get_snapshot(&old.id).unwrap(), rebuilt);
        assert!(matches!(
            manager.rebuild(&old, &specs).await,
            Err(TerminalError::Conflict(_))
        ));
        assert_eq!(client.list().await.unwrap().len(), 2);
        let reloaded =
            TerminalManager::persistent(directory.path().join("state"), client.clone()).unwrap();
        assert_eq!(reloaded.get_snapshot(&old.id).unwrap().panes, rebuilt.panes);
        stop_daemon(shutdown, daemon).await;
    }

    #[tokio::test]
    async fn rebuild_failure_keeps_old_metadata_and_cleans_partial_runtimes() {
        let directory = tempfile::tempdir().unwrap();
        let socket = directory.path().join("terminald/daemon.sock");
        let (shutdown, daemon) = start_daemon(socket.clone()).await;
        let client = TerminaldClient::new(socket);
        let manager = TerminalManager::in_memory(client.clone());
        let mut old = tab_with(
            TerminalLayout::Split {
                axis: TerminalSplitAxis::Column,
                ratio: 0.5,
                first: Box::new(TerminalLayout::Pane {
                    pane_id: "one".into(),
                }),
                second: Box::new(TerminalLayout::Pane {
                    pane_id: "two".into(),
                }),
            },
            vec![
                pane("one", TerminalPaneStatus::Exited),
                pane("two", TerminalPaneStatus::Interrupted),
            ],
        );
        old.panes[1].shell = "/missing/rebuild-shell".into();
        manager.lock_state().unwrap().tabs.push(old.clone());
        let specs: Vec<_> = old.panes.iter().map(runtime_spec).collect();
        assert!(manager.rebuild(&old, &specs).await.is_err());
        assert_eq!(manager.get_snapshot(&old.id).unwrap(), old);
        assert!(client.list().await.unwrap().is_empty());
        // A stale metadata status must never authorize replacing a live runtime.
        client.create("one", &specs[0]).await.unwrap();
        assert!(matches!(
            manager.rebuild(&old, &specs).await,
            Err(TerminalError::Conflict(_))
        ));
        assert_eq!(client.list().await.unwrap().len(), 1);
        stop_daemon(shutdown, daemon).await;
    }
}

//! On-demand, read-only association of a terminal pane with native agent history.

use super::*;
use aow_agents::sessions::{
    AgentSession, SessionEnvironment, SessionRoots,
    tracking::{AgentSessionTracker, LiveSessionContext, SessionResolution, SessionTarget},
};
use aow_protocol::TerminalAgentProcess;

#[derive(Serialize)]
pub(super) struct PaneSessions {
    agent: String,
    cwd: String,
    title: String,
    process: Option<TerminalAgentProcess>,
    /// The native session identity resolved by the agent adapter, if available.
    live_session_id: Option<String>,
    sessions: Vec<AgentSession>,
}

pub(super) async fn list(
    State(state): State<AppState>,
    AxumPath((tab_id, pane_id)): AxumPath<(String, String)>,
) -> Result<Json<PaneSessions>, HttpError> {
    let tab = state
        .terminals
        .get_snapshot(&tab_id)
        .map_err(terminal_http_error)?;
    let pane = tab
        .panes
        .iter()
        .find(|pane| pane.id == pane_id)
        .ok_or_else(|| terminal_http_error(TerminalError::PaneNotFound(pane_id.clone())))?;
    let detected = state
        .terminals
        .agents(Some(&tab.workspace_root))
        .await
        .map_err(terminal_http_error)?;
    let agent = detected
        .agents
        .get(&pane_id)
        .cloned()
        .unwrap_or_else(|| pane.agent_id.clone())
        .filter(|_| pane.status == TerminalPaneStatus::Running)
        .filter(|id| {
            aow_agents::Agent::from_id(id)
                .and_then(aow_agents::Agent::sessions)
                .is_some()
        })
        .ok_or_else(|| {
            terminal_http_error(TerminalError::Conflict(
                "当前面板没有可读取会话的 Agent".into(),
            ))
        })?;
    let process = detected.processes.get(&pane_id).cloned();
    let cwd = process
        .as_ref()
        .map_or_else(|| pane.cwd.clone(), |process| process.cwd.clone());
    let title = detected.titles.get(&pane_id).cloned().unwrap_or_default();
    let environment = process.as_ref().and_then(process_environment);
    // A process may exit between the daemon scan and this request. Never query
    // another process after PID reuse or use the server's config for that PID.
    if process.is_some() && environment.is_none() {
        return Err(terminal_http_error(TerminalError::Conflict(
            "Agent 进程已变化，请刷新会话列表".into(),
        )));
    }
    let roots = environment.as_ref().map_or_else(
        || SessionRoots::from_environment(&crate::PROCESS_HOME),
        |environment| {
            SessionRoots::from_configuration(
                environment
                    .get("HOME")
                    .map_or(crate::PROCESS_HOME.as_path(), PathBuf::as_path),
                environment,
            )
        },
    );
    let tracker = aow_agents::Agent::from_id(&agent).and_then(aow_agents::Agent::session_tracking);
    let live_session_id = if let (Some(tracker), Some(process), Some(environment)) =
        (tracker, &process, &environment)
    {
        match tracker
            .resolve_live_session(LiveSessionContext {
                pid: Some(process.pid),
                cwd: &cwd,
                title: &title,
                environment,
            })
            .await
        {
            SessionResolution::Resolved(SessionTarget::Id(id)) => Some(id),
            _ => None,
        }
    } else {
        None
    };
    let scan_cwd = PathBuf::from(&cwd);
    let scan_agent = agent.clone();
    let exact_id = live_session_id.clone();
    let sessions = tokio::task::spawn_blocking(move || {
        let mut sessions =
            aow_agents::sessions::list_sessions(&scan_cwd, Some(&scan_agent), roots.clone());
        if let Some(id) = exact_id {
            if !sessions
                .iter()
                .any(|session| session.locator().session_id == id)
            {
                if let Some(session) = aow_agents::sessions::find_session(&scan_agent, &id, roots) {
                    sessions.insert(0, session);
                }
            }
        }
        sessions
    })
    .await
    .map_err(|error| HttpError::internal(format!("agent session scan failed: {error}")))?;
    if process
        .as_ref()
        .is_some_and(|process| !same_process(process))
    {
        return Err(terminal_http_error(TerminalError::Conflict(
            "Agent 进程已变化，请刷新会话列表".into(),
        )));
    }
    // The pane supplies the trusted scan scope, including directories opened
    // with `cd` that aren't registered project worktrees. Snapshot reads still
    // go through the existing provider's transcript-root validation.
    for session in &sessions {
        let cwd = tokio::fs::canonicalize(session.cwd_path())
            .await
            .unwrap_or_else(|_| session.cwd_path());
        state
            .aow
            .cache_session_locator(&cwd, session)
            .map_err(crate::aow::aow_http_error)?;
    }
    Ok(Json(PaneSessions {
        agent,
        cwd,
        title,
        process,
        live_session_id,
        sessions,
    }))
}

pub(super) fn same_process(process: &TerminalAgentProcess) -> bool {
    aow_process::same_process(process.pid, &process.start_time)
}

pub(super) fn process_environment(process: &TerminalAgentProcess) -> Option<SessionEnvironment> {
    let bytes = aow_process::environment(process.pid, &process.start_time).ok()?;
    Some(configuration_environment(&bytes))
}

fn configuration_environment(bytes: &[u8]) -> SessionEnvironment {
    bytes
        .split(|byte| *byte == 0)
        .filter_map(|entry| {
            let (key, value) = std::str::from_utf8(entry).ok()?.split_once('=')?;
            (matches!(key, "HOME" | "PATH")
                || aow_agents::KNOWN_AGENTS
                    .iter()
                    .any(|agent| agent.definition().configuration_env.contains(&key)))
            .then(|| (key.to_owned(), PathBuf::from(value)))
            .filter(|(_, value)| !value.as_os_str().is_empty())
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_configuration_paths_are_read_from_the_agent_environment() {
        let keys: HashSet<_> = aow_agents::KNOWN_AGENTS
            .iter()
            .flat_map(|agent| agent.definition().configuration_env.iter().copied())
            .collect();
        let mut bytes = b"HOME=/home/user\0PATH=/usr/bin\0SECRET=hidden\0".to_vec();
        for key in &keys {
            bytes.extend_from_slice(format!("{key}=/config/{key}\0").as_bytes());
        }
        let environment = configuration_environment(&bytes);
        assert_eq!(environment.len(), keys.len() + 2);
        for key in keys {
            assert_eq!(environment[key], PathBuf::from(format!("/config/{key}")));
            assert!(configuration_environment(format!("{key}=\0").as_bytes()).is_empty());
        }
        assert!(!environment.contains_key("SECRET"));
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn native_process_environment_uses_the_agents_config_and_rejects_stale_identity() {
        use std::process::{Command, Stdio};
        struct ChildGuard(std::process::Child);
        impl Drop for ChildGuard {
            fn drop(&mut self) {
                let _ = self.0.kill();
                let _ = self.0.wait();
            }
        }
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path().canonicalize().unwrap();
        let ready = root.join("environment.ready");
        let mut command = Command::new(std::env::current_exe().unwrap());
        command.args([
            "--ignored",
            "--exact",
            "terminal::sessions::tests::native_environment_fixture",
        ]);
        command.env("AOW_NATIVE_ENV_FIXTURE", "1");
        command.env("AOW_NATIVE_ENV_READY", &ready);
        let keys: Vec<_> = aow_agents::KNOWN_AGENTS
            .iter()
            .flat_map(|agent| agent.definition().configuration_env.iter().copied())
            .chain(["HOME", "PATH"])
            .collect();
        for key in &keys {
            command.env(key, root.join(format!("{key} with spaces")));
        }
        let mut child = ChildGuard(
            command
                .env("AOW_TEST_SECRET", "must not be retained")
                .stdin(Stdio::piped())
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .spawn()
                .unwrap(),
        );
        // A PID can be observable before the exec has exposed the fixture's
        // environment through /proc. Wait for the child to enter the fixture.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while !ready.exists() {
            assert!(
                child.0.try_wait().unwrap().is_none(),
                "native environment fixture exited before becoming ready"
            );
            assert!(
                std::time::Instant::now() < deadline,
                "native environment fixture did not become ready"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let info = aow_process::info(child.0.id() as i32).unwrap();
        let mut process = TerminalAgentProcess {
            pid: info.pid,
            start_time: info.start_time,
            cwd: root.to_string_lossy().into_owned(),
        };
        assert!(same_process(&process));
        let environment = process_environment(&process).unwrap();
        assert_eq!(environment.len(), keys.len());
        for key in keys {
            assert_eq!(environment[key], root.join(format!("{key} with spaces")));
        }
        assert!(!environment.contains_key("AOW_TEST_SECRET"));
        let original = process.start_time.clone();
        process.start_time = "different start identity".into();
        assert!(process_environment(&process).is_none());
        process.start_time = original;
        child.0.kill().unwrap();
        child.0.wait().unwrap();
        assert!(!same_process(&process));
        assert!(process_environment(&process).is_none());
    }

    #[test]
    #[ignore = "subprocess fixture invoked by native process/session tests"]
    fn native_environment_fixture() {
        if std::env::var_os("AOW_NATIVE_ENV_FIXTURE").is_some() {
            if let Some(ready) = std::env::var_os("AOW_NATIVE_ENV_READY") {
                std::fs::write(ready, b"ready").unwrap();
            }
            std::io::stdin().read_line(&mut String::new()).unwrap();
        }
    }
}

