    capture: ({ route: r, worktree: w }) => r.view === 'automations' && r.task ? { type: 'automation', workspace: w.id, taskId: r.task, runId: r.run, view: r.run || r.automationView === 'runs' ? 'runs' : undefined } : undefined,
