function RunBadge({ run }: { run: AutomationRun }) {
  return <span className={`automation-badge ${run.status}`}><i />{runNames[run.status]}</span>;
}

function displayedDuration(run: AutomationRun, refreshedAt: number) {
  if (run.status === 'preparing' || run.status === 'running') {
    const startedAt = Date.parse(run.started_at);
    return duration(Number.isNaN(startedAt) ? null : Math.max(0, refreshedAt - startedAt));
  }
  return duration(run.duration_ms);
}

function SessionValue({ value, onOpen }: { value: string; onOpen: () => void }) {
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState('');
  useEffect(() => { if (!copied) return; const timer = window.setTimeout(() => setCopied(false), 1500); return () => window.clearTimeout(timer); }, [copied]);
  return <span className="automation-copy"><button data-workspace-open className="automation-session-link" title="打开 Agent Session" onClick={onOpen}><code>{value}</code></button><button aria-label="复制会话 ID" title={error || '复制会话 ID'} onClick={async () => { try { await navigator.clipboard.writeText(value); setCopied(true); setError(''); } catch { setError('复制失败，请选中文本复制'); } }}>{copied ? <Check /> : <Copy />}</button>{error ? <small role="status">{error}</small> : null}</span>;
}

function shellQuote(value: string) {
  return /^[a-zA-Z0-9_@%+=:,./-]+$/.test(value) ? value : `'${value.replaceAll("'", "'\"'\"'")}'`;
}

function usePageVisible(visible: boolean) {
  const [pageVisible, setPageVisible] = useState(() => !document.hidden);
  useEffect(() => {
    const update = () => setPageVisible(!document.hidden);
    document.addEventListener('visibilitychange', update);
    update();
    return () => document.removeEventListener('visibilitychange', update);
  }, []);
  return visible && pageVisible;
}

function RunHistory({ taskId, visible, refreshKey, onOpenSession, expanded, onExpandedChange }: { taskId: string; visible: boolean; refreshKey: number; onOpenSession: (run: AutomationRun) => void; expanded?: string; onExpandedChange: (id?: string) => void }) {
  const [runs, setRuns] = useState<AutomationRun[]>([]);
  const [loading, setLoading] = useState(true);
  const [moreBusy, setMoreBusy] = useState(false);
  const [hasMore, setHasMore] = useState(false);
  const [error, setError] = useState('');
  useEffect(() => {
    if (!expanded) return;
    let cancelled = false;
    void automationApi.runDetail(taskId, expanded).then(run => {
      if (!cancelled) setRuns(items => items.some(item => item.id === run.id) ? items : [...items, run]);
    }).catch(reason => { if (!cancelled) setError(errorMessage(reason)); });
    return () => { cancelled = true; };
  }, [taskId, expanded]);
  const [output, setOutput] = useState<{ runId: string; kind: RunOutput; content: string }>();
  const [outputLoading, setOutputLoading] = useState(false);
  const [outputError, setOutputError] = useState('');
  const [refreshedAt, setRefreshedAt] = useState(() => Date.now());
  const loaded = useRef(false);
  const runsRef = useRef(runs);
  runsRef.current = runs;

  useEffect(() => {
    if (!visible) return;
    let active = true;
    let fetching = false;
    const refresh = async () => {
      if (!active || fetching) return;
      fetching = true;
      try {
        const next = await automationApi.runs(taskId);
        if (!active) return;
        const earlierActive = runsRef.current.filter((run) => ['preparing', 'running'].includes(run.status) && !next.some((item) => item.id === run.id));
        const updated = await Promise.all(earlierActive.map((run) => automationApi.runDetail(taskId, run.id)));
        if (!active) return;
        setRuns((current) => {
          const merged = new Map(current.map((run) => [run.id, run]));
          [...next, ...updated].forEach((run) => merged.set(run.id, run));
          return [...merged.values()].sort((a, b) => b.id.localeCompare(a.id));
        });
        setRefreshedAt(Date.now());
        if (!loaded.current) { setHasMore(next.length === 50); loaded.current = true; }
        setError('');
      } catch (reason) { if (active) setError(errorMessage(reason)); }
      finally { fetching = false; if (active) setLoading(false); }
    };
    void refresh();
    const timer = window.setInterval(() => { if (!document.hidden) void refresh(); }, 2500);
    return () => { active = false; window.clearInterval(timer); };
  }, [taskId, visible, refreshKey]);

  const loadMore = async () => {
    setMoreBusy(true);
    try {
      const next = await automationApi.runs(taskId, runs.at(-1)?.id);
      setRuns((current) => [...new Map([...current, ...next].map((run) => [run.id, run])).values()].sort((a, b) => b.id.localeCompare(a.id)));
      setHasMore(next.length === 50); setError('');
    } catch (reason) { setError(errorMessage(reason)); }
    finally { setMoreBusy(false); }
  };

  const loadOutput = async (runId: string, kind: RunOutput) => {
    if (output?.runId === runId && output.kind === kind) {
      setOutput(undefined);
      setOutputError('');
      return;
    }
    setOutputLoading(true);
    setOutputError('');
    try {
      const content = await automationApi.runOutput(taskId, runId, kind);
      setOutput({ runId, kind, content });
    } catch (reason) {
      setOutputError(errorMessage(reason));
    } finally {
      setOutputLoading(false);
    }
  };

  return <div className="automation-history">
    {error ? <div className="automation-error" role="alert">{error}</div> : null}
    {loading ? <div className="automation-empty"><LoaderCircle className="automation-spin" /><span>正在加载执行历史…</span></div>
      : !runs.length ? <div className="automation-empty"><History /><h3>暂无执行记录</h3><p>按计划运行或点击“立即运行”后，执行记录会显示在这里。</p></div>
        : <><div className="automation-run-heading"><span>执行时间</span><span>工作区</span><span>参数</span><span>耗时</span><span>状态</span></div>
          {runs.map((run) => <div className="automation-run" key={run.id}>
            <button className="automation-run-summary" aria-expanded={expanded === run.id} onClick={() => { onExpandedChange(expanded === run.id ? undefined : run.id); setOutput(undefined); setOutputError(''); }}>
              <span>{expanded === run.id ? <ChevronDown /> : <ChevronRight />}<span>{dateTime(run.started_at)}<small>{run.source === 'manual' ? '手动运行' : '计划运行'}</small></span></span>
              <span className="automation-ellipsis" title={run.workspace_path ?? ''}>{run.branch || run.workspace_path?.split('/').pop() || '—'}</span>
              <RunParameterSummary run={run} />
              <span>{displayedDuration(run, refreshedAt)}</span><RunBadge run={run} />
            </button>
            {expanded === run.id ? <div className="automation-run-detail"><dl>
              <div className="automation-full-width"><dt>Session ID</dt><dd>{run.session_id ? <SessionValue value={run.session_id} onOpen={() => onOpenSession(run)} /> : run.status === 'running' || run.status === 'preparing' ? '等待 Agent 会话…' : '未获取'}</dd></div>
              <div><dt>开始时间</dt><dd>{dateTime(run.started_at)}</dd></div><div><dt>结束时间</dt><dd>{dateTime(run.finished_at)}</dd></div>
              <div className="automation-full-width"><dt>工作区</dt><dd><code>{run.workspace_path ?? '—'}</code></dd></div>
              <div className="automation-full-width"><dt>分支</dt><dd><code>{run.branch ?? '—'}</code></dd></div>
              <div><dt>进程 ID</dt><dd>{run.agent_pid ?? '—'}</dd></div><div><dt>退出码</dt><dd>{run.exit_code ?? '—'}</dd></div>
              <div className="automation-full-width"><dt>Agent 命令</dt><dd><code>{run.agent_command?.map(shellQuote).join(' ') ?? '—'}</code></dd></div>
              <div className="automation-full-width"><dt>Run ID</dt><dd><code>{run.id}</code></dd></div>
            </dl><RunParameters run={run} /><div className="automation-run-output"><div className="automation-run-output-heading"><span>执行输出</span><div><button className={output?.runId === run.id && output.kind === 'stdio' ? 'active' : ''} disabled={outputLoading} onClick={() => void loadOutput(run.id, 'stdio')}>stdio</button><button className={output?.runId === run.id && output.kind === 'stderr' ? 'active' : ''} disabled={outputLoading} onClick={() => void loadOutput(run.id, 'stderr')}>stderr</button></div></div>{outputLoading ? <p className="automation-output-state">正在读取输出…</p> : null}{outputError ? <p className="automation-output-state error">{outputError}</p> : null}{output?.runId === run.id ? <pre>{output.content || '(空)'}</pre> : null}</div>{run.message ? <p className={`automation-run-message ${run.status}`}>{run.message}</p> : null}</div> : null}
          </div>)}
          {hasMore ? <button className="automation-load-more" disabled={moreBusy} onClick={() => void loadMore()}>{moreBusy ? '加载中…' : '加载更早的记录'}</button> : null}
        </>}
  </div>;
}

interface AutomationDetailProps {
  initialLocation?: AutomationLocation;
  onLocationChange?: (location: AutomationLocation) => void;
  taskId: string;
  visible: boolean;
  refreshKey?: number;
  project: AowProject;
  agents: AowAgent[];
  onTaskChanged: (task?: AutomationTask, mutated?: boolean) => void;
  onTaskDeleted: (taskId: string) => void;
  onOpenSession: (run: AutomationRun) => void;
}

export function AutomationDetail({ taskId, visible, refreshKey: taskRefreshKey = 0, project, agents, onTaskChanged, onTaskDeleted, onOpenSession, initialLocation, onLocationChange }: AutomationDetailProps) {
  const [task, setTask] = useState<AutomationTask>();
  const [status, setStatus] = useState<SchedulerStatus>();
  const [localLocation, setLocalLocation] = useState<AutomationLocation>({ view: 'overview' });
  const location = initialLocation ?? localLocation;
  const tab = location.view;
  const expandedRun = location.runId;
  const changeLocation = (next: AutomationLocation) => { setLocalLocation(next); onLocationChange?.(next); };
  const setTab = (view: AutomationLocation['view']) => changeLocation({ view, runId: view === 'runs' ? expandedRun : undefined });
  const setExpandedRun = (runId?: string) => changeLocation({ view: 'runs', runId });
  const [editorOpen, setEditorOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [runTask, setRunTask] = useState<AutomationTask>();
  const [refreshKey, setRefreshKey] = useState(0);
  const request = useRef(0);
  const pollingVisible = usePageVisible(visible);
  const { confirm, confirmationDialog } = useConfirmation();

  const refresh = useCallback(async (includeStatus = false) => {
    const current = ++request.current;
    try {
      const [taskResult, statusResult] = await Promise.allSettled([automationApi.detail(taskId), includeStatus ? automationApi.status() : Promise.resolve(undefined)]);
      if (current !== request.current) return;
      if (taskResult.status === 'fulfilled') { setTask(taskResult.value); onTaskChanged(taskResult.value); setError(''); }
      else setError(errorMessage(taskResult.reason));
      if (statusResult.status === 'fulfilled' && statusResult.value) setStatus(statusResult.value);
    } catch (reason) { if (current === request.current) setError(errorMessage(reason)); }
  }, [onTaskChanged, taskId]);

  useEffect(() => {
    if (!pollingVisible) return;
    let active = true;
    let fetching = false;
    const poll = async (includeStatus = false) => {
      if (!active || fetching || document.hidden) return;
      fetching = true;
      try { await refresh(includeStatus); }
      finally { fetching = false; }
    };
    void poll(true);
    const timer = window.setInterval(() => void poll(), 3000);
    return () => {
      active = false;
      window.clearInterval(timer);
      request.current += 1;
    };
  }, [refresh, pollingVisible, taskRefreshKey]);

  const apply = (updated: AutomationTask) => { setTask(updated); onTaskChanged(updated, true); };
  const action = async (kind: 'run' | 'toggle' | 'sync' | 'delete') => {
    if (!task || busy) return;
    if (kind === 'run' && task.kind === 'manual' && task.prompt_bindings?.length) { setRunTask(task); return; }
    if (kind === 'delete' && !await confirm(deleteTaskConfirmation(task))) return;
    setBusy(true); setError(''); setNotice('');
    try {
      if (kind === 'run') {
        const result = await automationApi.run(task.id, task.revision);
        setTab('runs'); setRefreshKey((value) => value + 1);
        setNotice(result.run_id ? '已提交运行，等待 Runner 启动。' : '任务仍在执行，已跳过本次触发。');
      } else if (kind === 'delete') {
        await automationApi.remove(task.id);
        onTaskChanged(); onTaskDeleted(task.id);
        return;
      } else {
        apply(kind === 'toggle' ? await automationApi.enabled(task.id, !task.enabled) : await automationApi.sync(task.id));
      }
      void refresh(true);
    } catch (reason) { setError(errorMessage(reason)); }
    finally { setBusy(false); }
  };

  const controls = task ? <div className="automation-actions">
    <button title="立即运行" aria-label="立即运行" className="automation-primary" disabled={busy || (task.max_concurrent_runs === 1 && task.is_running) || status?.ready === false} onClick={() => void action('run')}><Play /><span>立即运行</span></button>
    <button title="编辑" aria-label="编辑" disabled={busy} onClick={() => setEditorOpen(true)}><Pencil /></button>
    {task.kind !== 'manual' ? <button title={task.enabled ? '暂停' : '启用'} aria-label={task.enabled ? '暂停' : '启用'} disabled={busy} onClick={() => void action('toggle')}>{task.enabled ? <Pause /> : <Zap />}</button> : null}
    <button title="删除" aria-label="删除" className="automation-danger" disabled={busy} onClick={() => void action('delete')}><Trash2 /></button>
  </div> : null;

  return <section className="automation-detail-page" aria-label="自动化详情">
    {task ? <header className="automation-detail-heading">
      {task.kind === 'manual' ? <MousePointerClick /> : <CalendarClock />}
      <div className="automation-detail-title">
        <h2 title={task.name}>{task.name}</h2>
        <div><span>{agentNames[task.agent]}</span><span>·</span><span className="automation-detail-workspace" title={`${task.project_name} / ${task.workspace_path}`}>{task.project_name} / {task.workspace_mode === 'temporary' ? '临时目录（TMP）' : task.workspace_path.split('/').pop()}</span></div>
      </div>
      <AutomationTaskBadge task={task} />
      {controls}
    </header> : null}
    {error ? <div className="automation-error" role="alert"><span>{error}</span><button aria-label="关闭错误提示" onClick={() => setError('')}><X /></button></div> : null}
    {notice ? <div className="automation-notice" role="status"><span>{notice}</span><button aria-label="关闭提示" onClick={() => setNotice('')}><X /></button></div> : null}
    {!task && !error ? <div className="automation-empty"><LoaderCircle className="automation-spin" /><span>正在加载自动化…</span></div> : null}
    {task ? <>
      <nav className="automation-tabs" aria-label="自动化详情"><button className={tab === 'overview' ? 'active' : ''} aria-current={tab === 'overview' ? 'page' : undefined} onClick={() => setTab('overview')}>概述</button><button className={tab === 'runs' ? 'active' : ''} aria-current={tab === 'runs' ? 'page' : undefined} onClick={() => setTab('runs')}>执行历史</button></nav>
      <div className="automation-detail-scroll"><div className="automation-detail">
        {task.scheduler_error ? <div className="automation-error"><span>{task.scheduler_error}</span><button disabled={busy} onClick={() => void action('sync')}><RefreshCw />重新同步</button></div> : null}
        {tab === 'runs' ? <RunHistory expanded={expandedRun} onExpandedChange={setExpandedRun} key={task.id} taskId={task.id} visible={pollingVisible} refreshKey={refreshKey} onOpenSession={onOpenSession} /> : <div className="automation-overview">
          <div className="automation-metrics">
            <div><span>{task.kind === 'manual' ? <MousePointerClick /> : <CalendarClock />}{task.kind === 'manual' ? '执行方式' : '运行计划'}</span><strong>{task.kind === 'manual' ? '手动运行' : scheduleName(task.cron, task.interval_seconds)}</strong><small>{task.max_concurrent_runs === 1 ? '禁止重叠执行，执行中自动跳过' : `最多同时执行 ${task.max_concurrent_runs} 个任务`}</small></div>
            {task.kind === 'manual' ? <div><span><FileText />执行变量</span><strong>{variableNames(task.prompt_bindings).length} 个变量</strong><small>{task.prompt_bindings?.length ? '每次运行前填写' : '点击运行即可执行'}</small></div> : <div><span><Clock3 />下次运行</span><strong>{task.enabled ? task.interval_seconds ? '等待系统触发' : dateTime(task.next_run_at) : '已暂停'}</strong><small>{task.interval_seconds ? task.max_concurrent_runs === 1 ? '结束后等待下一次触发' : '达到并发上限时跳过，不排队' : task.cron}</small></div>}
            <div><span><History />最近运行</span><strong>{task.last_run ? dateTime(task.last_run.started_at) : '暂无记录'}</strong>{task.last_run ? <RunBadge run={task.last_run} /> : <small>等待首次运行</small>}</div>
          </div>
          {task.kind === 'manual' && task.prompt_bindings?.length ? <section className="automation-variables" aria-label="任务变量"><strong>执行时填写的变量</strong><div className="automation-variable-list">{variableNames(task.prompt_bindings).map(name => <code key={name}>{name}</code>)}</div></section> : null}
          <dl className="automation-configuration"><div><dt>Agent</dt><dd><AgentIcon agentId={task.agent} />{agentNames[task.agent]}</dd></div><div><dt>执行权限</dt><dd>{task.yolo ? 'Yolo / Full Access' : '标准权限'}</dd></div><div><dt>失败提醒</dt><dd>{task.failure_notification === 'feishu' ? '飞书 Bot' : task.failure_notification === 'wechat' ? '微信 Bot' : '不提醒'}</dd></div><div><dt>工作区方式</dt><dd>{workspaceNames[task.workspace_mode]}</dd></div><div><dt>任务结束清理</dt><dd>{task.workspace_mode === 'new_worktree' ? '强制清理 Worktree' : task.workspace_mode === 'temporary' ? '自动清理临时目录' : '—'}</dd></div><div><dt>基础分支</dt><dd>{task.workspace_mode === 'existing' || task.workspace_mode === 'temporary' ? '—' : <code>{task.base_branch}</code>}</dd></div><div><dt>更新时间</dt><dd>{dateTime(task.updated_at)}</dd></div><div className="automation-full-width"><dt>任务 ID</dt><dd><code>{task.id}</code></dd></div><div className="automation-full-width"><dt>{task.workspace_mode === 'temporary' ? '关联项目工作区' : '工作区'}</dt><dd><code>{task.workspace_path}</code></dd></div></dl>
          <section className="automation-prompt-preview"><h3><FileText />任务内容</h3><MarkdownContent readOnly text={task.prompt} className="automation-prompt-markdown" /></section>{task.precheck_command ? <section className="automation-prompt-preview automation-command-preview"><h3><Terminal />执行前检查<small>{task.precheck_timeout_seconds} 秒超时</small></h3><pre>{task.precheck_command}</pre></section> : null}
        </div>}
      </div></div>
    </> : null}
    {runTask ? <ManualRunDialog task={runTask} onClose={() => setRunTask(undefined)} onStarted={runId => {
      setRunTask(undefined); setTab('runs'); setRefreshKey(value => value + 1);
      setNotice(runId ? '已提交运行，等待 Runner 启动。' : '任务仍在执行，已跳过本次触发。'); void refresh(true);
    }} /> : null}
    {editorOpen && task ? <AutomationEditor task={task} project={project} agents={agents} timezone={status?.timezone} onClose={() => setEditorOpen(false)} onSaved={(updated) => { setEditorOpen(false); apply(updated); void refresh(true); }} /> : null}
    {confirmationDialog}
  </section>;
}

import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import type { editor } from 'monaco-editor';
import { CalendarClock, LoaderCircle, MousePointerClick, Settings2, Terminal, X } from 'lucide-react';
import type { AowAgent } from '../agents/types';
import type { AowProject } from '../../aow/types';
import { notificationsApi } from '../notifications/api';
import { agentNames, errorMessage } from './presentation';
import { automationApi } from './api';
import type { AutomationAgent, AutomationTask, TaskInput, TaskKind, WorkspaceMode } from './types';

import { identifyVariables, variableNames } from './variables';

const Editor = lazy(() => import('../editor/MonacoEditor'));

type Cadence = 'interval' | 'hourly' | 'daily' | 'weekdays' | 'weekly' | 'custom';
function parseSchedule(cron: string): { cadence: Cadence; time: string; weekday: string; minute: string } {
  const [minute, hour, day, month, weekday] = cron.split(/\s+/);
  if (/^\d+$/.test(minute) && day === '*' && month === '*') {
    if (hour === '*' && weekday === '*') return { cadence: 'hourly', time: '09:00', weekday: '1', minute };
    if (/^\d+$/.test(hour)) {
      const cadence = weekday === '*' ? 'daily' : weekday === '1-5' ? 'weekdays' : /^[0-7]$/.test(weekday) ? 'weekly' : 'custom';
      return { cadence, time: `${hour.padStart(2, '0')}:${minute.padStart(2, '0')}`, weekday: /^[0-7]$/.test(weekday) ? weekday === '7' ? '0' : weekday : '1', minute };
    }
  }
  return { cadence: 'custom', time: '09:00', weekday: '1', minute: '0' };
}

export function AutomationEditor({ task, kind = 'scheduled', project, agents, timezone, onClose, onSaved }: {
  task?: AutomationTask;
  kind?: TaskKind;
  project: AowProject;
  agents: AowAgent[];
  timezone?: string;
  onClose: () => void;
  onSaved: (task: AutomationTask) => void;
}) {
  const initialWorktree = project.worktrees.find((worktree) => worktree.is_main) ?? project.worktrees[0];
  const [draft, setDraft] = useState<TaskInput>(() => task ? { ...task, kind: task.kind ?? 'scheduled', prompt_bindings: task.prompt_bindings ?? [], failure_notification: task.failure_notification ?? null } : {
    kind, prompt_bindings: [], name: '', prompt: '', agent: (agents.find((agent) => agent.available && Object.hasOwn(agentNames, agent.id))?.id as AutomationAgent | undefined) ?? 'codex',
    project_id: project.id, workspace_mode: 'new_worktree', workspace_path: initialWorktree?.path ?? '',
    cleanup_worktree: true, base_branch: initialWorktree?.branch || 'HEAD', cron: '0 9 * * *', interval_seconds: null, max_concurrent_runs: 1, enabled: true, yolo: true, precheck_command: '', precheck_timeout_seconds: 60, failure_notification: null,
  });
  const [schedule, setSchedule] = useState(() => ({ ...parseSchedule(draft.cron), ...(draft.interval_seconds ? { cadence: 'interval' as Cadence } : {}) }));
  const [lastConcurrentRuns, setLastConcurrentRuns] = useState(() => draft.max_concurrent_runs > 1 ? draft.max_concurrent_runs : 3);
  const initialSeconds = draft.interval_seconds;
  const initialUnit = initialSeconds ? initialSeconds % 3600 === 0 ? 3600 : initialSeconds % 60 === 0 ? 60 : 1 : 60;
  const [intervalUnit, setIntervalUnit] = useState(initialUnit);
  const [intervalAmount, setIntervalAmount] = useState(initialSeconds ? String(initialSeconds / initialUnit) : '');
  const [customCron, setCustomCron] = useState(draft.cron);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const manual = draft.kind === 'manual';
  const names = variableNames(draft.prompt_bindings);
  const [botStatus, setBotStatus] = useState<'loading' | 'ready' | 'error'>('loading');
  const [availableBots, setAvailableBots] = useState<string[]>([]);
  const dialogRef = useRef<HTMLDialogElement>(null);
  const nameRef = useRef<HTMLInputElement>(null);
  const promptEditorRef = useRef<editor.IStandaloneCodeEditor | null>(null);
  const update = <K extends keyof TaskInput>(key: K, value: TaskInput[K]) => setDraft((current) => ({ ...current, [key]: value }));

  useEffect(() => {
    let active = true;
    void notificationsApi.notificationSettings().then(settings => {
      if (active) {
        setAvailableBots(settings.im.providers.filter(provider => provider.provider === 'wechat' || provider.secret_configured).map(provider => provider.provider));
        setBotStatus('ready');
      }
    }).catch(() => { if (active) setBotStatus('error'); });
    return () => { active = false; };
  }, []);

  useEffect(() => {
    const dialog = dialogRef.current;
    dialog?.showModal(); nameRef.current?.focus();
    return () => { dialog?.close(); };
  }, []);

  const save = async (event: React.FormEvent) => {
    event.preventDefault();
    if (busy) return;
    if (!draft.prompt.trim()) {
      setError('请输入任务内容。');
      promptEditorRef.current?.focus();
      return;
    }
    if (new TextEncoder().encode(draft.prompt).length > 65536) {
      setError('任务内容不能超过 64 KiB。');
      promptEditorRef.current?.focus();
      return;
    }
    const [hour, minute] = schedule.time.split(':').map(Number);
    const cron = schedule.cadence === 'custom' ? customCron.trim()
      : schedule.cadence === 'hourly' ? `${Number(schedule.minute)} * * * *`
        : `${minute} ${hour} * * ${schedule.cadence === 'daily' ? '*' : schedule.cadence === 'weekdays' ? '1-5' : schedule.weekday}`;
    const input = { ...draft, enabled: manual ? true : draft.enabled, project_id: project.id, name: draft.name.trim(), cleanup_worktree: draft.workspace_mode === 'new_worktree' ? true : draft.cleanup_worktree, cron: manual || schedule.cadence === 'interval' ? '' : cron, interval_seconds: !manual && schedule.cadence === 'interval' ? Number(intervalAmount) * intervalUnit : null };
    setBusy(true); setError('');
    try { onSaved(task ? await automationApi.update(task.id, input, task.revision) : await automationApi.create(input)); }
    catch (reason) { setError(errorMessage(reason)); setBusy(false); }
  };

  return createPortal(<dialog ref={dialogRef} className="automation-editor" aria-labelledby="automation-editor-title"
    onCancel={(event) => { event.preventDefault(); if (!busy) onClose(); }} onKeyDown={(event) => event.stopPropagation()}>
    <form onSubmit={(event) => void save(event)}>
      <header><div>{manual ? <MousePointerClick /> : <CalendarClock />}<h2 id="automation-editor-title">{task ? manual ? '编辑手动任务' : '编辑自动化' : manual ? '创建手动任务' : '创建自动化'}</h2></div><button type="button" disabled={busy} aria-label="关闭" onClick={onClose}><X /></button></header>
      <div className="automation-editor-body">
        <section className="automation-prompt-editor">
          <label htmlFor="automation-name">名称</label>
          <input id="automation-name" ref={nameRef} className="automation-name-input" placeholder="例如：每日代码检查" required maxLength={200} value={draft.name} onChange={(event) => update('name', event.target.value)} />
          <div className="automation-prompt-label"><span id="automation-prompt-label">任务内容</span><small>Markdown</small></div>
          <div className="automation-prompt-input" role="group" aria-labelledby="automation-prompt-label">
            <div className="automation-prompt-monaco">
              <Suspense fallback={<span className="automation-hint">正在加载编辑器…</span>}>
                <Editor language="markdown" theme="vs-dark" value={draft.prompt} saveViewState={false}
                  loading={<span className="automation-hint">正在加载编辑器…</span>}
                  options={{
                    ariaLabel: '任务内容', placeholder: '描述希望 Agent 执行的任务、关注的文件，以及预期的结果…',
                    automaticLayout: true, readOnly: busy, minimap: { enabled: false },
                    fontSize: 13, lineHeight: 22, lineNumbersMinChars: 3, wordWrap: 'on',
                    scrollBeyondLastLine: false, padding: { top: 10, bottom: 10 },
                    quickSuggestions: false, wordBasedSuggestions: 'off', suggestOnTriggerCharacters: false,
                  }}
                  onMount={instance => { promptEditorRef.current = instance; }}
                  onChange={value => { const prompt = value ?? ''; setDraft(current => prompt === current.prompt ? current : { ...current, prompt, prompt_bindings: current.kind === 'manual' ? identifyVariables(prompt) : [] }); }} />
              </Suspense>
            </div>
          </div>
          {manual ? <section className="automation-variables" aria-label="任务变量" aria-live="polite">
            <strong>执行时填写的变量 <small>{names.length}</small></strong>
            <p className="automation-hint">使用 {'{{变量名}}'} 插入变量；同名变量只需填写一次。</p>
            {names.length ? <div className="automation-variable-list">{names.map(name => <code key={name}>{name}</code>)}</div> : <p className="automation-hint">暂无变量，运行时将直接执行。</p>}
          </section> : null}
        </section>
        <aside className="automation-settings">
          <h3><Settings2 />执行配置</h3>
          <div className="automation-agent-setting"><span>Agent</span><div className="automation-agent-row"><select aria-label="Agent" value={draft.agent} onChange={(event) => update('agent', event.target.value as AutomationAgent)}>
            {Object.entries(agentNames).map(([id, name]) => <option key={id} value={id} disabled={!agents.some((agent) => agent.id === id && agent.available)}>{name}{agents.some((agent) => agent.id === id && agent.available) ? '' : ' · 未安装'}</option>)}
          </select><label className="automation-yolo-option"><input type="checkbox" checked={draft.yolo} onChange={(event) => update('yolo', event.target.checked)} />Yolo</label></div></div>
          <label><span>工作区方式</span><select aria-label="工作区" value={draft.workspace_mode} onChange={(event) => { const mode = event.target.value as WorkspaceMode; setDraft((current) => ({ ...current, workspace_mode: mode, cleanup_worktree: mode === 'new_worktree' ? true : current.cleanup_worktree })); }}>
            <option value="new_worktree">每次新建 Worktree</option><option value="new_branch">在现有工作区新建分支</option><option value="existing">使用现有工作区</option><option value="temporary">每次新建临时目录（TMP）</option>
          </select></label>
          <label><span>{draft.workspace_mode === 'temporary' ? '关联项目工作区' : draft.workspace_mode === 'new_worktree' ? '参考工作区' : '执行工作区'}</span><select aria-label={draft.workspace_mode === 'temporary' ? '关联项目工作区' : draft.workspace_mode === 'new_worktree' ? '参考工作区' : '执行工作区'} required value={draft.workspace_path} onChange={(event) => update('workspace_path', event.target.value)}>
            <option value="" disabled>选择工作区</option>
            {project.worktrees.map((worktree) => <option key={worktree.path} value={worktree.path}>{worktree.branch || 'detached'} · {worktree.path.split('/').pop()}</option>)}
          </select></label>
          {draft.workspace_mode === 'temporary' ? <p className="automation-hint">每次运行会在系统临时目录中创建空工作区，结束后自动删除；该任务的 Agent 会话不会出现在项目的普通会话列表中。</p> : null}
          {draft.workspace_mode !== 'existing' && draft.workspace_mode !== 'temporary' ? <label><span>基础分支</span><input aria-label="基础分支" required list="automation-branches" value={draft.base_branch} onChange={(event) => update('base_branch', event.target.value)} /><datalist id="automation-branches">{[...new Set(project.worktrees.map((worktree) => worktree.branch).filter(Boolean))].map((branch) => <option key={branch} value={branch} />)}</datalist></label> : null}
          {draft.workspace_mode === 'new_worktree' ? <p className="automation-hint">任务结束时会强制清理 Worktree，丢弃其中的未提交改动；自动创建的分支仍会保留。</p> : null}
          {draft.workspace_mode === 'new_branch' ? <p className="automation-hint">执行时会创建并切换到新分支；工作区须无未提交修改。</p> : null}
          <div className="automation-settings-divider" />
          <div className="automation-schedule-heading"><h3>{manual ? <MousePointerClick /> : <CalendarClock />}{manual ? '手动执行' : '运行计划'}</h3><label className="automation-checkbox"><input type="checkbox" checked={draft.max_concurrent_runs === 1} onChange={(event) => { if (event.target.checked) { if (draft.max_concurrent_runs > 1) setLastConcurrentRuns(draft.max_concurrent_runs); update('max_concurrent_runs', 1); } else update('max_concurrent_runs', lastConcurrentRuns); }} />禁止重叠执行</label></div>
          {draft.max_concurrent_runs > 1 ? <label><span>最大同时执行数</span><input aria-label="最大同时执行数" type="number" required min="2" max="10" step="1" value={draft.max_concurrent_runs} onChange={(event) => { const value = Number(event.target.value); setLastConcurrentRuns(value); update('max_concurrent_runs', value); }} /><small>达到上限时跳过本次触发，不排队。</small></label> : null}
          {!manual ? <>
          <label><span>频率</span><select aria-label="运行计划" value={schedule.cadence} onChange={(event) => setSchedule((current) => ({ ...current, cadence: event.target.value as Cadence }))}>
            <option value="interval">固定间隔</option><option value="hourly">每小时</option><option value="daily">每天</option><option value="weekdays">工作日</option><option value="weekly">每周</option><option value="custom">自定义 Cron</option>
          </select></label>
          {schedule.cadence === 'interval' ? <div className="automation-interval-fields">
            <label><span>间隔</span><input aria-label="运行间隔" type="number" required min="1" max={Math.floor(2678400 / intervalUnit)} step="1" placeholder="填写间隔" value={intervalAmount} onChange={(event) => setIntervalAmount(event.target.value)} /></label>
            <label><span>单位</span><select aria-label="间隔单位" value={intervalUnit} onChange={(event) => setIntervalUnit(Number(event.target.value))}><option value={1}>秒</option><option value={60}>分钟</option><option value={3600}>小时</option></select></label>
          </div> : schedule.cadence === 'custom' ? <label><span>Cron 表达式</span><input aria-label="Cron 表达式" required value={customCron} onChange={(event) => setCustomCron(event.target.value)} placeholder="0 9 * * 1-5" /><small>分 时 日 月 星期 · 支持 *、列表、范围、步长</small></label>
            : schedule.cadence === 'hourly' ? <label><span>每小时的第几分钟</span><input aria-label="每小时的第几分钟" type="number" required min="0" max="59" value={schedule.minute} onChange={(event) => setSchedule((current) => ({ ...current, minute: event.target.value }))} /></label>
              : <label><span>时间</span><input aria-label="时间" type="time" required value={schedule.time} onChange={(event) => setSchedule((current) => ({ ...current, time: event.target.value }))} /></label>}
          {schedule.cadence === 'weekly' ? <label><span>星期</span><select aria-label="星期" value={schedule.weekday} onChange={(event) => setSchedule((current) => ({ ...current, weekday: event.target.value }))}>{['日', '一', '二', '三', '四', '五', '六'].map((day, index) => <option key={day} value={index}>星期{day}</option>)}</select></label> : null}
          <p className="automation-hint">{schedule.cadence === 'interval' ? '启用后等待首个间隔，再按间隔触发。' : `按本机时区运行${timezone ? `：${timezone}` : ''}`}</p>
          </> : <p className="automation-hint">点击运行后填写变量，即可执行任务。</p>}
          <div className="automation-settings-divider" />
          <p className="automation-hint">{draft.max_concurrent_runs === 1 ? '上次执行未结束时跳过本次触发。' : `最多同时执行 ${draft.max_concurrent_runs} 个任务；达到上限时跳过本次触发。`}</p>
          <details open={!!task?.precheck_command}><summary><Terminal />执行前检查<span>可选</span></summary>
            <label><span>检查命令</span><textarea aria-label="检查命令" rows={3} value={draft.precheck_command} onChange={(event) => update('precheck_command', event.target.value)} placeholder="退出码为 0 时继续执行" /></label>
            <label><span>超时时间</span><select aria-label="超时时间" value={draft.precheck_timeout_seconds} onChange={(event) => update('precheck_timeout_seconds', Number(event.target.value))}>{[30, 60, 120, 300, 600].map((seconds) => <option key={seconds} value={seconds}>{seconds} 秒</option>)}</select></label>
          </details>
          <div className="automation-settings-divider" />
          <label><span>失败提醒</span><select aria-label="失败提醒" value={draft.failure_notification ?? ''} disabled={busy} onChange={event => update('failure_notification', event.target.value === 'feishu' || event.target.value === 'wechat' ? event.target.value : null)}>
            <option value="">不提醒</option>
            {(['feishu', 'wechat'] as const).map(provider => <option key={provider} value={provider} disabled={!availableBots.includes(provider)}>{provider === 'feishu' ? '飞书' : '微信'} Bot{botStatus === 'ready' && !availableBots.includes(provider) ? ' · 当前环境未配置' : ''}</option>)}
          </select></label>
          <p className="automation-hint">{botStatus === 'loading' ? '正在检查 IM Bot 配置…' : botStatus === 'error' ? '无法读取 IM Bot 配置，已有提醒设置仍会保留。' : draft.failure_notification && !availableBots.includes(draft.failure_notification) ? `当前环境未配置${draft.failure_notification === 'feishu' ? '飞书' : '微信'} Bot，已保留提醒设置；配置完成后，后续执行失败时会发送提醒。` : !availableBots.length ? '在 Settings → IM 配置飞书或微信 Bot 后，可选择失败提醒。' : '任务执行失败时通过所选 Bot 提醒；跳过和中断不提醒。'}</p>
        </aside>
      </div>
      {error ? <div className="automation-error" role="alert">{error}</div> : null}
      <footer>{!manual ? <label className="automation-checkbox"><input type="checkbox" checked={draft.enabled} onChange={(event) => update('enabled', event.target.checked)} />启用自动化</label> : <span />}<div><button type="button" disabled={busy} onClick={onClose}>取消</button><button className="automation-primary" type="submit" disabled={busy || !draft.workspace_path || !agents.some((agent) => agent.id === draft.agent && agent.available)}>{busy ? <LoaderCircle className="automation-spin" /> : null}{busy ? '保存中…' : task ? '保存更改' : manual ? '创建手动任务' : '创建自动化'}</button></div></footer>
    </form>
  </dialog>, document.body);
}

import { useCallback, useEffect, useId, useRef, useState } from 'react';
import { CalendarClock, LoaderCircle, MousePointerClick, Plus, RefreshCw } from 'lucide-react';
import type { AowAgent } from '../agents/types';
import type { AowProject } from '../../aow/types';
import { withFloatingOpen } from '../../aow/floatingWorkspaceState';
import { AutomationEditor } from './AutomationEditor';
import { AutomationTaskBadge } from './AutomationTaskBadge';
import { AutomationTaskMenu } from './AutomationTaskMenu';
import { deleteTaskConfirmation } from './deleteTaskConfirmation';
import { variableNames } from './variables';
import { automationApi } from './api';
import { errorMessage, scheduleName } from './presentation';
import type { AutomationTask, SchedulerStatus, TaskKind } from './types';
import { useConfirmation } from '../../components/ConfirmationDialog';
import { AowIconButton } from '../../components/AowIconButton';
import { AowPanel, AowPanelStack } from '../../components/AowPanel';
import { AowListRow } from '../../components/AowListRow';
import './automations.css';

interface AutomationPanelProps {
  project: AowProject;
  agents: AowAgent[];
  activeTaskId?: string;
  refreshKey?: number;
  onOpenTask: (task: AutomationTask) => void;
  onTaskChanged: (task?: AutomationTask, mutated?: boolean) => void;
  onTaskDeleted: (taskId: string) => void;
}

export function AutomationPanel({ project, agents, activeTaskId, refreshKey = 0, onOpenTask, onTaskChanged, onTaskDeleted }: AutomationPanelProps) {
  const panelId = useId();
  const [collapsedGroups, setCollapsedGroups] = useState<Partial<Record<TaskKind, boolean>>>({});
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [status, setStatus] = useState<SchedulerStatus>();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [editorOpen, setEditorOpen] = useState(false);
  const [creatingKind, setCreatingKind] = useState<TaskKind>('scheduled');
  const [editingTask, setEditingTask] = useState<AutomationTask>();
  const [busy, setBusy] = useState(false);
  const [contextMenu, setContextMenu] = useState<{ taskId: string; x: number; y: number }>();
  const dismissMenu = useCallback(() => setContextMenu(undefined), []);
  const menuTask = contextMenu ? tasks.find(task => task.id === contextMenu.taskId) : undefined;
  const { confirm, confirmationDialog } = useConfirmation();
  const request = useRef(0);

  const refresh = useCallback(async (includeStatus = false) => {
    const current = ++request.current;
    try {
      const [tasksResult, statusResult] = await Promise.allSettled([automationApi.list(project.id), includeStatus ? automationApi.status() : Promise.resolve(undefined)]);
      if (current !== request.current) return;
      if (tasksResult.status === 'fulfilled') { setTasks(tasksResult.value); setError(''); }
      else setError(errorMessage(tasksResult.reason));
      if (statusResult.status === 'fulfilled' && statusResult.value) setStatus(statusResult.value);
    } finally { if (current === request.current) setLoading(false); }
  }, [project.id]);

  useEffect(() => { setLoading(true); void refresh(true); }, [refresh, refreshKey]);

  const apply = (task: AutomationTask) => {
    setTasks((items) => items.some((item) => item.id === task.id)
      ? items.map((item) => item.id === task.id ? task : item)
      : [task, ...items]);
    onTaskChanged(task, true);
  };

  const action = async (task: AutomationTask, kind: 'toggle' | 'delete') => {
    if (busy) return;
    if (kind === 'delete' && !await confirm(deleteTaskConfirmation(task))) return;
    setBusy(true); setError('');
    try {
      if (kind === 'delete') {
        await automationApi.remove(task.id);
        request.current += 1;
        setTasks(items => items.filter(item => item.id !== task.id));
        onTaskDeleted(task.id);
      } else {
        apply(await automationApi.enabled(task.id, !task.enabled));
      }
    } catch (reason) { setError(errorMessage(reason)); }
    finally { setBusy(false); }
  };

  return <section className="automation-panel" aria-label={`${project.name} 自动化`}>
    {error ? <div className="automation-panel-error" role="alert">{error}</div> : null}
    <AowPanelStack>
    {(['scheduled', 'manual'] as const).map(kind => {
      const manual = kind === 'manual';
      const items = tasks.filter(task => (task.kind ?? 'scheduled') === kind);
      const label = manual ? '手动任务' : '自动化';
      const title = manual ? 'Manual' : 'Schedule';
      const collapsed = collapsedGroups[kind] ?? (!loading && !error && items.length === 0);
      const bodyId = `${panelId}-${kind}`;
      return <AowPanel className="automation-panel-group" key={kind} bodyClassName="automation-panel-list" bodyRole="list" title={title} icon={manual ? <MousePointerClick /> : <CalendarClock />} collapsed={collapsed} controlsId={bodyId}
          onCollapsedChange={next => { setCollapsedGroups(groups => ({ ...groups, [kind]: next })); dismissMenu(); }} actions={<>
          <AowIconButton title={`刷新${label}`} aria-label={`刷新${label}`} disabled={loading} onClick={() => { setLoading(true); void refresh(true); }}><RefreshCw className={loading ? 'automation-spin' : ''} /></AowIconButton>
          <AowIconButton title={`创建${label}`} aria-label={`创建${label}`} disabled={!!project.error || !project.worktrees.length} onClick={() => { setCreatingKind(kind); setEditingTask(undefined); setEditorOpen(true); }}><Plus /></AowIconButton>
        </>}>
          {loading ? <div className="automation-panel-state"><LoaderCircle className="automation-spin" />正在加载任务…</div> : null}
          {!loading && !items.length ? <div className="automation-panel-state">{manual ? <MousePointerClick /> : <CalendarClock />}<strong>暂无{manual ? '手动任务' : '自动化任务'}</strong><span>点击右上角新增{label}。</span></div> : null}
          {!loading && items.map(task => <AowListRow key={task.id} role="listitem" className={`automation-panel-row${task.id === activeTaskId ? ' active' : ''}`}
            title={task.name} tooltip={`${task.name} · ID: ${task.id}`} icon={manual ? <MousePointerClick /> : <CalendarClock />} menuLabel="任务操作" onOpen={() => onOpenTask(task)}
            menuExpanded={contextMenu?.taskId === task.id} onMenu={(x, y) => setContextMenu({ taskId: task.id, x, y })}>
            <small className="automation-panel-meta"><AutomationTaskBadge task={task} /><span aria-hidden="true">•</span><span className="automation-panel-summary"><code>{task.id}</code><span> · </span>{manual ? `${variableNames(task.prompt_bindings).length} 个变量` : scheduleName(task.cron, task.interval_seconds)}</span></small>
          </AowListRow>)}
      </AowPanel>;
    })}
    </AowPanelStack>
    {contextMenu && menuTask ? <AutomationTaskMenu {...contextMenu} task={menuTask} busy={busy} onClose={dismissMenu}
      onOpen={() => onOpenTask(menuTask)} onOpenFloating={() => withFloatingOpen(() => onOpenTask(menuTask))}
      onEdit={() => { setEditingTask(menuTask); setEditorOpen(true); }}
      onToggle={() => void action(menuTask, 'toggle')} onDelete={() => void action(menuTask, 'delete')} /> : null}
    {editorOpen ? <AutomationEditor task={editingTask} kind={creatingKind} project={project} agents={agents} timezone={status?.timezone} onClose={() => setEditorOpen(false)} onSaved={(task) => { setEditorOpen(false); apply(task); if (!editingTask) onOpenTask(task); }} /> : null}
    {confirmationDialog}
  </section>;
}

import type { AutomationTask } from './types';

export function AutomationTaskBadge({ task }: { task: AutomationTask }) {
  const state = task.scheduler_error ? 'failed' : task.is_running ? 'running' : task.enabled ? 'enabled' : 'paused';
  return <span className={`automation-badge ${state}`}><i />{task.scheduler_error ? '配置异常' : task.is_running ? '执行中' : task.kind === 'manual' ? '手动' : task.enabled ? '已启用' : '已暂停'}</span>;
}

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Pause, Pencil, Trash2, Zap } from 'lucide-react';
import { WorkspaceMenuLabel } from '../../aow/WorkspaceMenuLabel';
import type { AutomationTask } from './types';

export function AutomationTaskMenu({ x, y, task, busy, onClose, onOpen, onOpenFloating, onEdit, onToggle, onDelete }: {
  x: number;
  y: number;
  task: AutomationTask;
  busy: boolean;
  onClose: () => void;
  onOpen: () => void;
  onOpenFloating: () => void;
  onEdit: () => void;
  onToggle: () => void;
  onDelete: () => void;
}) {
  const menu = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ x, y });

  useLayoutEffect(() => {
    const bounds = menu.current?.getBoundingClientRect();
    if (!bounds) return;
    setPosition({
      x: Math.max(4, Math.min(x, window.innerWidth - bounds.width - 4)),
      y: Math.max(4, Math.min(y, window.innerHeight - bounds.height - 4)),
    });
  }, [x, y]);

  useEffect(() => {
    const close = () => onClose();
    const key = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
    window.addEventListener('pointerdown', close);
    window.addEventListener('scroll', close, true);
    window.addEventListener('resize', close);
    window.addEventListener('keydown', key);
    return () => {
      window.removeEventListener('pointerdown', close);
      window.removeEventListener('scroll', close, true);
      window.removeEventListener('resize', close);
      window.removeEventListener('keydown', key);
    };
  }, [onClose]);

  const action = (callback: () => void) => () => { onClose(); callback(); };
  return createPortal(<div ref={menu} className="project-aow-context-menu automation-task-menu"
    style={{ left: position.x, top: position.y }} role="menu" aria-label={`${task.name} 自动化操作`}
    onPointerDown={event => event.stopPropagation()} onContextMenu={event => event.preventDefault()}>
    <button role="menuitem" onClick={action(onOpen)}><WorkspaceMenuLabel action="open" /></button>
    <button role="menuitem" onClick={action(onOpenFloating)}><WorkspaceMenuLabel action="floating" /></button>
    <hr />
    <button role="menuitem" disabled={busy} onClick={action(onEdit)}><Pencil />编辑</button>
    {task.kind !== 'manual' ? <button role="menuitem" disabled={busy} onClick={action(onToggle)}>{task.enabled ? <Pause /> : <Zap />}{task.enabled ? '暂停' : '启用'}</button> : null}
    <button role="menuitem" className="danger" disabled={busy} onClick={action(onDelete)}><Trash2 />删除</button>
  </div>, document.body);
}

import { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { LoaderCircle, MousePointerClick, Play, X } from 'lucide-react';
import { automationApi } from './api';
import { errorMessage } from './presentation';
import type { AutomationTask } from './types';
import { variableNames } from './variables';

export function ManualRunDialog({ task, onClose, onStarted }: {
  task: AutomationTask;
  onClose: () => void;
  onStarted: (runId: string | null) => void;
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const [values, setValues] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const submitting = useRef(false);
  const names = variableNames(task.prompt_bindings);
  useEffect(() => {
    const element = dialog.current;
    element?.showModal();
    element?.querySelector('textarea')?.focus();
    return () => element?.close();
  }, []);
  const ready = names.every(name => Object.hasOwn(values, name) && !!values[name].trim());
  return createPortal(<dialog ref={dialog} className="automation-editor automation-run-dialog" aria-labelledby="manual-run-title"
    onCancel={event => { event.preventDefault(); if (!submitting.current) onClose(); }} onKeyDown={event => event.stopPropagation()}>
    <form onSubmit={async event => {
      event.preventDefault();
      if (!ready || submitting.current) return;
      submitting.current = true; setBusy(true); setError('');
      try {
        const result = await automationApi.run(task.id, task.revision, values);
        onStarted(result.run_id);
      } catch (reason) { setError(errorMessage(reason)); }
      finally { submitting.current = false; setBusy(false); }
    }}>
      <header><div><MousePointerClick /><h2 id="manual-run-title">运行手动任务</h2></div><button type="button" aria-label="关闭" disabled={busy} onClick={onClose}><X /></button></header>
      <div className="automation-run-fields">
        <p>{task.name}</p><p className="automation-hint">填写本次执行的变量值，所有变量均为必填。</p>
        {names.map((name, index) => <label key={name} htmlFor={`manual-variable-${index}`}><span>{name}</span>
          <textarea id={`manual-variable-${index}`} required rows={2} disabled={busy} value={Object.hasOwn(values, name) ? values[name] : ''}
            onChange={event => setValues(current => ({ ...current, [name]: event.target.value }))} />
        </label>)}
      </div>
      {error ? <div className="automation-error" role="alert">{error}</div> : null}
      <footer><span /><div><button type="button" disabled={busy} onClick={onClose}>取消</button><button type="submit" className="automation-primary" disabled={busy || !ready}>{busy ? <LoaderCircle className="automation-spin" /> : <Play />}{busy ? '提交中…' : '运行'}</button></div></footer>
    </form>
  </dialog>, document.body);
}

import { CalendarClock, ChevronRight, MousePointerClick } from 'lucide-react';
import { automationApi } from './api';
import { agentNames, dateTime, duration, runNames, scheduleName, workspaceNames } from './presentation';
import type { AutomationRun } from './types';
import { sessionsApi } from '../sessions/api';
import { AgentIcon } from '../agents/AgentIcon';
import { RunParameters } from './RunParameters';
import { MarkdownContent } from '../../components/MarkdownContent';
import type { AowAgentSession } from '../sessions/types';
import type { MobileNavigate } from '../../mobile/mobileState';
import { MobilePageHeader, MobileRefresh, MobileState } from '../../mobile/MobilePrimitives';
import { useMobileResource, useMobileScroll, type MobileRoute } from '../../mobile/mobileState';

function taskState(task: { scheduler_error: string | null; is_running: boolean; enabled: boolean; kind?: string }) {
  return task.scheduler_error ? '配置异常' : task.is_running ? '执行中' : task.kind === 'manual' ? '手动' : task.enabled ? '已启用' : '已暂停';
}

export function MobileAutomations({ route, projectId, visible, navigate, back }: {
  route: MobileRoute; projectId: string; visible: boolean; navigate: MobileNavigate; back: () => void;
}) {
  const tasks = useMobileResource(`automations.${projectId}`, () => automationApi.list(projectId), visible && !route.task);
  const scroll = useMobileScroll(`automations.${projectId}`, !!tasks.data);
  if (route.task) return <MobileAutomationTask route={route} navigate={navigate} back={back} />;
  return <section className="mobile-content-page">
    <MobilePageHeader title="自动化" subtitle="项目任务与执行记录" actions={<MobileRefresh reload={tasks.reload} loading={tasks.loading} />} />
    <div className="mobile-scroll" ref={scroll}>
      <MobileState loading={tasks.loading && !tasks.data} error={tasks.error} retry={tasks.reload} empty={tasks.data?.length === 0 ? '这个项目还没有自动化任务。' : undefined} />
      <div className="mobile-list">{tasks.data?.map((task) => <button className="mobile-list-row" key={task.id} onClick={() => navigate({ workspace: route.workspace, view: 'automations', task: task.id })}>
        <div className="mobile-row-icon">{task.kind === 'manual' ? <MousePointerClick size={21} /> : <CalendarClock size={21} />}</div><div className="mobile-row-main"><strong>{task.name}</strong><span>{task.kind === 'manual' ? '手动运行' : task.enabled ? scheduleName(task.cron, task.interval_seconds) : '已停用'} · {task.is_running ? '执行中' : task.last_run ? runNames[task.last_run.status] : '尚未执行'}</span></div><ChevronRight size={17} />
      </button>)}</div>
    </div>
  </section>;
}

function MobileAutomationTask({ route, navigate, back }: { route: MobileRoute; navigate: MobileNavigate; back: () => void }) {
  const task = useMobileResource(`task.${route.task}`, () => automationApi.detail(route.task!));
  const runs = useMobileResource(`runs.${route.task}`, () => automationApi.runs(route.task!));
  const scroll = useMobileScroll(`task.${route.task}`, !!task.data);
  if (route.run) return <MobileAutomationRun route={route} back={back} />;
  return <section className="mobile-content-page">
    <MobilePageHeader title={task.data?.name ?? '自动化任务'} back={back} actions={<MobileRefresh reload={() => { task.reload(); runs.reload(); }} loading={task.loading || runs.loading} />} />
    <div className="mobile-scroll" ref={scroll}>
      <MobileState loading={task.loading && !task.data} error={task.error} retry={task.reload} />
      {task.data && <><section className="mobile-automation-card"><h3>任务配置</h3><dl className="mobile-automation-details">
        <div><dt>任务 ID</dt><dd><code>{task.data.id}</code></dd></div>
        <div><dt>项目</dt><dd>{task.data.project_name}<small><code>{task.data.project_id}</code></small></dd></div>
        <div><dt>状态</dt><dd>{taskState(task.data)}</dd></div>
        <div><dt>Agent</dt><dd>{agentNames[task.data.agent]}</dd></div>
        <div><dt>执行权限</dt><dd>{task.data.yolo ? 'Yolo / Full Access' : '标准权限'}</dd></div>
        <div><dt>失败提醒</dt><dd>{task.data.failure_notification === 'feishu' ? '飞书 Bot' : task.data.failure_notification === 'wechat' ? '微信 Bot' : '不提醒'}</dd></div>
        {task.data.kind === 'manual' ? <div><dt>执行方式</dt><dd>手动运行</dd></div> : <div><dt>运行计划</dt><dd>{scheduleName(task.data.cron, task.data.interval_seconds)}<small><code>{task.data.interval_seconds ? `${task.data.interval_seconds} 秒` : task.data.cron}</code></small></dd></div>}
        <div><dt>最大并发</dt><dd>{task.data.max_concurrent_runs === 1 ? '1（禁止重叠执行）' : task.data.max_concurrent_runs}</dd></div>
        {task.data.kind !== 'manual' ? <div><dt>下次运行</dt><dd>{task.data.enabled ? dateTime(task.data.next_run_at) : '已暂停'}</dd></div> : null}
        <div><dt>工作区方式</dt><dd>{workspaceNames[task.data.workspace_mode]}</dd></div>
        <div><dt>{task.data.workspace_mode === 'temporary' ? '关联项目工作区' : '工作区'}</dt><dd><code>{task.data.workspace_path}</code></dd></div>
        <div><dt>基础分支</dt><dd>{task.data.workspace_mode === 'existing' || task.data.workspace_mode === 'temporary' ? '—' : <code>{task.data.base_branch}</code>}</dd></div>
        <div><dt>结束后清理</dt><dd>{task.data.workspace_mode === 'new_worktree' ? '强制清理 Worktree' : task.data.workspace_mode === 'temporary' ? '自动清理临时目录' : '—'}</dd></div>
        <div><dt>创建时间</dt><dd>{dateTime(task.data.created_at)}</dd></div>
        <div><dt>更新时间</dt><dd>{dateTime(task.data.updated_at)}</dd></div>
      </dl>{task.data.scheduler_error && <p className="mobile-inline-error">{task.data.scheduler_error}</p>}</section>
      <section className="mobile-automation-card"><h3>任务内容</h3><MarkdownContent readOnly text={task.data.prompt} className="mobile-markdown mobile-automation-markdown" /></section>
      {task.data.precheck_command && <section className="mobile-automation-card"><h3>执行前检查 <small>{task.data.precheck_timeout_seconds} 秒超时</small></h3><pre className="mobile-automation-command">{task.data.precheck_command}</pre></section>}</>}
      <h3 className="mobile-section-label">执行历史</h3>
      <MobileState loading={runs.loading && !runs.data} error={runs.error} retry={runs.reload} empty={runs.data?.length === 0 ? '暂无执行记录。' : undefined} />
      <div className="mobile-list">{runs.data?.map((run) => <button className="mobile-list-row" key={run.id}
        onClick={() => navigate({ ...route, run: run.id })}>
        <div className="mobile-row-icon"><AgentIcon agentId={run.agent} /></div><div className="mobile-row-main"><strong>{runNames[run.status]}</strong><span>{dateTime(run.started_at)} · {duration(run.duration_ms)}</span></div><ChevronRight size={17} />
      </button>)}</div>
      {runs.data?.length === 50 && <p className="mobile-reader-meta">展示最近 50 次执行。</p>}
    </div>
  </section>;
}

function MobileAutomationRun({ route, back }: { route: MobileRoute; back: () => void }) {
  const run = useMobileResource(`run.${route.task}.${route.run}`, () => automationApi.runDetail(route.task!, route.run!));
  const session = useMobileResource(`run-session.${route.task}.${route.run}`, () => sessionsApi.automationRunSession(route.task!, route.run!), !!run.data?.session_id);
  const scroll = useMobileScroll(`run.${route.task}.${route.run}`, !!run.data);
  return <section className="mobile-content-page">
    <MobilePageHeader title={run.data?.task_name ?? '执行详情'} subtitle={run.data ? `Run ${run.data.id}` : undefined} back={back} actions={<MobileRefresh reload={() => { run.reload(); session.reload(); }} loading={run.loading || session.loading} />} />
    <div className="mobile-scroll" ref={scroll}><MobileState loading={run.loading && !run.data} error={run.error} retry={run.reload} />
      {run.data && <><section className="mobile-automation-card"><h3>执行信息</h3><dl className="mobile-automation-details">
        <div><dt>Run ID</dt><dd><code>{run.data.id}</code></dd></div>
        <div><dt>任务 ID</dt><dd><code>{run.data.task_id}</code></dd></div>
        <div><dt>状态</dt><dd>{runNames[run.data.status]}</dd></div>
        <div><dt>触发方式</dt><dd>{run.data.source === 'manual' ? '手动运行' : '计划运行'}</dd></div>
        <div><dt>开始时间</dt><dd>{dateTime(run.data.started_at)}</dd></div>
        <div><dt>结束时间</dt><dd>{dateTime(run.data.finished_at)}</dd></div>
        <div><dt>耗时</dt><dd>{duration(run.data.duration_ms)}</dd></div>
        <div><dt>工作区</dt><dd><code>{run.data.workspace_path ?? '—'}</code></dd></div>
        <div><dt>分支</dt><dd><code>{run.data.branch ?? '—'}</code></dd></div>
        <div><dt>Session ID</dt><dd><code>{run.data.session_id ?? '—'}</code></dd></div>
        <div><dt>退出码</dt><dd>{run.data.exit_code ?? '—'}</dd></div>
      </dl>{run.data.message && <p className="mobile-automation-run-message">{run.data.message}</p>}</section>
      <RunParameters run={run.data} />
      <h3 className="mobile-section-label mobile-automation-result-label">本次执行内容</h3>
      {run.data.session_id ? session.data ? <MobileAutomationRunResult run={run.data} session={session.data} workspace={run.data.workspace_path ?? route.workspace} />
        : <><MobileState loading={session.loading} error={session.error} retry={session.reload} />{session.error ? <RunOutput run={run.data} /> : null}</>
        : <RunOutput run={run.data} />}</>}
    </div>
  </section>;
}

function MobileAutomationRunResult({ run, session, workspace }: { run: AutomationRun; session: AowAgentSession; workspace: string }) {
  const snapshot = useMobileResource(`automation-run-snapshot.${workspace}.${session.id}`, () => sessionsApi.agentSessionSnapshot(session, workspace));
  const results = snapshot.data?.turns.flatMap((turn) => turn.final ? [{ id: turn.id, message: turn.final }] : []) ?? [];
  return <section className="mobile-automation-card mobile-automation-result">
    <MobileState loading={snapshot.loading && !snapshot.data} error={snapshot.error} retry={snapshot.reload} />
    {results.map((result) => <article key={result.id}><AgentIcon agentId={session.agent} /><MarkdownContent readOnly text={result.message.text} className="mobile-markdown" /></article>)}
    {snapshot.data && !results.length ? <RunOutput run={run} embedded /> : null}
  </section>;
}

function RunOutput({ run, embedded = false }: { run: AutomationRun; embedded?: boolean }) {
  const output = useMobileResource(`output.${run.id}`, () => automationApi.runOutput(run.task_id, run.id, 'stdio'));
  const content = <><MobileState loading={output.loading} error={output.error} retry={output.reload} empty={output.data === '' ? '暂无执行内容。' : undefined} />{output.data ? <pre className="mobile-code mobile-automation-output">{output.data}</pre> : null}</>;
  return embedded ? content : <section className="mobile-automation-card mobile-automation-result">{content}</section>;
}

import { useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import type { AutomationRun } from './types';

const SUMMARY_LIMIT = 100;

export function RunParameterSummary({ run }: { run: AutomationRun }) {
  const anchor = useRef<HTMLSpanElement>(null);
  const tooltip = useRef<HTMLDivElement>(null);
  const closeTimer = useRef<number | undefined>(undefined);
  const tooltipId = useId();
  const [open, setOpen] = useState(false);
  const [position, setPosition] = useState({ left: 0, top: 0 });
  const entries = Object.entries(run.variables ?? {});
  const summary = entries.map(([key, value]) => `${key}=${value}`).join(',').replace(/[\r\n\t]/g, ' ');
  const characters = Array.from(summary);
  const text = characters.length > SUMMARY_LIMIT ? `${characters.slice(0, SUMMARY_LIMIT).join('')}…` : summary;
  const keepOpen = () => window.clearTimeout(closeTimer.current);
  const closeSoon = () => { keepOpen(); closeTimer.current = window.setTimeout(() => setOpen(false), 160); };

  useEffect(() => () => window.clearTimeout(closeTimer.current), []);
  useLayoutEffect(() => {
    if (!open || !anchor.current || !tooltip.current) return;
    const bounds = tooltip.current.getBoundingClientRect();
    const rect = anchor.current.getBoundingClientRect();
    setPosition({
      left: Math.max(8, Math.min(rect.left, window.innerWidth - bounds.width - 8)),
      top: rect.bottom + bounds.height + 6 <= window.innerHeight - 8
        ? rect.bottom + 6 : Math.max(8, rect.top - bounds.height - 6),
    });
  }, [open, run.variables]);
  useEffect(() => {
    if (!open) return;
    const close = () => setOpen(false);
    const keydown = (event: KeyboardEvent) => { if (event.key === 'Escape') close(); };
    const scroll = (event: Event) => { if (!(event.target instanceof Node) || !tooltip.current?.contains(event.target)) close(); };
    window.addEventListener('keydown', keydown);
    window.addEventListener('resize', close);
    window.addEventListener('scroll', scroll, true);
    return () => {
      window.removeEventListener('keydown', keydown);
      window.removeEventListener('resize', close);
      window.removeEventListener('scroll', scroll, true);
    };
  }, [open]);

  if (!entries.length) return <span className="automation-parameter-summary automation-muted">{run.source === 'manual' && run.variables == null ? '未记录' : '—'}</span>;
  return <span ref={anchor} className="automation-parameter-summary" aria-describedby={open ? tooltipId : undefined}
    onPointerEnter={event => { if (event.pointerType !== 'touch') { keepOpen(); setOpen(true); } }} onPointerLeave={closeSoon}
    onClick={() => setOpen(false)}>
    <code>{text}</code>
    {open ? createPortal(<div ref={tooltip} id={tooltipId} role="tooltip" aria-label="执行参数" className="automation-parameter-tooltip" style={position}
      onPointerEnter={keepOpen} onPointerLeave={closeSoon} onPointerDown={event => event.stopPropagation()} onClick={event => event.stopPropagation()}>
      {entries.map(([key, value]) => <div className="automation-parameter-tooltip-row" key={key}><code>{key}</code><span>=</span><code>{value}</code></div>)}
    </div>, document.body) : null}
  </span>;
}

import type { AutomationRun } from './types';
import './run-parameters.css';

export function RunParameters({ run }: { run: AutomationRun }) {
  if (run.source !== 'manual') return null;
  const entries = Object.entries(run.variables ?? {});
  return <section className="automation-run-parameters" aria-label="触发参数">
    <h3>触发参数</h3>
    {run.variables == null ? <p>该执行记录未保存触发参数。</p> : entries.length === 0 ? <p>本次执行无参数。</p>
      : <dl className="automation-run-parameter-list">{entries.map(([name, value]) => <div key={name}><dt>{name}</dt><dd><pre>{value}</pre></dd></div>)}</dl>}
  </section>;
}

import type { TaskInput, RunOutput, AutomationRun, AutomationTask, SchedulerStatus } from './types';
import { appUrl } from '../../lib/basePath';

const base = appUrl('/api/aow/automations');
async function request<T>(path: string, method = 'GET', body?: unknown): Promise<T> {
  const response = await fetch(`${base}${path}`, {
    method, headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => null) as { message?: string } | null;
    throw new Error(payload?.message ?? `请求失败 (${response.status})`);
  }
  return response.status === 204 ? undefined as T : response.json() as Promise<T>;
}
export const automationApi = {
  status: () => request<SchedulerStatus>('/status'),
  list: (projectId?: string) => request<AutomationTask[]>(projectId ? `?project_id=${encodeURIComponent(projectId)}` : ''),
  detail: (id: string) => request<AutomationTask>(`/${id}`),
  create: (input: TaskInput) => request<AutomationTask>('', 'POST', input),
  update: (id: string, input: TaskInput, revision: number) => request<AutomationTask>(`/${id}`, 'PUT', { ...input, revision }),
  enabled: (id: string, enabled: boolean) => request<AutomationTask>(`/${id}/enabled`, 'PUT', { enabled }),
  sync: (id: string) => request<AutomationTask>(`/${id}/sync`, 'POST'),
  remove: (id: string) => request<void>(`/${id}`, 'DELETE'),
  run: (id: string, revision: number, variables: Record<string, string> = {}) => request<{ run_id: string | null }>(`/${id}/run`, 'POST', { revision, variables }),
  runs: (id: string, before?: string, limit = 50) => request<AutomationRun[]>(`/${id}/runs?limit=${limit}${before ? `&before=${encodeURIComponent(before)}` : ''}`),
  runDetail: (id: string, runId: string) => request<AutomationRun>(`/${id}/runs/${runId}`),
  runOutput: async (id: string, runId: string, output: RunOutput) => {
    const response = await fetch(`${base}/${encodeURIComponent(id)}/runs/${encodeURIComponent(runId)}/output/${output}`);
    if (!response.ok) {
      const payload = await response.json().catch(() => null) as { message?: string } | null;
      throw new Error(payload?.message ?? `请求失败 (${response.status})`);
    }
    return response.text();
  },
};

