            <div className="pr-files">{files.length ? files.map((file) => {
              const expanded = expandedFiles.has(file.path);
              const names: Record<string, string> = { added: '新增', deleted: '删除', modified: '修改', renamed: '重命名', copied: '复制' };
              return <section className={'pr-file' + (expanded ? ' expanded' : '')} key={file.path}>
                <button className="pr-file-header" disabled={loading} aria-expanded={expanded} aria-controls={`${prefix}-file-${encodeURIComponent(file.path)}`} onClick={() => toggleFile(file)}>{expanded ? <ChevronDown /> : <ChevronRight />}<FileTypeIcon path={file.path} /><span className="pr-file-path" title={file.path}>{file.path}</span><span className={'pr-change-type ' + file.change_type}>{names[file.change_type] || file.change_type}</span><span className="pr-file-stat">{file.additions != null ? <b className="pr-additions">+{file.additions}</b> : null}{file.deletions != null ? <b className="pr-deletions">−{file.deletions}</b> : null}</span></button>
                <div id={`${prefix}-file-${encodeURIComponent(file.path)}`} className="pr-inline-diff" hidden={!expanded}>{expanded && activeTab === 'changes' ? <InlineFileDiff detail={detail} file={file} state={fileDiffs[file.path]} mobile={mobile} modelScope={`${repository}:${prefix}`} sideBySide={sideBySide} onRetry={() => loadDiff(file, true)} /> : null}</div>
              </section>;
            }) : <Empty icon={<FileDiff />}>{fileQuery ? '没有匹配的文件，试试其他路径。' : '暂无可展示的文件变更。'}</Empty>}</div>
          </section>
          <section id={`${prefix}-checks`} role="tabpanel" aria-labelledby={`${prefix}-checks-tab`} hidden={activeTab !== 'checks'}>
            <div className="pr-section-heading"><div><h2>检查与审阅</h2><span>{passedChecks} / {detail.checks.length} 项检查通过</span></div><label className="pr-filter-label">显示<select aria-label="筛选检查" value={checkFilter} onChange={(event) => setCheckFilter(event.target.value)}><option value="all">全部检查</option><option value="failed">未通过</option><option value="pending">等待 / 运行中</option><option value="passed">已通过</option></select></label></div>
            <label className="pr-search pr-check-search"><Search /><input aria-label="搜索检查名称" placeholder="搜索检查名称…" value={checkQuery} onChange={(event) => setCheckQuery(event.target.value)} /></label>
            <div className="pr-review-summary"><ShieldCheck /><span>代码审阅</span><Badge value={review} /><small>{detail.reviewers.length} 位审阅人</small></div>
            <div className="pr-checks">{checks.length ? checks.map((check, index) => <CheckCard key={check.id || `${check.name}:${index}`} check={check} />) : <Empty icon={<ShieldCheck />}>{detail.checks.length ? '没有符合筛选条件的检查。' : '暂无 CI 检查。'}</Empty>}</div>
          </section>
          <section id={`${prefix}-discussion`} role="tabpanel" aria-labelledby={`${prefix}-discussion-tab`} hidden={activeTab !== 'discussion'}>
            <div className="pr-section-heading"><div><h2>讨论</h2><span>{threads.length} 条讨论 · {detail.unresolved_threads.length} 条未解决</span></div><div className="pr-segmented" aria-label="讨论筛选"><button aria-pressed={!unresolvedOnly} onClick={() => setUnresolvedOnly(false)}>全部</button><button aria-pressed={unresolvedOnly} onClick={() => setUnresolvedOnly(true)}>未解决</button></div></div>
            <div className="pr-discussions">{discussions.length ? discussions.map((thread) => <DiscussionCard key={thread.id} thread={thread} />) : <Empty icon={unresolvedOnly ? <Check /> : <MessageSquareMore />}>{unresolvedOnly ? '没有未解决的讨论。' : '暂无讨论。'}</Empty>}</div>
          </section>
        </main>
        {activeTab === 'overview' ? <aside className="pr-sidebar" aria-label="PR 元信息">
          <section><h2>作者</h2>{detail.author ? <Person user={detail.author} /> : <p className="pr-muted">未提供作者信息</p>}</section>
          <section><h2>审阅人 <span>{detail.reviewers.length}</span></h2>{detail.reviewers.length ? detail.reviewers.map((user) => <Person key={user.id} user={user} />) : <p className="pr-muted">暂未指定审阅人</p>}</section>
          <section><h2>标签</h2>{detail.labels?.length ? <div className="pr-labels">{detail.labels.map((label) => <span key={label}>{label}</span>)}</div> : <p className="pr-muted">暂无标签</p>}</section>
          {detail.milestone ? <section><h2>里程碑</h2><p className="pr-milestone">{detail.milestone}</p></section> : null}
          <section><h2>时间</h2><dl className="pr-metadata"><div><dt>创建于</dt><dd><time dateTime={detail.created_at}>{formatPrTime(detail.created_at)}</time></dd></div><div><dt>更新于</dt><dd><time dateTime={detail.updated_at}>{formatPrTime(detail.updated_at)}</time></dd></div></dl></section>
          <section><h2>变更概况</h2><dl className="pr-metadata pr-diff-summary"><div><dt><GitCommitHorizontal />提交</dt><dd>{detail.commits_count}</dd></div><div><dt><FileDiff />文件</dt><dd>{detail.changes_count}</dd></div>{additions != null ? <div><dt>{partialStats ? '已知新增行' : '新增行'}</dt><dd className="pr-additions">+{additions}</dd></div> : null}{deletions != null ? <div><dt>{partialStats ? '已知删除行' : '删除行'}</dt><dd className="pr-deletions">−{deletions}</dd></div> : null}</dl></section>
        </aside> : null}
      </div>
    </div>
  </article>;
}

import { useCallback, useEffect, useId, useMemo, useRef, useState } from 'react';
import { GitPullRequest, LoaderCircle, RefreshCw, UserRound } from 'lucide-react';
import { useReviewTarget } from './reviewProviders';
import { prApi } from './api';
import type { PullRequestSummary, MyPullRequests } from './types';
import { AowIconButton } from '../../components/AowIconButton';
import { AowPanel, AowPanelStack } from '../../components/AowPanel';
import { AowListRow } from '../../components/AowListRow';

interface Props {
  repository: string;
  visible: boolean;
  activeNumber?: number;
  activeProvider?: string;
  activeRemote?: string;
  onOpen: (pr: PullRequestSummary) => void;
}

function errorMessage(reason: unknown) {
  return reason instanceof Error ? reason.message : String(reason);
}

function relativeTime(value: string) {
  const time = Date.parse(value);
  if (!Number.isFinite(time)) return value;
  const seconds = Math.round((time - Date.now()) / 1000);
  const ranges: [Intl.RelativeTimeFormatUnit, number][] = [
    ['year', 31_536_000], ['month', 2_592_000], ['week', 604_800], ['day', 86_400], ['hour', 3_600], ['minute', 60],
  ];
  const formatter = new Intl.RelativeTimeFormat('zh-CN', { numeric: 'auto' });
  for (const [unit, size] of ranges) if (Math.abs(seconds) >= size) return formatter.format(Math.round(seconds / size), unit);
  return formatter.format(seconds, 'second');
}

function PullRequestRow({ pr, current, selected, onOpen }: {
  pr: PullRequestSummary;
  current: boolean;
  selected: boolean;
  onOpen: () => void;
}) {
  return <AowListRow className={'my-pr-row' + (selected ? ' selected' : '')} icon={<GitPullRequest />}
    title={`${pr.draft ? 'Draft ' : ''}#${pr.number} · ${pr.title}`} menuLabel="Pull Request 操作" onOpen={onOpen}>
    <span className="my-pr-row-details"><small>{pr.source_branch} → {pr.target_branch}</small>
      <span className="my-pr-row-meta">{current ? '当前分支' : relativeTime(pr.updated_at)}</span>
    </span>
  </AowListRow>;
}

export function PullRequestsPanel({ repository, visible, activeNumber, activeProvider, activeRemote, onOpen }: Props) {
  const panelId = useId();
  const selection = useReviewTarget(repository, visible);
  const provider = selection.target?.provider;
  const remote = selection.target?.remote;
  const [collapsed, setCollapsed] = useState<{ user?: boolean; pr?: boolean }>({});
  const [state, setState] = useState<MyPullRequests>();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const requestVersion = useRef(0);

  const load = useCallback(async () => {
    const version = ++requestVersion.current;
    if (!selection.ready) return;
    setLoading(true); setError('');
    try {
      const next = await prApi.myPullRequests(repository, { provider, remote });
      if (version === requestVersion.current) setState(next);
    } catch (reason) {
      if (version === requestVersion.current) { setError(errorMessage(reason)); }
    } finally {
      if (version === requestVersion.current) setLoading(false);
    }
  }, [repository, provider, remote, selection.ready]);

  useEffect(() => {
    setState(undefined); setError(''); setLoading(false);
    if (visible) void load();
    return () => { requestVersion.current += 1; };
  }, [load, visible]);

  const current = useMemo(() => new Set(state?.pull_requests.filter((pr) => pr.source_branch === state.current_branch).map((pr) => pr.number)), [state]);
  const user = state?.current_user;
  const userBodyId = `${panelId}-user`;
  const prBodyId = `${panelId}-pr`;
  return <section className="side-view pull-requests-panel" aria-label="Pull Requests">
    {selection.targets.length > 1 ? <label className="review-remote-picker">Remote<select aria-label="PR remote" value={selection.remote} onChange={e => selection.select(e.target.value)}><option value="">请选择 remote</option>{selection.targets.map(t => <option key={t.remote} value={t.remote}>{t.remote} · {t.provider_name} · {t.repository}</option>)}</select></label> : null}
    {selection.error ? <div className="side-error" role="alert">{selection.error}<button onClick={selection.reload}>重新匹配</button></div> : null}
    <AowPanelStack>
      <AowPanel className="pull-requests-section pull-requests-user-section" title="User" icon={<UserRound />} collapsed={collapsed.user} controlsId={userBodyId}
        onCollapsedChange={user => setCollapsed(value => ({ ...value, user }))} empty={!!state && !user && !error}>
        {user ? <div className="pull-requests-user" title={`${user.display_name || user.username} (@${user.username}) · 当前用户`}>
          <strong>{user.display_name || user.username}</strong>
          <small>@{user.username} · 当前用户</small>
        </div> : <div className="side-empty">{loading ? '正在加载当前用户…' : error ? '未能加载当前用户' : '打开面板后加载当前用户。'}</div>}
      </AowPanel>
      <AowPanel className="pull-requests-section pull-requests-pr-section" bodyClassName="pull-requests-body" empty={!!state && !state.pull_requests.length && !error} title="PR" icon={<GitPullRequest />} collapsed={collapsed.pr} controlsId={prBodyId}
        onCollapsedChange={pr => setCollapsed(value => ({ ...value, pr }))}
        actions={<AowIconButton title="刷新 Pull Requests" aria-label="刷新 Pull Requests" disabled={loading} onClick={selection.reload}><RefreshCw className={loading ? 'spinning' : ''} /></AowIconButton>}>
        {error ? <div className="side-error" role="alert">{error}</div> : null}
        {!state && !loading && !error ? <div className="side-empty">打开面板后加载该用户创建的 Open PR。</div> : null}
        {loading && !state ? <div className="my-pr-state" role="status"><LoaderCircle className="spinning" />正在加载 Pull Requests…</div> : null}
        {state ? <div className="my-pr-list">
          {state.pull_requests.length ? state.pull_requests.map((pr) => <PullRequestRow key={pr.number} pr={pr} current={current.has(pr.number)} selected={activeNumber === pr.number && (!activeProvider || activeProvider === pr.provider) && (!activeRemote || activeRemote === pr.remote)} onOpen={() => onOpen(pr)} />) : <div className="side-empty">当前仓库没有该用户创建的 Open PR。</div>}
        </div> : null}
      </AowPanel>
    </AowPanelStack>
  </section>;
}

.review-provider-settings-host:not([hidden]) { display: flex; flex: 1; min-height: 0; min-width: 0; }
.review-provider-settings-host > section { flex: 1; }
.review-provider-settings { min-width: 0; }
.review-provider-toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
