.review-provider-fields input, .review-provider-fields textarea { width: 100%; box-sizing: border-box; }
.review-provider-editor { border: 1px solid var(--aow-line); overflow: hidden; border-radius: 6px; margin-top: 10px; }
.review-provider-protocol { margin-top: 16px; }
.review-provider-protocol summary { cursor: pointer; }
.review-provider-protocol pre { overflow: auto; }
.review-provider-settings .project-aow-dialog-footer { flex-wrap: wrap; }
