export function MobileSessions({ route, visible, navigate, back }: { route: MobileRoute; visible: boolean; navigate: MobileNavigate; back: () => void }) {
  const list = useMobileResource(`sessions.${route.cwd ?? route.workspace}`, async () => {
    const results = await Promise.allSettled(agents.map((agent) => sessionsApi.agentSessions(route.cwd ?? route.workspace, agent)));
    const sessions = results.flatMap((result) => result.status === 'fulfilled' ? result.value : []);
    const failures = results.flatMap((result, index) => result.status === 'rejected' ? [`${agents[index]}: ${String(result.reason)}`] : []);
    if (failures.length === agents.length) throw new Error(failures.join('\n'));
    return { sessions: sessions.sort((a, b) => b.updated_at.localeCompare(a.updated_at)), failures };
  }, visible);
  const scroll = useMobileScroll(`sessions.${route.cwd ?? route.workspace}`, !!list.data);
  const selected = list.data?.sessions.find((session) => session.id === route.session || session.agent === route.agent && session.agent + ':' + session.session_id === route.session);
  return <section className="mobile-content-page">
    {route.session ? selected ? <MobileSessionReader session={selected} workspace={route.cwd ?? selected.cwd} back={back} />
      : <><MobilePageHeader title="会话" back={back} /><MobileState loading={list.loading} error={list.error} retry={list.reload} empty="未找到这个会话，请返回列表刷新。" /></>
      : <>
        <MobilePageHeader title="Conversation" subtitle="本地会话记录" actions={<MobileRefresh reload={list.reload} loading={list.loading} />} />
        <div className="mobile-scroll" ref={scroll}>
          <MobileState error={list.error} loading={list.loading && !list.data} retry={list.reload} empty={list.data?.sessions.length === 0 ? '这个工作区还没有会话记录。' : undefined} />
          {list.data?.failures.map((failure) => <p className="mobile-inline-error" key={failure}>{failure}</p>)}
          <div className="mobile-list">{list.data?.sessions.map((session) => <button className="mobile-list-row mobile-session-row" key={session.id}
            onClick={() => navigate({ workspace: route.workspace, view: 'sessions', session: session.id, agent: session.agent, cwd: session.cwd })}>
            <div className="mobile-row-icon"><AgentIcon agentId={session.agent} /></div>
            <div className="mobile-row-main"><strong>{session.title}</strong><span>{session.agent} · {mobileTime(session.updated_at)}</span></div><ChevronRight size={17} />
          </button>)}</div>
        </div>
      </>}
  </section>;
}

export function MobileSessionReader({ session, workspace, back }: { session: AowAgentSession; workspace: string; back: () => void }) {
  const snapshot = useMobileResource(`snapshot.${workspace}.${session.id}`, () => sessionsApi.agentSessionSnapshot(session, workspace));
  const scroll = useMobileScroll(`snapshot.${workspace}.${session.id}`, !!snapshot.data);
  return <section className="mobile-content-page">
    <MobilePageHeader title={session.title} subtitle={snapshot.data ? `${session.agent} · ${statusNames[snapshot.data.status]} · ${snapshot.data.turns.length} 轮` : session.agent}
      back={back} actions={<>{snapshot.data && <SessionShareButton session={session} workspacePath={workspace} />}<MobileRefresh reload={snapshot.reload} loading={snapshot.loading} /></>} />
    <div className="mobile-scroll mobile-conversation" ref={scroll}>
      <MobileState error={snapshot.error} loading={snapshot.loading && !snapshot.data} retry={snapshot.reload} empty={snapshot.data?.turns.length === 0 ? '这个会话还没有可展示的对话。' : undefined} />
      {snapshot.data && <p className="mobile-reader-meta"><MessageSquare size={13} />快照更新于 {mobileTime(snapshot.data.captured_at)}{snapshot.data.truncated && ' · 仅展示最近 200 轮'}</p>}
      {snapshot.data?.turns.map((turn, index) => <article className="mobile-turn" key={turn.id}>
        <div className="mobile-turn-label">第 {index + 1} 轮 · {statusNames[turn.status]}{index === snapshot.data!.turns.length - 1 && <span>最新一轮</span>}</div>
        <section className="mobile-message user"><SessionMessageContent text={turn.user.text} className="mobile-markdown" /></section>
        <section className="mobile-message assistant">
          <header className="mobile-session-agent"><AgentIcon agentId={session.agent} /><strong>{{ codex: 'Codex', claude: 'Claude', traecli: 'TraeCode CLI', hermes: 'Hermes' }[session.agent]}</strong></header>
          <SessionTurnProcess key={`${session.id}:${turn.id}:${index === snapshot.data!.turns.length - 1}`} turn={turn} isLatest={index === snapshot.data!.turns.length - 1} />
          {turn.final && <SessionMessageContent text={turn.final.text} imageReferenceText={turn.user.text} className="mobile-markdown" />}
          <SessionTurnPending turn={turn} />
        </section>
      </article>)}
    </div>
  </section>;
}

import { useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { sessionImageReferences } from './sessionImageReferences';
import { MarkdownContent } from '../../components/MarkdownContent';
import './session-image-preview.css';

function ImagePreview({ anchor, id, onClose, onEnter, onLeave }: {
  anchor: HTMLAnchorElement; id: string; onClose: () => void; onEnter: () => void; onLeave: () => void;
}) {
  const preview = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ left: 8, top: 8 });
  const [status, setStatus] = useState<'loading' | 'loaded' | 'error'>('loading');

  useLayoutEffect(() => {
    const bounds = preview.current?.getBoundingClientRect();
    if (!bounds) return;
    const rect = anchor.getBoundingClientRect();
    const top = rect.bottom + 8 + bounds.height <= window.innerHeight - 8
      ? rect.bottom + 8 : rect.top - bounds.height - 8;
    setPosition({
      left: Math.max(8, Math.min(rect.left, window.innerWidth - bounds.width - 8)),
      top: Math.max(8, Math.min(top, window.innerHeight - bounds.height - 8)),
    });
    anchor.setAttribute('aria-describedby', id);
    return () => anchor.removeAttribute('aria-describedby');
  }, [anchor, id]);

  useEffect(() => {
    const keydown = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
    window.addEventListener('keydown', keydown);
    window.addEventListener('scroll', onClose, true);
    window.addEventListener('resize', onClose);
    return () => {
      window.removeEventListener('keydown', keydown);
      window.removeEventListener('scroll', onClose, true);
      window.removeEventListener('resize', onClose);
    };
  }, [onClose]);

  return createPortal(<div ref={preview} id={id} role="tooltip" className="session-image-preview" style={position}
    onMouseEnter={onEnter} onMouseLeave={onLeave}>
    <div className="session-image-preview-canvas">
      {status !== 'error' && <img src={anchor.href} alt={anchor.textContent ?? '图片预览'}
        className={status === 'loaded' ? 'loaded' : undefined} onLoad={() => setStatus('loaded')} onError={() => setStatus('error')} />}
      {status !== 'loaded' && <span role="status">{status === 'error' ? '图片无法加载，文件可能已移除或当前无法访问。' : '正在加载图片…'}</span>}
    </div>
    <div className="session-image-preview-caption">{anchor.textContent}</div>
  </div>, document.body);
}

export function SessionMessageContent({ text, imageReferenceText = text, className, previewImages = true }: {
  text: string; imageReferenceText?: string; className?: string; previewImages?: boolean;
}) {
  const images = useMemo(() => previewImages ? sessionImageReferences(imageReferenceText) : undefined, [imageReferenceText, previewImages]);
  const root = useRef<HTMLDivElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const [anchor, setAnchor] = useState<HTMLAnchorElement | null>(null);
  const id = useId();
  const cancelClose = useCallback(() => { clearTimeout(timer.current); }, []);
  const close = useCallback(() => { clearTimeout(timer.current); setAnchor(null); }, []);
  const scheduleClose = () => { cancelClose(); timer.current = setTimeout(close, 120); };

  useEffect(() => { close(); }, [text, images, close]);
  useEffect(() => cancelClose, [cancelClose]);

  const show = (target: EventTarget | null) => {
    // Portal events bubble through React even though the preview is outside the message.
    if (target instanceof Node && !root.current?.contains(target)) return;
    const link = target instanceof Element ? target.closest<HTMLAnchorElement>('a.session-image-reference') : null;
    if (!link || !root.current?.contains(link) || images?.get(link.dataset.sessionImage ?? '') !== link.getAttribute('href')) {
      scheduleClose();
      return;
    }
    cancelClose();
    setAnchor(link);
  };

  return <div ref={root} onMouseOver={(event) => show(event.target)} onMouseLeave={scheduleClose}
    onFocusCapture={(event) => show(event.target)} onBlurCapture={scheduleClose}>
    <MarkdownContent text={text} className={className} readOnly imageReferences={images} />
    {anchor && <ImagePreview key={anchor.href} anchor={anchor} id={id} onClose={close} onEnter={cancelClose} onLeave={scheduleClose} />}
  </div>;
}

import { useEffect, useId, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Check, Copy, LoaderCircle, Share2, X } from 'lucide-react';
import { sessionShareApi, type SessionShare } from './sessionShareApi';
import type { AowAgentSession } from './types';
import './session-share.css';

interface Props { session: AowAgentSession; workspacePath: string }

export function SessionShareButton(props: Props) {
  const [open, setOpen] = useState(false);
  return <>
    <button type="button" className="session-share-button" title="分享会话" aria-label="分享会话" onClick={() => setOpen(true)}><Share2 size={16} /><span>分享</span></button>
    {open && <ShareDialog key={`${props.session.id}:${props.workspacePath}`} {...props} close={() => setOpen(false)} />}
  </>;
}

function ShareDialog({ session, workspacePath, close }: Props & { close: () => void }) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const linkRef = useRef<HTMLInputElement>(null);
  const busyRef = useRef(false);
  const [share, setShare] = useState<SessionShare | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const id = useId();
  const url = share ? new URL(share.path, window.location.origin).href : '';

  useEffect(() => {
    const dialog = dialogRef.current!;
    dialog.showModal();
    const controller = new AbortController();
    void sessionShareApi.info(session, controller.signal).then(setShare).catch(reason => {
      if (!controller.signal.aborted) setError(reason instanceof Error ? reason.message : '无法读取分享设置');
    }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => { controller.abort(); dialog.close(); };
  }, [session.agent, session.session_id]);

  const copy = async (value: string) => {
    try {
      if (!navigator.clipboard?.writeText) throw new Error('clipboard unavailable');
      await navigator.clipboard.writeText(value);
      setNotice('链接已复制');
    } catch {
      // HTTP deployments may not expose Clipboard API. Keep the link selectable.
      const input = linkRef.current;
      if (input) { input.value = value; input.focus(); input.select(); }
      try {
        if (!input || !document.execCommand('copy')) throw new Error('copy failed');
        setNotice('链接已复制');
      } catch { setNotice('链接已生成，请选中链接手动复制'); }
    }
  };

  const mutate = async (action: () => Promise<void>) => {
    if (busyRef.current) return;
    busyRef.current = true;
    setBusy(true); setError(''); setNotice('');
    try { await action(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : '操作失败，请重试'); }
    finally { busyRef.current = false; setBusy(false); }
  };

  const createAndCopy = () => mutate(async () => {
    const result = share ?? await sessionShareApi.create(session, workspacePath);
    setShare(result);
    await copy(new URL(result.path, window.location.origin).href);
  });
  const revoke = () => mutate(async () => {
    if (!share) return;
    await sessionShareApi.revoke(share.id);
    setShare(null);
    setNotice('已取消分享，旧链接已失效');
  });

  return createPortal(<dialog ref={dialogRef} className="session-share-dialog" aria-labelledby={`${id}-title`} aria-describedby={`${id}-description`}
    onCancel={event => { event.preventDefault(); if (!busyRef.current) close(); }} onKeyDown={event => event.stopPropagation()}>
    <header><h2 id={`${id}-title`}>分享会话</h2><button type="button" aria-label="关闭分享窗口" disabled={busy} onClick={close}><X size={18} /></button></header>
    <p className="session-share-title">{session.title}</p>
    <p id={`${id}-description`}>持有链接的人无需登录，即可只读查看此会话及后续对话，包括处理过程和工具详情。可以随时取消分享。</p>
    <label htmlFor={`${id}-link`}>分享链接</label>
    <input ref={linkRef} id={`${id}-link`} value={url} readOnly placeholder={loading ? '正在读取分享设置…' : '创建后显示分享链接'} onFocus={event => event.currentTarget.select()} />
    {error && <p className="session-share-error" role="alert">{error}</p>}
    {notice && <p className="session-share-notice" role="status">{notice === '链接已复制' && <Check size={14} />}{notice}</p>}
    <footer>{share && <button type="button" className="danger" disabled={busy || loading} onClick={() => void revoke()}>取消分享</button>}
      <button type="button" className="primary" disabled={busy || loading} onClick={() => void createAndCopy()}>
        {busy || loading ? <LoaderCircle size={15} className="spinning" /> : <Copy size={15} />}{share ? '复制链接' : '创建并复制链接'}
      </button></footer>
  </dialog>, document.body);
}

import { SessionMessageContent } from './SessionMessageContent';
import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';
import { AlertCircle, ArrowDownToLine, History, LoaderCircle, RefreshCw, UserRound } from 'lucide-react';
import type { AgentSessionSnapshot, AgentSessionTurnStatus, AowAgentSession } from './types';
import { AgentIcon } from '../agents/AgentIcon';
import { SessionTurnPending, SessionTurnProcess } from './SessionTurnProcess';

interface Props {
  session: Pick<AowAgentSession, 'id' | 'agent' | 'title'> & Partial<Pick<AowAgentSession, 'cwd' | 'session_id'>>;
  snapshot?: AgentSessionSnapshot;
  loading: boolean;
  error?: string;
  onRefresh: () => void;
  actions?: ReactNode;
  publicView?: boolean;
}

const promptPreviewLength = 32;

const statusNames: Record<AgentSessionTurnStatus, string> = {
  completed: '已完成',
  failed: '失败',
  interrupted: '已中断',
  in_progress: '进行中',
};

function time(value: string | null) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat('zh-CN', { dateStyle: 'medium', timeStyle: 'medium' }).format(date);
}

function promptPreview(text: string) {
  const normalized = text.replace(/\s+/g, ' ').trim();
  if (!normalized) return '空白输入';
  const characters = Array.from(normalized);
  return characters.length > promptPreviewLength
    ? `${characters.slice(0, promptPreviewLength).join('')}…`
    : normalized;
}

export function SessionSnapshotView({ session, snapshot, loading, error, onRefresh, actions, publicView = false }: Props) {
  const conversationRef = useRef<HTMLDivElement>(null);
  const turnRefs = useRef<Array<HTMLElement | null>>([]);
  const navigationRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const [activeTurn, setActiveTurn] = useState(0);
  const turnCount = snapshot?.turns.length ?? 0;
  const agentName = { codex: 'Codex', claude: 'Claude', traecli: 'TraeCode CLI', hermes: 'Hermes' }[session.agent];

  useEffect(() => {
    turnRefs.current = turnRefs.current.slice(0, turnCount);
    navigationRefs.current = navigationRefs.current.slice(0, turnCount);
  }, [turnCount]);

  useEffect(() => {
    setActiveTurn(0);
    conversationRef.current?.scrollTo({ top: 0, behavior: 'instant' });
  }, [session.id]);

  useEffect(() => {
    navigationRefs.current[activeTurn]?.scrollIntoView({ block: 'nearest' });
  }, [activeTurn]);

  const updateActiveTurn = useCallback(() => {
    const conversation = conversationRef.current;
    if (!conversation || !turnRefs.current.length) return;
    if (conversation.scrollTop > 0 && conversation.scrollHeight - conversation.scrollTop - conversation.clientHeight <= 2) {
      setActiveTurn(turnRefs.current.length - 1);
      return;
    }
    const marker = conversation.getBoundingClientRect().top + Math.min(100, conversation.clientHeight * .25);
    let next = 0;
    for (let index = 0; index < turnRefs.current.length; index += 1) {
      const turn = turnRefs.current[index];
      if (!turn || turn.getBoundingClientRect().top > marker) break;
      next = index;
    }
    setActiveTurn((current) => current === next ? current : next);
  }, []);

  const navigateToTurn = (index: number) => {
    setActiveTurn(index);
    const conversation = conversationRef.current;
    const turn = turnRefs.current[index];
    if (!conversation || !turn) return;
    conversation.scrollTo({
      top: conversation.scrollTop + turn.getBoundingClientRect().top - conversation.getBoundingClientRect().top - 18,
      behavior: 'smooth',
    });
  };

  useEffect(() => { updateActiveTurn(); }, [snapshot, updateActiveTurn]);

  return <section className="project-aow-session-snapshot" aria-label={`${session.title} 会话快照`}>
    <header className="project-aow-snapshot-header">
      <AgentIcon agentId={session.agent} />
      <div className="project-aow-snapshot-heading">
        <h2 title={session.title}>{session.title}</h2>
        <div><span>{agentName}</span><span>·</span><span>{turnCount} 轮对话</span>{!publicView && <span className="project-aow-snapshot-workspace" title={`${session.cwd} · ${session.session_id}`}>{session.cwd}</span>}</div>
      </div>
      {snapshot ? <>
        <span className={`status ${snapshot.status}`}>{statusNames[snapshot.status]}</span>
        {snapshot.truncated ? <span className="warning">最近 200 轮</span> : null}
        <time className="project-aow-snapshot-captured" dateTime={snapshot.captured_at}>更新于 {time(snapshot.captured_at)}</time>
      </> : null}
      {turnCount > 1 && <button className="project-aow-snapshot-latest" type="button" onClick={() => navigateToTurn(turnCount - 1)}><ArrowDownToLine /><span>最新一轮</span></button>}
      {actions}
      <button title="刷新会话快照" aria-label="刷新会话快照" disabled={loading} onClick={onRefresh}><RefreshCw className={loading ? 'spinning' : ''} /></button>
    </header>
    <div className="project-aow-snapshot-body">
      <div className="project-aow-snapshot-conversation" ref={conversationRef} onScroll={updateActiveTurn}>
        {loading && !snapshot ? <div className="project-aow-snapshot-state"><LoaderCircle className="spinning" />正在读取会话快照…</div> : null}
        {error ? <div className="project-aow-snapshot-state error"><AlertCircle />{error}<button onClick={onRefresh}>重试</button></div> : null}
        {!loading && !error && snapshot && !snapshot.turns.length ? <div className="project-aow-snapshot-state"><History />这个会话还没有可展示的用户输入。</div> : null}
        {snapshot?.turns.length ? <div className="project-aow-snapshot-chat">
          {snapshot.turns.map((turn, index) => <article
            className="project-aow-snapshot-turn"
            key={turn.id}
            ref={(node) => { turnRefs.current[index] = node; }}
          >
            <div className="project-aow-snapshot-turn-label"><span>第 {index + 1} 轮</span>{index === turnCount - 1 && <span className="latest">最新一轮</span>}<span className={`turn-status ${turn.status}`}>{statusNames[turn.status]}</span></div>
            <section className="project-aow-snapshot-message user">
              <header className="project-aow-snapshot-message-header"><UserRound size={22} /><strong>User</strong>{turn.user.timestamp && <time dateTime={turn.user.timestamp}>{time(turn.user.timestamp)}</time>}</header>
              <div className="project-aow-snapshot-bubble">
                <SessionMessageContent text={turn.user.text} previewImages={!publicView} />
              </div>
            </section>
            <section className={`project-aow-snapshot-message assistant ${session.agent}`}>
              <div className="project-aow-snapshot-bubble">
                <header className="project-aow-snapshot-message-header"><AgentIcon agentId={session.agent} /><strong>{agentName}</strong>{turn.final?.timestamp && <time dateTime={turn.final.timestamp}>{time(turn.final.timestamp)}</time>}</header>
                <SessionTurnProcess key={`${session.id}:${turn.id}:${index === turnCount - 1}`} turn={turn} isLatest={index === turnCount - 1} />
                {turn.final && <div className="project-aow-snapshot-conclusion"><SessionMessageContent text={turn.final.text} imageReferenceText={turn.user.text} previewImages={!publicView} /></div>}
                <SessionTurnPending turn={turn} />
              </div>
            </section>
          </article>)}
        </div> : null}
      </div>
      {snapshot?.turns.length ? <nav className="project-aow-snapshot-navigation" aria-label="用户输入导航">
        <header><strong>对话导航</strong><span>{snapshot.turns.length}</span></header>
        <ol>
          {snapshot.turns.map((turn, index) => <li key={turn.id}>
            <button
              className={activeTurn === index ? 'active' : undefined}
              type="button"
              title={turn.user.text}
              aria-current={activeTurn === index ? 'location' : undefined}
              ref={(node) => { navigationRefs.current[index] = node; }}
              onClick={() => navigateToTurn(index)}
            >
              <span>{index + 1}</span>
              <strong>{promptPreview(turn.user.text)}</strong>
              <i className={turn.status} title={statusNames[turn.status]} />
            </button>
          </li>)}
        </ol>
      </nav> : null}
    </div>
  </section>;
}

import { useEffect, useId, useState } from 'react';
import { Check, ChevronRight, Circle, CircleAlert, LoaderCircle, MessageSquare, Minus, Wrench } from 'lucide-react';
import type { AgentSessionActivity, AgentSessionSnapshotTurn, AgentSessionToolText } from './types';
import { activityTimeLabel, groupSessionActivities, toolGroupStatus, toolSummary } from './sessionProcessPresentation';
import './session-turn-process.css';

const statusLabels = { completed: '已完成', failed: '失败', interrupted: '已中断', in_progress: '执行中', unknown: '结果未记录' };

function ActivityTimeMarker({ activities, kind }: { activities: AgentSessionActivity[]; kind: AgentSessionActivity['kind'] }) {
  const label = activityTimeLabel(activities);
  const description = kind === 'commentary' ? '进度说明时间' : activities.length > 1 ? '工具组记录时间' : '工具调用时间';
  return <span className="session-process-marker" title={label} role="img" aria-label={`${description}：${label}`} tabIndex={0}>
    {kind === 'tool' ? <Wrench size={12} aria-hidden="true" /> : <MessageSquare size={12} aria-hidden="true" />}
  </span>;
}

function ToolStatus({ status, label = statusLabels[status ?? 'unknown'] }: { status: AgentSessionActivity['status']; label?: string }) {
  const Icon = status === 'completed' ? Check : status === 'failed' ? CircleAlert
    : status === 'in_progress' ? LoaderCircle : status === 'interrupted' ? Minus : Circle;
  return <span className={`session-process-status ${status ?? 'unknown'}`} title={label}>
    <Icon size={13} className={status === 'in_progress' ? 'spinning' : undefined} aria-hidden="true" />
    <span>{label}</span>
  </span>;
}

function ToolText({ label, value, error = false }: { label: string; value?: AgentSessionToolText; error?: boolean }) {
  if (!value) return null;
  return <div className={`session-tool-text${error ? ' error' : ''}`}>
    <div className="session-tool-text-label">{label}{value.truncated && <span>内容过长，仅保留开头和结尾</span>}</div>
    <pre tabIndex={0} aria-label={label}>{value.text}</pre>
  </div>;
}

function ToolRow({ tool }: { tool: AgentSessionActivity }) {
  const [expanded, setExpanded] = useState(false);
  const contentId = useId();
  const details = tool.details;
  const preview = (details?.command?.text ?? details?.input?.text)?.replace(/\s+/g, ' ').slice(0, 240);
  const heading = <>
    <span>{toolSummary([tool])}</span>
    <code>{tool.text}</code>
    <ToolStatus status={tool.status} />
  </>;
  if (!details) return <div className="session-process-tool">{heading}</div>;
  return <div className={`session-process-tool has-details${tool.status === 'failed' ? ' failed' : ''}`}>
    <button type="button" className="session-tool-toggle" aria-expanded={expanded} aria-controls={contentId}
      aria-label={`${expanded ? '收起' : '展开'}工具调用详情：${tool.text}`} onClick={() => setExpanded(!expanded)}>
      {heading}
      <ChevronRight className="session-tool-chevron" size={13} aria-hidden="true" />
    </button>
    {preview && <code className="session-tool-preview">{preview}</code>}
    <div id={contentId} className="session-tool-detail" hidden={!expanded}>
      {expanded && <>
        <ToolText label="命令" value={details.command} />
        {details.command && details.input ? <details className="session-tool-input">
          <summary>输入参数</summary><ToolText label="完整输入参数" value={details.input} />
        </details> : <ToolText label="输入参数" value={details.input} />}
        <ToolText label="工作目录" value={details.cwd} />
        {(details.exit_code !== undefined || details.duration_ms !== undefined) && <div className="session-tool-metadata">
          {details.exit_code !== undefined && <span>退出码：<code>{details.exit_code}</code></span>}
          {details.duration_ms !== undefined && <span>耗时：{details.duration_ms < 1 ? '<1' : details.duration_ms} ms</span>}
        </div>}
        <ToolText label="错误输出" value={details.error} error />
        <ToolText label="执行输出" value={details.output} />
        {!details.output && !details.error && <p className="session-tool-empty">
          {tool.status === 'in_progress' ? '等待执行输出…' : '未记录输出内容。'}
        </p>}
      </>}
    </div>
  </div>;
}

function ToolGroup({ tools }: { tools: AgentSessionActivity[] }) {
  const [expanded, setExpanded] = useState(false);
  const contentId = useId();
  const summary = toolSummary(tools);
  const status = toolGroupStatus(tools);
  if (tools.length === 1) return <ToolRow tool={tools[0]} />;
  return <div className="session-tool-group">
    <button type="button" className="session-tool-group-toggle" aria-expanded={expanded} aria-controls={contentId}
      aria-label={`${expanded ? '收起' : '展开'}工具调用：${summary}`} onClick={() => setExpanded(!expanded)}>
      <span className="session-tool-group-summary">{summary}</span>
      <span className="session-tool-group-count">{tools.length} 次调用</span>
      <ToolStatus {...status} />
      <ChevronRight className="session-tool-group-chevron" size={13} aria-hidden="true" />
    </button>
    <div id={contentId} hidden={!expanded}>
      {expanded && <ol className="session-tool-group-details">
        {tools.map((tool) => <li key={tool.id}>
          <ActivityTimeMarker activities={[tool]} kind="tool" />
          <ToolRow tool={tool} />
        </li>)}
      </ol>}
    </div>
  </div>;
}

// The parent keys this by session, turn and latest/history role. Snapshot refreshes
// preserve a manual choice; finished and historical turns default to collapsed.
export function SessionTurnProcess({ turn, isLatest }: { turn: AgentSessionSnapshotTurn; isLatest: boolean }) {
  const [expanded, setExpanded] = useState(isLatest && turn.status === 'in_progress');
  const contentId = useId();
  useEffect(() => {
    if (turn.status !== 'in_progress') setExpanded(false);
  }, [turn.status]);
  const activities = turn.activities ?? [];
  if (!activities.length && !turn.activities_truncated) return null;
  const toolCount = activities.filter((item) => item.kind === 'tool').length;
  const progressCount = activities.length - toolCount;
  const entries = groupSessionActivities(activities);

  return <div className={`session-turn-process${expanded ? ' expanded' : ''}`}>
    <button type="button" className="session-process-toggle" aria-expanded={expanded} aria-controls={contentId}
      aria-label={expanded ? '收起处理过程' : '展开处理过程'} onClick={() => setExpanded((value) => !value)}>
      <ChevronRight size={14} className="session-process-chevron" aria-hidden="true" />
      <span>处理过程</span>
      <span className="session-process-count">{[toolCount ? `${toolCount} 次工具调用` : '', progressCount ? `${progressCount} 条进度` : ''].filter(Boolean).join(' · ')}</span>
      <span className="session-process-action">{expanded ? '收起' : '展开'}</span>
    </button>
    <div id={contentId} hidden={!expanded}>
      {expanded && <>
        {turn.activities_truncated && <p className="session-process-notice">过程较长，仅展示最近的 {activities.length} 条记录。</p>}
        <ol className="session-process-timeline">
          {entries.map((entry) => <li key={entry.id} className={`session-process-item ${entry.kind}`}>
            <ActivityTimeMarker activities={entry.kind === 'tools' ? entry.tools : [entry.item]} kind={entry.kind === 'tools' ? 'tool' : 'commentary'} />
            {entry.kind === 'commentary' ? <p>{entry.item.text}</p> : <ToolGroup tools={entry.tools} />}
          </li>)}
        </ol>
      </>}
    </div>
  </div>;
}

export function SessionTurnPending({ turn }: { turn: AgentSessionSnapshotTurn }) {
  if (turn.final) return null;
  const descriptions = {
    in_progress: 'Agent 正在处理，尚未生成最终结论。',
    failed: '本轮执行失败，未生成最终结论。',
    interrupted: '本轮已中断，未生成最终结论。',
    completed: '本轮未记录最终结论。',
  };
  return <p className={`session-turn-pending ${turn.status}`}>
    {turn.status === 'in_progress' ? <LoaderCircle size={14} className="spinning" aria-hidden="true" /> : <CircleAlert size={14} aria-hidden="true" />}
    {descriptions[turn.status]}
  </p>;
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { AlertCircle, LoaderCircle, Share2 } from 'lucide-react';
import { SessionSnapshotView } from './SessionSnapshotView';
import { sessionShareApi, SessionShareError } from './sessionShareApi';
import type { AgentSessionSnapshot } from './types';
import './session-share.css';

export function SharedSessionPage({ token }: { token: string }) {
  const [snapshot, setSnapshot] = useState<AgentSessionSnapshot>();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [unavailable, setUnavailable] = useState(false);
  const reloadRef = useRef<() => void>(() => {});
  const refresh = useCallback(() => reloadRef.current(), []);

  useEffect(() => {
    let active = true;
    let stopped = false;
    let request: AbortController | undefined;
    let timer: number | undefined;
    const update = async () => {
      if (!active || stopped || request || document.visibilityState !== 'visible') return;
      window.clearTimeout(timer);
      const controller = new AbortController();
      request = controller;
      setLoading(true);
      try {
        const next = await sessionShareApi.read(token, controller.signal);
        if (active && !controller.signal.aborted) { setSnapshot(next); setError(''); }
      } catch (reason) {
        if (!active || controller.signal.aborted) return;
        if (reason instanceof SessionShareError && (reason.status === 404 || reason.status === 410)) {
          stopped = true;
          setSnapshot(undefined);
          setUnavailable(true);
        }
        setError(reason instanceof Error ? reason.message : '读取会话失败，请稍后重试');
      } finally {
        // A hidden tab may abort this request and start another one immediately
        // on becoming visible. Its old completion must not replace the new timer.
        if (active && request === controller) {
          request = undefined;
          setLoading(false);
          if (!stopped && document.visibilityState === 'visible') timer = window.setTimeout(() => void update(), 10_000);
        }
      }
    };
    const visibility = () => {
      if (document.visibilityState === 'visible') void update();
      else {
        window.clearTimeout(timer);
        const pending = request;
        request = undefined;
        pending?.abort();
      }
    };
    reloadRef.current = () => void update();
    document.addEventListener('visibilitychange', visibility);
    void update();
    return () => { active = false; request?.abort(); window.clearTimeout(timer); document.removeEventListener('visibilitychange', visibility); };
  }, [token]);

  return <main className="shared-session-page">
    <div className="shared-session-banner"><Share2 size={15} /><strong>会话分享 · 只读</strong><span>内容每 10 秒自动更新</span></div>
    {snapshot ? <SessionSnapshotView session={{ id: `${snapshot.agent}:${snapshot.session_id}`, agent: snapshot.agent, title: snapshot.title }}
      snapshot={snapshot} loading={loading} error={error} onRefresh={refresh} publicView />
      : <div className="shared-session-state" role={error ? 'alert' : 'status'}>
        {loading ? <LoaderCircle className="spinning" /> : <AlertCircle />}
        <p>{error || '正在读取分享会话…'}</p>
        {!loading && !unavailable && <button type="button" onClick={refresh}>重试</button>}
      </div>}
  </main>;
}

import type { AowAgentSession, AgentSessionSnapshot } from './types';
