import { useEffect, useRef, type PointerEvent, type RefObject } from 'react';
import type { TerminalFrame, TerminalPaneControls } from './terminalPresentation';

type Point = { x: number; y: number };
type Gesture = { x: number; y: number; lastY: number; axis?: 'vertical' | 'horizontal'; remainder: number };
const TOUCH_SCROLL_MULTIPLIER = 2;

export function useMobileTerminalGestures(viewport: RefObject<HTMLDivElement | null>, controls: RefObject<TerminalPaneControls | null>,
  frame: TerminalFrame, visible: boolean, fontSize: number, onFontSizeChange: (size: number) => void) {
  const cellHeight = useRef(15);
  cellHeight.current = Math.max(1, frame.height / frame.rows);
  const zoom = useRef({ fontSize, onFontSizeChange });
  zoom.current = { fontSize, onFontSizeChange };
  const pointers = useRef(new Map<number, Point>());
  const pinch = useRef<{ distance: number; fontSize: number } | undefined>(undefined);
  const multiTouch = useRef(false);
  const gesture = useRef<Gesture | undefined>(undefined);
  const reset = () => { pointers.current.clear(); gesture.current = undefined; pinch.current = undefined; multiTouch.current = false; };
  useEffect(() => { reset(); return reset; }, [visible]);
  useEffect(() => {
    const node = viewport.current;
    if (!node || !visible) return;
    let remainder = 0;
    const wheel = (event: WheelEvent) => {
      // Non-bubbling events are the wheel inputs sent through xterm by our scroll control.
      if (!event.bubbles) return;
      event.preventDefault();
      event.stopPropagation();
      if (event.ctrlKey) {
        zoom.current.onFontSizeChange(zoom.current.fontSize * Math.exp(-event.deltaY * .01));
        return;
      }
      if (event.shiftKey) return;
      const unit = event.deltaMode === WheelEvent.DOM_DELTA_LINE ? cellHeight.current : event.deltaMode === WheelEvent.DOM_DELTA_PAGE ? node.clientHeight : 1;
      remainder += event.deltaY * unit / cellHeight.current;
      const lines = Math.trunc(remainder);
      if (lines) { controls.current?.scroll(lines, event); remainder -= lines; }
    };
    node.addEventListener('wheel', wheel, { capture: true, passive: false });
    return () => node.removeEventListener('wheel', wheel, { capture: true });
  }, [visible, viewport, controls]);
  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || !visible) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    pointers.current.set(event.pointerId, { x: event.clientX, y: event.clientY });
    if (pointers.current.size >= 2) {
      multiTouch.current = true;
      gesture.current = undefined;
      const [first, second] = [...pointers.current.values()];
      pinch.current = { distance: Math.hypot(first.x - second.x, first.y - second.y), fontSize: zoom.current.fontSize };
    } else if (!multiTouch.current) {
      gesture.current = { x: event.clientX, y: event.clientY, lastY: event.clientY, remainder: 0 };
    }
  };
  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (!pointers.current.has(event.pointerId)) return;
    pointers.current.set(event.pointerId, { x: event.clientX, y: event.clientY });
    if (pointers.current.size >= 2 && pinch.current && pinch.current.distance > 0) {
      const [first, second] = [...pointers.current.values()];
      const distance = Math.hypot(first.x - second.x, first.y - second.y);
      zoom.current.onFontSizeChange(pinch.current.fontSize * distance / pinch.current.distance);
      return;
    }
    const start = gesture.current;
    if (multiTouch.current || !start) return;
    const dx = start.x - event.clientX;
    const dy = start.y - event.clientY;
    if (!start.axis && Math.max(Math.abs(dx), Math.abs(dy)) < 4) return;
    start.axis ??= Math.abs(dx) > Math.abs(dy) ? 'horizontal' : 'vertical';
    if (start.axis === 'vertical') {
      start.remainder += (start.lastY - event.clientY) * TOUCH_SCROLL_MULTIPLIER / cellHeight.current;
      const lines = Math.trunc(start.remainder);
      if (lines) { controls.current?.scroll(lines, event); start.remainder -= lines; }
    }
    start.lastY = event.clientY;
  };
  const onPointerEnd = (event: PointerEvent<HTMLDivElement>) => {
    pointers.current.delete(event.pointerId);
    pinch.current = undefined;
    if (!pointers.current.size) { gesture.current = undefined; multiTouch.current = false; }
  };
  return { onPointerDown, onPointerMove, onPointerUp: onPointerEnd, onPointerCancel: onPointerEnd, onLostPointerCapture: onPointerEnd };
}

import { useLayoutEffect, useRef, type RefObject } from 'react';
import type { TerminalFrame } from './terminalPresentation';

export function useMobileTerminalSurface(viewport: RefObject<HTMLDivElement | null>, frame: TerminalFrame, visible: boolean) {
  const surface = useRef<HTMLDivElement>(null);
  const currentFrame = useRef(frame);
  const updateSurface = useRef<() => void>(() => {});

  useLayoutEffect(() => {
    const clip = viewport.current;
    const node = surface.current;
    if (!clip || !node) return;
    const root = document.documentElement;
    let width = 0;
    let height = 0;
    const update = () => {
      const bounds = clip.getBoundingClientRect();
      if (!bounds.width || !bounds.height) return;
      const inset = parseFloat(root.style.getPropertyValue('--mobile-keyboard-inset')) || 0;
      // Pin the actual surface size throughout keyboard animation. Only the
      // clipping viewport shrinks; xterm's ResizeObserver sees no size change.
      if (!height || bounds.width !== width || inset === 0) {
        const safeArea = parseFloat(getComputedStyle(root).getPropertyValue('--mobile-keyboard-safe-area')) || 0;
        const nextHeight = Math.max(1, bounds.height + inset - safeArea);
        if (height !== nextHeight) node.style.height = `${nextHeight}px`;
        height = nextHeight;
        width = bounds.width;
      }
      const frame = currentFrame.current;
      const bottom = frame.top + frame.height;
      const cursorBottom = frame.top + (frame.cursorRow + 1) * frame.height / frame.rows;
      const offset = Math.max(0, Math.min(bottom - bounds.height, cursorBottom - bounds.height));
      // ResizeObserver runs before paint. Update the composited surface here,
      // without a React state update that can leave translation one frame late.
      // Whole device pixels also avoid changing glyph rasterization on the move.
      const dpr = window.devicePixelRatio || 1;
      const transform = `translate3d(0, ${-Math.round(offset * dpr) / dpr}px, 0)`;
      if (node.style.transform !== transform) node.style.transform = transform;
    };
    updateSurface.current = update;
    const observer = new ResizeObserver(update);
    observer.observe(clip);
    update();
    return () => { observer.disconnect(); updateSurface.current = () => {}; };
  }, [viewport]);

  useLayoutEffect(() => {
    currentFrame.current = frame;
    updateSurface.current();
  }, [frame, visible]);

  return surface;
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { terminalApi } from './terminalApi';
import type { TerminalAgentList, TerminalPaneStatus, TerminalTab } from './types';
import type { AowWorktree } from '../../aow/types';

const empty = { tabs: [] as TerminalTab[], agents: {}, titles: {}, processes: {} };

// Listing a repository's terminals must not mount their emulators or attach to PTYs.
export function useProjectTerminals(worktrees: AowWorktree[], enabled: boolean) {
  const rootsKey = JSON.stringify(worktrees.map(worktree => worktree.path).sort());
  const roots = useMemo(() => new Set<string>(JSON.parse(rootsKey)), [rootsKey]);
  const [snapshot, setSnapshot] = useState<(TerminalAgentList & { rootsKey: string; tabs: TerminalTab[] })>();
  const [error, setError] = useState('');
  const [revision, setRevision] = useState(0);
  const reload = useCallback(() => setRevision(value => value + 1), []);

  useEffect(() => {
    if (!enabled) return;
    const controller = new AbortController();
    let pending = false;
    const refresh = async () => {
      if (pending || document.visibilityState !== 'visible') return;
      pending = true;
      try {
        const [tabs, metadata] = await Promise.all([
          terminalApi.list(undefined, controller.signal),
          terminalApi.agents(undefined, controller.signal),
        ]);
        if (controller.signal.aborted) return;
        setSnapshot({ rootsKey, tabs: tabs.filter(tab => roots.has(tab.workspace_root)), ...metadata });
        setError('');
      } catch (reason) {
        if (!controller.signal.aborted) setError(reason instanceof Error ? reason.message : String(reason));
      } finally {
        pending = false;
      }
    };
    void refresh();
    const timer = window.setInterval(() => void refresh(), 3000);
    document.addEventListener('visibilitychange', refresh);
    return () => {
      controller.abort();
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', refresh);
    };
  }, [enabled, rootsKey, roots, revision]);

  const remove = useCallback((id: string) => {
    setSnapshot(current => current && { ...current, tabs: current.tabs.filter(tab => tab.id !== id) });
    reload();
  }, [reload]);

  const updatePaneStatus = useCallback((tabId: string, paneId: string, status: TerminalPaneStatus, exitCode?: number | null) => {
    setSnapshot(current => current && { ...current, tabs: current.tabs.map(tab => tab.id === tabId ? {
      ...tab, panes: tab.panes.map(pane => pane.id === paneId
        ? { ...pane, status, ...(exitCode === undefined ? {} : { exit_code: exitCode }) } : pane),
    } : tab) });
  }, []);

  const current = snapshot?.rootsKey === rootsKey ? snapshot : undefined;
  return { ...(current ?? empty), error, loaded: !!current, loading: enabled && !current && !error, reload, remove, updatePaneStatus };
}

import { useEffect, useState } from 'react';
import { terminalApi } from './terminalApi';
import type { TerminalAgentList } from './types';

const emptyMetadata: TerminalAgentList = { agents: {}, titles: {}, processes: {} };

function sameValues(a: Record<string, string | null>, b: Record<string, string | null>) {
  return Object.keys(a).length === Object.keys(b).length
    && Object.entries(a).every(([id, value]) => b[id] === value);
}

export function useTerminalAgents(workspaceRoot: string, enabled: boolean) {
  const [snapshot, setSnapshot] = useState({ root: workspaceRoot, metadata: emptyMetadata });

  useEffect(() => {
    if (!enabled) return;
    const controller = new AbortController();
    let pending = false;
    const update = (metadata: TerminalAgentList) => {
      if (controller.signal.aborted) return;
      setSnapshot(previous => previous.root === workspaceRoot
        && sameValues(previous.metadata.agents, metadata.agents)
        && sameValues(previous.metadata.titles, metadata.titles)
        && Object.keys(previous.metadata.processes).length === Object.keys(metadata.processes).length
        && Object.entries(previous.metadata.processes).every(([id, process]) => {
          const next = metadata.processes[id];
          return next?.pid === process.pid && next.start_time === process.start_time && next.cwd === process.cwd;
        })
        ? previous : { root: workspaceRoot, metadata });
    };
    const refresh = async () => {
      if (pending || document.visibilityState !== 'visible') return;
      pending = true;
      try { update(await terminalApi.agents(workspaceRoot, controller.signal)); }
      catch { /* A failed poll is not evidence that the agent exited. */ }
      finally { pending = false; }
    };
    void refresh();
    const timer = window.setInterval(() => void refresh(), 1500);
    document.addEventListener('visibilitychange', refresh);
    return () => {
      controller.abort();
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', refresh);
    };
  }, [workspaceRoot, enabled]);

  return snapshot.root === workspaceRoot ? snapshot.metadata : emptyMetadata;
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { terminalApi } from './terminalApi';
import { isCliTerminal } from './terminalPresentation';
import { useTerminalAgents } from './useTerminalAgents';
import type { TerminalLayout, TerminalPaneStatus, TerminalTab } from './types';

function message(reason: unknown) {
  return reason instanceof Error ? reason.message : String(reason);
}

function reorderTabs(items: TerminalTab[], tabIds: string[]) {
  if (items.length !== tabIds.length) return items;
  const byId = new Map(items.map((tab) => [tab.id, tab]));
  const ordered = tabIds.map((id) => byId.get(id));
  return ordered.every((tab): tab is TerminalTab => tab !== undefined) ? ordered : items;
}

function sameLayout(left: TerminalLayout | null, right: TerminalLayout | null): boolean {
  if (left === right) return true;
  if (!left || !right) return false;
  if (left.type === 'pane') return right.type === 'pane' && left.pane_id === right.pane_id;
  return right.type === 'split' && left.axis === right.axis && left.ratio === right.ratio
    && sameLayout(left.first, right.first) && sameLayout(left.second, right.second);
}

export function useTerminals(workspaceRoot: string, enabled: boolean) {
  const [tabs, setTabs] = useState<TerminalTab[]>([]);
  const [activeId, setActiveId] = useState<string>();
  const [loading, setLoading] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const busyRef = useRef(busy);
  busyRef.current = busy;
  const requestGeneration = useRef(0);
  const busyGeneration = useRef(0);
  const workspaceGeneration = useRef(0);
  const workspaceRootRef = useRef(workspaceRoot);
  const stateRootRef = useRef(workspaceRoot);
  const loadedRootRef = useRef<string | undefined>(undefined);
  const tabsRef = useRef(tabs);
  tabsRef.current = tabs;

  if (workspaceRootRef.current !== workspaceRoot) {
    workspaceRootRef.current = workspaceRoot;
    workspaceGeneration.current += 1;
  }

  const load = useCallback(async (quiet = false) => {
    if (workspaceRootRef.current !== workspaceRoot || (quiet && busyRef.current)) return;
    const generation = ++requestGeneration.current;
    const rootGeneration = workspaceGeneration.current;
    loadedRootRef.current = workspaceRoot;
    if (!quiet) { setLoading(true); setError(''); }
    try {
      const nextTabs = await terminalApi.list(workspaceRoot);
      if (requestGeneration.current !== generation
        || workspaceGeneration.current !== rootGeneration
        || workspaceRootRef.current !== workspaceRoot) return;
      stateRootRef.current = workspaceRoot;
      setTabs(current => {
        const previousById = new Map(current.map(tab => [tab.id, tab]));
        return nextTabs.map(tab => {
          const previous = previousById.get(tab.id);
          // A fresh JSON object must not reset TerminalWorkspace's active drag.
          return previous && sameLayout(previous.layout, tab.layout)
            ? { ...tab, layout: previous.layout }
            : tab;
        });
      });
      setLoaded(true);
      setError('');
      setActiveId((current) => nextTabs.some((tab) => tab.id === current) ? current : nextTabs.find(tab => !isCliTerminal(tab))?.id);
    } catch (reason) {
      if (requestGeneration.current === generation
        && workspaceGeneration.current === rootGeneration
        && workspaceRootRef.current === workspaceRoot) setError(message(reason));
    } finally {
      if (requestGeneration.current === generation
        && workspaceGeneration.current === rootGeneration
        && workspaceRootRef.current === workspaceRoot) setLoading(false);
    }
  }, [workspaceRoot]);

  useEffect(() => {
    requestGeneration.current += 1;
    busyGeneration.current += 1;
    loadedRootRef.current = undefined;
    stateRootRef.current = workspaceRoot;
    setTabs([]);
    setLoaded(false);
    setActiveId(undefined);
    setLoading(false);
    setBusy(false);
    setError('');
  }, [workspaceRoot]);

  useEffect(() => {
    if (enabled && loadedRootRef.current !== workspaceRoot) void load();
  }, [enabled, load]);

  useEffect(() => {
    if (!enabled) return;
    let pending = false;
    const timer = window.setInterval(() => {
      if (document.visibilityState === 'visible' && !pending) {
        pending = true;
        void load(true).finally(() => { pending = false; });
      }
    }, 3000);
    return () => window.clearInterval(timer);
  }, [enabled, load]);

  const create = useCallback(async () => {
    if (workspaceRootRef.current !== workspaceRoot) return null;
    requestGeneration.current += 1;
    const operationGeneration = ++busyGeneration.current;
    const rootGeneration = workspaceGeneration.current;
    setLoading(false);
    setBusy(true);
    setError('');
    try {
      const tab = await terminalApi.create(workspaceRoot, { cwd: workspaceRoot });
      if (workspaceGeneration.current !== rootGeneration
        || workspaceRootRef.current !== workspaceRoot) return null;
      stateRootRef.current = workspaceRoot;
      setTabs((items) => [...items.filter((item) => item.id !== tab.id), tab]);
      setActiveId(tab.id);
      return tab;
    } catch (reason) {
      if (workspaceGeneration.current === rootGeneration
        && workspaceRootRef.current === workspaceRoot) setError(message(reason));
      return null;
    } finally {
      if (busyGeneration.current === operationGeneration
        && workspaceGeneration.current === rootGeneration
        && workspaceRootRef.current === workspaceRoot) setBusy(false);
    }
  }, [workspaceRoot]);

  const rename = useCallback(async (tabId: string, nextName: string) => {
    const name = nextName.trim();
    if (!name) return;
    const root = workspaceRootRef.current;
    const rootGeneration = workspaceGeneration.current;
    const operationGeneration = ++busyGeneration.current;
    requestGeneration.current += 1;
    setLoading(false);
    setBusy(true);
    setError('');
    try {
      const updated = await terminalApi.rename(tabId, name);
      if (workspaceGeneration.current !== rootGeneration || workspaceRootRef.current !== root) return;
      setTabs((items) => items.map((tab) => tab.id === tabId ? { ...(updated ?? tab), name, name_is_custom: true } : tab));
    } catch (reason) {
      if (workspaceGeneration.current === rootGeneration && workspaceRootRef.current === root) setError(message(reason));
    } finally {
      if (busyGeneration.current === operationGeneration
        && workspaceGeneration.current === rootGeneration
        && workspaceRootRef.current === root) setBusy(false);
    }
  }, []);

  const reorder = useCallback(async (tabIds: string[]) => {
    const root = workspaceRootRef.current;
    const rootGeneration = workspaceGeneration.current;
    const previousIds = tabsRef.current.map((tab) => tab.id);
    if (previousIds.length !== tabIds.length
      || previousIds.some((id) => !tabIds.includes(id))
      || previousIds.every((id, index) => id === tabIds[index])) return;
    const operationGeneration = ++busyGeneration.current;
    requestGeneration.current += 1;
    setLoading(false);
    setBusy(true);
    setError('');
    setTabs((items) => reorderTabs(items, tabIds));
    try {
      const reordered = await terminalApi.reorder(root, tabIds);
      if (workspaceGeneration.current !== rootGeneration || workspaceRootRef.current !== root) return;
      stateRootRef.current = root;
      setTabs((items) => reorderTabs(items, reordered.map((tab) => tab.id)));
    } catch (reason) {
      if (workspaceGeneration.current === rootGeneration && workspaceRootRef.current === root) {
        setTabs((items) => reorderTabs(items, previousIds));
        setError(message(reason));
      }
    } finally {
      if (busyGeneration.current === operationGeneration
        && workspaceGeneration.current === rootGeneration
        && workspaceRootRef.current === root) setBusy(false);
    }
  }, []);

  const close = useCallback(async (tabId: string) => {
    const root = workspaceRootRef.current;
    const rootGeneration = workspaceGeneration.current;
    const operationGeneration = ++busyGeneration.current;
    requestGeneration.current += 1;
    setLoading(false);
    setBusy(true);
    setError('');
    try {
      await terminalApi.close(tabId);
      if (workspaceGeneration.current !== rootGeneration || workspaceRootRef.current !== root) return;
      setTabs((items) => {
        const index = items.findIndex((item) => item.id === tabId);
        const remaining = items.filter((item) => item.id !== tabId);
        setActiveId((current) => current === tabId
          ? remaining[Math.min(Math.max(index, 0), remaining.length - 1)]?.id
          : current);
        return remaining;
      });
    } catch (reason) {
      if (workspaceGeneration.current === rootGeneration && workspaceRootRef.current === root) setError(message(reason));
    } finally {
      if (busyGeneration.current === operationGeneration
        && workspaceGeneration.current === rootGeneration
        && workspaceRootRef.current === root) setBusy(false);
    }
  }, []);

  const remove = useCallback((tabId: string) => {
    setTabs((items) => {
      const index = items.findIndex((item) => item.id === tabId);
      if (index < 0) return items;
      const remaining = items.filter((item) => item.id !== tabId);
      setActiveId((current) => current === tabId
        ? remaining[Math.min(index, remaining.length - 1)]?.id
        : current);
      return remaining;
    });
  }, []);

  const replace = useCallback((updated: TerminalTab) => {
    if (updated.workspace_root !== workspaceRootRef.current) return;
    requestGeneration.current += 1;
    setLoading(false);
    setTabs((items) => items.some((tab) => tab.id === updated.id)
      ? items.map((tab) => tab.id === updated.id
        ? typeof tab.revision === 'number' && typeof updated.revision === 'number' && updated.revision < tab.revision
          ? tab
          : updated
        : tab)
      : [...items, updated]);
  }, []);

  const updatePaneStatus = useCallback((tabId: string, paneId: string, status: TerminalPaneStatus, exitCode?: number | null) => {
    const currentRoot = workspaceRootRef.current;
    if (stateRootRef.current !== currentRoot
      || !tabsRef.current.some((tab) => tab.id === tabId && tab.workspace_root === currentRoot)) return;
    requestGeneration.current += 1;
    setLoading(false);
    setTabs((items) => items.map((tab) => tab.id === tabId ? {
      ...tab,
      panes: tab.panes.map((pane) => pane.id === paneId
        ? { ...pane, status, ...(exitCode === undefined ? {} : { exit_code: exitCode }) }
        : pane),
    } : tab));
  }, []);

  const currentTabs = stateRootRef.current === workspaceRoot ? tabs : [];
  const { agents: detectedAgents, titles: terminalTitles, processes: agentProcesses } = useTerminalAgents(workspaceRoot, enabled && currentTabs.length > 0);
  const currentActiveId = stateRootRef.current === workspaceRoot ? activeId : undefined;
  const activeTab = useMemo(
    () => currentTabs.find((tab) => tab.id === currentActiveId),
    [currentActiveId, currentTabs],
  );

  return {
    tabs: currentTabs, activeId: currentActiveId, activeTab, loaded, loading, busy, error, detectedAgents, terminalTitles, agentProcesses,
    activate: setActiveId, create, rename, reorder, close, remove, replace, updatePaneStatus, reload: load,
  };
}

import { appUrl } from './basePath';

class AowHttpError extends Error {}

export async function aowRequest<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(appUrl(url), {
    ...init,
    headers: init?.body === undefined
      ? init?.headers
      : { 'Content-Type': 'application/json', ...init.headers },
  });
  const payload = response.status === 204 ? null : await response.json().catch(() => null);
  if (!response.ok) {
    const message = payload && typeof payload === 'object' && 'message' in payload
      ? String(payload.message)
      : `HTTP ${response.status}`;
    throw new AowHttpError(message);
  }
  return payload as T;
}

// Supplied by the web server before any module runs. Vite development/test
// pages have no metadata and keep using the root deployment.
export const basePath = typeof document === 'undefined' ? ''
  : document.querySelector<HTMLMetaElement>('meta[name="aow-base-path"]')?.content ?? '';

/** Convert a root-relative application URL into a deployment URL, exactly once. */
export function appUrl(path: string): string {
  if (!path.startsWith('/') || path.startsWith('//')) throw new Error('Expected a root-relative application URL');
  return basePath + path;
}

export function appPath(pathname: string): string | undefined {
  if (!basePath) return pathname;
  if (pathname === basePath) return '/';
  return pathname.startsWith(basePath + '/') ? pathname.slice(basePath.length) : undefined;
}

export const appBaseUrl = () => window.location.origin + basePath;

// Preserve existing root-deployment state; isolate subpath deployments on the
// same origin. This is namespacing, not a security boundary between sites.
export const storageKey = (key: string) => basePath ? `aow@${basePath}:${key}` : key;
function scopedStorage(kind: 'localStorage' | 'sessionStorage') {
  return {
    getItem: (key: string) => window[kind].getItem(storageKey(key)),
    setItem: (key: string, value: string) => window[kind].setItem(storageKey(key), value),
    removeItem: (key: string) => window[kind].removeItem(storageKey(key)),
  };
}
export const appLocalStorage = scopedStorage('localStorage');
export const appSessionStorage = scopedStorage('sessionStorage');

import { appUrl } from './basePath';

export class HttpRequestError extends Error {}

export async function fetchWithTimeout(url: string, init?: RequestInit, timeoutMs = 12_000) {
  const controller = new AbortController();
  const signal = init?.signal ? AbortSignal.any([init.signal, controller.signal]) : controller.signal;
  const timer = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(appUrl(url), { ...init, signal });
  } catch (error) {
    init?.signal?.throwIfAborted();
    if (error instanceof DOMException && error.name === 'AbortError') {
      throw new Error(`请求超时（${Math.round(timeoutMs / 1000)} 秒）`);
    }
    throw error;
  } finally {
    window.clearTimeout(timer);
  }
}

export async function request<T>(url: string, init?: RequestInit, retries = 1, timeoutMs = 12_000): Promise<T> {
  for (let attempt = 0; ; attempt += 1) {
    try {
      init?.signal?.throwIfAborted();
      const response = await fetchWithTimeout(url, init, timeoutMs);
      const payload = await response.json().catch(() => null);
      init?.signal?.throwIfAborted();
      if (!response.ok) {
        throw new HttpRequestError(payload?.message ?? payload?.error?.message ?? `HTTP ${response.status}`);
      }
      return payload as T;
    } catch (error) {
      init?.signal?.throwIfAborted();
      if (error instanceof HttpRequestError || attempt >= retries) throw error;
      await new Promise((resolve) => window.setTimeout(resolve, 250));
    }
  }
}

import { appPath } from './lib/basePath';
import { lazy, StrictMode, Suspense } from 'react';
import { createRoot } from 'react-dom/client';
import { LoginGate } from './LoginGate';
import { AgentTaskNotifications } from './features/notifications/AgentTaskNotifications';
import { AowTabEntry } from './aow/AowTabEntry';
import './styles.css';

const mode = new URLSearchParams(window.location.search).get('ui');
const mobile = mode !== 'desktop' && (mode === 'mobile' || /^\/m(?:\/|$)/.test(appPath(window.location.pathname) ?? '')
  || window.matchMedia('(max-width: 820px)').matches);
// Choose once so keyboard and orientation changes never replace a running terminal.
const Aow = mobile
  ? lazy(() => import('./mobile/MobileAow').then((module) => ({ default: module.MobileAow })))
  : lazy(() => import('./aow/desktop'));
const SharedSessionPage = lazy(() => import('./features/sessions/SharedSessionPage').then(module => ({ default: module.SharedSessionPage })));
const shareRoute = /^\/share\/([^/]+)\/?$/.exec(appPath(window.location.pathname) ?? '');
const fallback = <div role="status" style={{ padding: 24, color: '#d7d9de', background: '#181a1f', minHeight: '100dvh', fontFamily: 'system-ui' }}>正在打开 AoW…</div>;

const root = createRoot(document.getElementById('root')!);
root.render(<StrictMode>{shareRoute
  ? <Suspense fallback={fallback}><SharedSessionPage key={shareRoute[1]} token={shareRoute[1]} /></Suspense>
  : <LoginGate><AowTabEntry>{tab => <><Suspense fallback={fallback}><Aow initialEntry={tab} /></Suspense><AgentTaskNotifications /></>}</AowTabEntry></LoginGate>
}</StrictMode>);

import { appUrl } from '../lib/basePath';
import type { ResolvedTab } from '../aow/tabRoutes';
import { mobileTabTarget } from '../aow/tabRoutes/mobile';
import { lazy, Suspense, useEffect, useState } from 'react';
import { ArrowLeft, ArrowUpRight, CalendarClock, ChevronRight, FolderOpen, GitBranch, GitPullRequest, Home, MessageSquare, Pin, PinOff, Search, TerminalSquare, X } from 'lucide-react';
import { aowApi } from '../aow/aowApi';
import { ProjectIcon } from '../aow/ProjectIcon';
import { usePinnedWorktrees } from '../aow/usePinnedWorktrees';
import { useAowTabLocation } from '../aow/AowTabEntry';
import { WorktreeIcon, worktreeColorValues } from '../aow/WorktreeIcon';
import { AowNodeSwitcher } from '../aow/AowNodeSwitcher';
import type { AowProject, AowWorktree } from '../aow/types';
import { MobileRefresh, MobileState } from './MobilePrimitives';
import { mobileRouteUrl, saveMobileValue, storedMobileValue, useMobileResource, useMobileRoute, useMobileScroll, useMobileViewport, type MobileRoute, type MobileView } from './mobileState';
import type { MobileNavigate } from './mobileState';
import './mobile.css';

const MobileTerminals = lazy(() => import('../features/terminals/MobileTerminals').then((module) => ({ default: module.MobileTerminals })));
const MobileSessions = lazy(() => import('../features/sessions/MobileSessions').then((module) => ({ default: module.MobileSessions })));
const MobileFiles = lazy(() => import('../features/files/MobileFiles').then((module) => ({ default: module.MobileFiles })));
const MobileGit = lazy(() => import('../features/git/MobileGit').then((module) => ({ default: module.MobileGit })));
const MobileAutomations = lazy(() => import('../features/automations/MobileAutomations').then((module) => ({ default: module.MobileAutomations })));
const MobilePullRequests = lazy(() => import('../features/pr/MobilePullRequests').then((module) => ({ default: module.MobilePullRequests })));

const navigation = [
  { id: 'terminal', label: '终端', icon: TerminalSquare },
  { id: 'sessions', label: 'Conversation', icon: MessageSquare },
  { id: 'automations', label: '自动化', icon: CalendarClock },
  { id: 'files', label: '文件', icon: FolderOpen },
  { id: 'git', label: 'Git', icon: GitBranch },
  { id: 'pull-requests', label: 'PR', icon: GitPullRequest },
] as const;

export function MobileAow({ initialEntry }: { initialEntry?: ResolvedTab } = {}) {
  const projects = useMobileResource('projects', () => aowApi.projects());
  const { route, navigate, back } = useMobileRoute(initialEntry, projects.data);
  const syncLocation = useAowTabLocation();
  useEffect(() => {
    if (!projects.data || route.view === 'terminal' && route.workspace) return;
    const target = mobileTabTarget(route, projects.data);
    syncLocation(target, target ? '' : mobileRouteUrl(route));
  }, [route, projects.data, syncLocation]);
  const [headerActions, setHeaderActions] = useState<HTMLDivElement | null>(null);
  const project = projects.data?.find((item) => item.worktrees.some((worktree) => worktree.path === route.workspace));
  const worktree = project?.worktrees.find((item) => item.path === route.workspace);
  useMobileViewport(project?.name ?? '项目');
  const goHome = () => navigate({});
  const fallback = { workspace: route.workspace, view: route.view, ...(route.view === 'files' && route.notes ? { notes: route.notes } : {}) };
  return <div className="mobile-app">
    <header className="mobile-app-header">
      {worktree ? <>
        <button className="mobile-icon-button" aria-label="返回项目列表" onClick={goHome}><ArrowLeft size={21} /></button>
        <button className="mobile-brand-title" onClick={goHome}><strong>{project?.name}</strong><span>{worktree.branch || 'Detached HEAD'}</span></button>
      </> : <MobileNodeSwitcher />}
      <div className="mobile-header-actions" ref={setHeaderActions} />
    </header>
    {route.workspace ? project && worktree ? <MobileWorkspace initialTabId={route.terminal} key={worktree.path} project={project} worktree={worktree} route={route} navigate={navigate} back={() => back(fallback)} headerActions={headerActions} />
      : <div className="mobile-home"><MobileState loading={projects.loading} error={projects.error} retry={projects.reload} empty="工作区不存在或已被移除。" /><button className="mobile-button" onClick={goHome}><Home size={17} />返回项目</button></div>
      : <MobileHome projects={projects.data?.filter(project => !project.builtin) ?? []} loading={projects.loading} error={projects.error} reload={projects.reload} navigate={navigate} />}
  </div>;
}

function MobileNodeSwitcher() {
  const settings = useMobileResource('aow-settings', () => aowApi.settings());
  return <AowNodeSwitcher mobile addresses={settings.data ? settings.data.node_addresses ?? [] : undefined} error={settings.error} />;
}

function MobileHome({ projects, loading, error, reload, navigate }: {
  projects: AowProject[]; loading: boolean; error?: string; reload: () => void; navigate: MobileNavigate;
}) {
  const [query, setQuery] = useState(() => storedMobileValue('project-search'));
  const [pinned, setPinned, pinnedState] = usePinnedWorktrees();
  const scroll = useMobileScroll('projects', !loading);
  const recentPath = storedMobileValue('recent-workspace');
  const recentProject = projects.find((project) => project.worktrees.some((worktree) => worktree.path === recentPath));
  const recent = recentProject?.worktrees.find((worktree) => worktree.path === recentPath);
  const open = (workspace: string) => { saveMobileValue('recent-workspace', workspace); navigate({ workspace, view: 'terminal' }); };
  const filtered = projects.map((project) => ({ ...project, worktrees: project.worktrees.filter((worktree) => `${project.name} ${worktree.branch} ${worktree.path}`.toLowerCase().includes(query.toLowerCase())) })).filter((project) => project.worktrees.length || project.name.toLowerCase().includes(query.toLowerCase()));
  const matchingEntries = new Map(filtered.flatMap((project) => project.worktrees.map((worktree) => [worktree.path, { project, worktree }] as const)));
  const pinnedEntries = [...pinned].flatMap((path) => { const entry = matchingEntries.get(path); return entry ? [entry] : []; });
  const togglePin = (path: string) => setPinned((current) => {
    const next = new Set(current);
    if (next.has(path)) next.delete(path);
    else next.add(path);
    return next;
  });
  return <main className="mobile-home mobile-scroll" ref={scroll}>
    <div className="mobile-home-heading"><div><span className="mobile-eyebrow">WORKSPACE</span><h1>你的项目</h1></div><MobileRefresh reload={() => { reload(); pinnedState.reload(); }} loading={loading || pinnedState.loading} /></div>
    <label className="mobile-search"><Search size={18} /><input type="search" aria-label="搜索项目或分支" placeholder="搜索项目、分支…" value={query} onChange={(event) => { setQuery(event.target.value); saveMobileValue('project-search', event.target.value); }} /></label>
    {(!query || pinnedEntries.length > 0) && <section className="mobile-pinned" aria-label="Pinned">
      <div className="mobile-home-section"><h3 className="mobile-section-label"><Pin size={13} />Pinned</h3><span>{pinnedEntries.length}</span></div>
      {pinnedState.error && <p className="mobile-inline-error" role="alert">{pinnedState.error}</p>}
      {pinnedEntries.length > 0 ? <div className="mobile-project-card">
        {pinnedEntries.map(({ project, worktree }) => <MobileWorktreeRow key={worktree.path} project={project} worktree={worktree} pinned showProject open={open} togglePin={togglePin} />)}
      </div> : <p className="mobile-pinned-empty">{pinnedState.loading ? '正在同步置顶…' : '点击工作区右侧的图钉，置顶常用工作区。'}</p>}
    </section>}
    {!query && recent && <section className="mobile-recent"><h3 className="mobile-section-label">继续上次的工作</h3><button className="mobile-resume-card" onClick={() => open(recent.path)}>
      <div className="mobile-resume-icon"><WorktreeIcon icon={recent.icon} size={24} style={{ color: worktreeColorValues[recent.color ?? 'default'] }} /></div><div className="mobile-row-main"><strong>{recentProject!.name}</strong><span><GitBranch size={13} />{recent.branch || 'Detached HEAD'}</span></div><ArrowUpRight size={20} />
    </button></section>}
    <div className="mobile-home-section"><h3 className="mobile-section-label">全部项目</h3><span>{projects.length}</span></div>
    <MobileState error={error} loading={loading && !projects.length} retry={reload} empty={!loading && !filtered.length ? (query ? '没有匹配的项目或分支。' : '暂无项目，请先在桌面端注册工作区。') : undefined} />
    {filtered.map((project) => <section className="mobile-project-card" key={project.id}>
      <header><div className="mobile-project-icon"><ProjectIcon project={project} size={28} /></div><div className="mobile-row-main"><h2>{project.name}</h2><span>{project.worktrees.length} 个工作区</span></div></header>
      {project.error && <p className="mobile-inline-error">{project.error}</p>}
      {project.worktrees.map((worktree) => <MobileWorktreeRow key={worktree.path} project={project} worktree={worktree} pinned={pinned.has(worktree.path)} open={open} togglePin={togglePin} />)}
    </section>)}
    {projects.length > 0 && <p className="mobile-home-footer">{projects.reduce((total, project) => total + project.worktrees.length, 0)} 个工作区 · 随时查看，继续工作</p>}
    <footer className="mobile-home-links">
      <a href={appUrl('/?ui=desktop')}><ArrowUpRight size={15} />打开桌面版</a>
      {window.aowHost?.close && <button onClick={() => window.aowHost?.close?.()}><X size={15} />关闭工作台</button>}
    </footer>
  </main>;
}

function MobileWorktreeRow({ project, worktree, pinned, showProject, open, togglePin }: {
  project: AowProject; worktree: AowWorktree; pinned: boolean; showProject?: boolean; open: (path: string) => void; togglePin: (path: string) => void;
}) {
  const branch = worktree.branch || 'Detached HEAD';
  const label = `${project.name} · ${branch}`;
  return <div className="mobile-worktree-item">
    <button className="mobile-worktree-row" onClick={() => open(worktree.path)}>
      <WorktreeIcon icon={worktree.icon} size={17} style={{ color: worktreeColorValues[worktree.color ?? 'default'] }} /><div className="mobile-row-main"><strong>{branch}</strong><span>{showProject ? `${project.name} · ` : ''}{worktree.path.split('/').filter(Boolean).pop()}</span></div>
      {worktree.is_main && <span className="mobile-badge">主目录</span>}<ChevronRight size={15} />
    </button>
    <button className="mobile-pin-button" aria-label={`${pinned ? '取消置顶' : '置顶'} ${label}`} aria-pressed={pinned} title={pinned ? '取消置顶' : '置顶'} onClick={() => togglePin(worktree.path)}>
      {pinned ? <PinOff size={16} /> : <Pin size={16} />}
    </button>
  </div>;
}

function MobileWorkspace({ project, worktree, route, navigate, back, headerActions, initialTabId }: { initialTabId?: string; project: AowProject; worktree: AowWorktree; route: MobileRoute; navigate: MobileNavigate; back: () => void; headerActions: HTMLElement | null }) {
  const [visited, setVisited] = useState<Set<MobileView>>(new Set([route.view]));
  useEffect(() => {
    setVisited((old) => old.has(route.view) ? old : new Set([...old, route.view]));
    saveMobileValue('recent-workspace', worktree.path);
  }, [route.view, worktree.path]);
  return <main className="mobile-workspace" data-view={route.view}>
    <div className="mobile-workspace-pages">
      {navigation.filter(({ id }) => visited.has(id) || id === route.view).map(({ id }) => <div className="mobile-workspace-page" key={id} hidden={id !== route.view}>
        <Suspense fallback={<MobileState loading />}>
          {id === 'terminal' && <MobileTerminals initialTabId={initialTabId} project={project} worktree={worktree} visible={route.view === id} headerActions={headerActions} />}
          {id === 'sessions' && <MobileSessions route={route} visible={route.view === id} navigate={navigate} back={back} />}
          {id === 'files' && <MobileFiles route={route} notesPath={project.notes_path} visible={route.view === id} navigate={navigate} back={back} />}
          {id === 'git' && <MobileGit route={route} visible={route.view === id} navigate={navigate} back={back} />}
          {id === 'pull-requests' && <MobilePullRequests route={route} visible={route.view === id} navigate={navigate} back={back} />}
          {id === 'automations' && <MobileAutomations route={route} projectId={project.id} visible={route.view === id} navigate={navigate} back={back} />}
        </Suspense>
      </div>)}
    </div>
    <nav className="mobile-bottom-nav" aria-label="工作区导航">
      {navigation.map(({ id, label, icon: Icon }) => <button key={id} aria-label={label} title={label} aria-current={route.view === id ? 'page' : undefined}
      onClick={() => navigate({ workspace: worktree.path, view: id }, true)}><Icon size={28} /></button>)}</nav>
  </main>;
}

import { ArrowLeft, LoaderCircle, RefreshCw } from 'lucide-react';
import type { ReactNode } from 'react';

export function MobileState({ loading, error, empty, retry }: { loading?: boolean; error?: string; empty?: string; retry?: () => void }) {
  if (error) return <div className="mobile-state error" role="alert"><p>{error}</p><button className="mobile-button" onClick={retry}><RefreshCw size={16} />重新加载</button></div>;
  if (loading) return <div className="mobile-state" role="status"><LoaderCircle className="spinning" size={22} /><p>正在加载…</p></div>;
  return empty ? <div className="mobile-state"><p>{empty}</p></div> : null;
}

export function MobilePageHeader({ title, subtitle, back, actions }: { title: string; subtitle?: string; back?: () => void; actions?: ReactNode }) {
  return <header className="mobile-page-header">
    {back && <button className="mobile-icon-button" aria-label="返回" onClick={back}><ArrowLeft size={21} /></button>}
    <div className="mobile-heading"><h2>{title}</h2>{subtitle && <span>{subtitle}</span>}</div>
    {actions}
  </header>;
}

export function MobileRefresh({ reload, loading }: { reload: () => void; loading?: boolean }) {
  return <button className="mobile-icon-button" aria-label="刷新" disabled={loading} onClick={reload}><RefreshCw size={18} className={loading ? 'spinning' : ''} /></button>;
}

export function mobileTime(value: string) {
  return new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
}

